  endTime: { column: "end_time", coerce: (v) => (v ? v : null) },
  deliveryTolls: { column: "delivery_tolls", coerce: (v) => (v == null ? null : num(v, 0)) },
  destinationTolls: { column: "destination_tolls", coerce: (v) => (v == null ? null : num(v, 0)) },
