import React, { useState, useEffect } from "react";
import { Tag, ChevronLeft, ChevronRight, CheckCircle2, RefreshCw, Save, AlertCircle } from "lucide-react";
import { handleApiError } from "../../../../api";
import { useSafeNotification } from "../../../../hooks/useSafeNotification";
import {
  listMarketRates,
  saveMarketRates,
  marketRateNum,
  type MarketRateInput,
} from "../../services/marketRateService";

const SUMMARY_FIELDS = ["vij", "gun", "rp"] as const;
const TABLE_ONE_FIELDS = ["sneha", "vencobRate", "vencobVii", "vencobGun", "associationVii"] as const;
const TABLE_TWO_FIELDS = ["c17", "c15", "c13", "c12", "c10"] as const;
const ALL_FIELDS = [...SUMMARY_FIELDS, ...TABLE_ONE_FIELDS, ...TABLE_TWO_FIELDS] as const;

/** Local-timezone date formatter (business dates must never use toISOString,
 * which shifts dates by a day for non-UTC timezones). */
function formatLocalDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

/** Parse a YYYY-MM-DD business date as LOCAL midnight (never UTC). */
function parseLocalDate(dateStr: string): Date {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(dateStr).trim());
  if (!match) return new Date(dateStr);
  return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
}

export default function WeeklyMarketRates() {
  const { showNotification } = useSafeNotification();
  const [autoSaveStatus, setAutoSaveStatus] = useState<"Saved" | "Saving..." | "Error">("Saved");

  // Helper to get current Monday to Sunday dates (local, date-safe)
  const getCurrentWeekRange = (dateObj: Date = new Date()) => {
    const curr = new Date(dateObj);
    const day = curr.getDay();
    const diffToMonday = curr.getDate() - day + (day === 0 ? -6 : 1);

    const monday = new Date(curr.setDate(diffToMonday));
    const sunday = new Date(curr.setDate(monday.getDate() + 6));

    return { from: formatLocalDate(monday), to: formatLocalDate(sunday) };
  };

  const [currentDateObj, setCurrentDateObj] = useState(new Date());
  const [fromDate, setFromDate] = useState(getCurrentWeekRange().from);
  const [toDate, setToDate] = useState(getCurrentWeekRange().to);
  const [matrixDays, setMatrixDays] = useState<Array<{ label: string; dateStr: string }>>([]);

  // Persistent storage structure
  const [tableOneData, setTableOneData] = useState<Record<string, Record<string, string>>>({});
  const [tableTwoData, setTableTwoData] = useState<Record<string, Record<string, string>>>({});
  const [summaryData, setSummaryData] = useState<Record<string, Record<string, string>>>({});

  // Handle Weekly Shift
  const handleShiftTime = (direction: "prev" | "next") => {
    const newDate = new Date(currentDateObj);
    newDate.setDate(newDate.getDate() + (direction === "next" ? 7 : -7));
    setCurrentDateObj(newDate);
    const newRange = getCurrentWeekRange(newDate);
    setFromDate(newRange.from);
    setToDate(newRange.to);
  };

  useEffect(() => {
    const days = [];
    const current = parseLocalDate(fromDate);
    const end = parseLocalDate(toDate);

    while (current <= end) {
      const dayNum = current.getDate().toString();
      const dateStr = formatLocalDate(current);
      days.push({ label: dayNum, dateStr });
      current.setDate(current.getDate() + 1);
    }
    setMatrixDays(days);
  }, [fromDate, toDate]);

  // Load Market Rates from the PostgreSQL backend (never localStorage).
  useEffect(() => {
    let cancelled = false;
    setAutoSaveStatus("Saving...");
    void listMarketRates(fromDate, toDate)
      .then((rows) => {
        if (cancelled) return;
        const summary: Record<string, Record<string, string>> = {};
        const tableOne: Record<string, Record<string, string>> = {};
        const tableTwo: Record<string, Record<string, string>> = {};
        for (const row of rows) {
          const date = row.businessDate;
          summary[date] = {};
          for (const key of SUMMARY_FIELDS) summary[date][key] = String(row[key] ?? "");
          tableOne[date] = {};
          for (const key of TABLE_ONE_FIELDS) tableOne[date][key] = String(row[key] ?? "");
          tableTwo[date] = {};
          for (const key of TABLE_TWO_FIELDS) tableTwo[date][key] = String(row[key] ?? "");
        }
        setSummaryData(summary);
        setTableOneData(tableOne);
        setTableTwoData(tableTwo);
        setAutoSaveStatus("Saved");
      })
      .catch((err) => {
        if (cancelled) return;
        setAutoSaveStatus("Error");
        showNotification(`Unable to load market rates: ${handleApiError(err)}`, "error");
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fromDate, toDate]);

  const handleSave = async () => {
    const rows: MarketRateInput[] = [];
    for (const dayObj of matrixDays) {
      const date = dayObj.dateStr;
      const merged = {
        ...(summaryData[date] || {}),
        ...(tableOneData[date] || {}),
        ...(tableTwoData[date] || {}),
      };
      const hasAny = ALL_FIELDS.some((field) => String(merged[field] ?? "").trim() !== "");
      if (!hasAny) continue;
      const payload: MarketRateInput = { businessDate: date };
      for (const field of ALL_FIELDS) {
        if (String(merged[field] ?? "").trim() !== "") {
          payload[field] = marketRateNum(merged[field]);
        }
      }
      rows.push(payload);
    }
    if (rows.length === 0) {
      showNotification("Nothing to save. Enter at least one rate first.", "info");
      return;
    }
    setAutoSaveStatus("Saving...");
    try {
      const saved = await saveMarketRates(rows);
      const summary: Record<string, Record<string, string>> = {};
      const tableOne: Record<string, Record<string, string>> = {};
      const tableTwo: Record<string, Record<string, string>> = {};
      for (const row of saved) {
        const date = row.businessDate;
        summary[date] = {};
        for (const key of SUMMARY_FIELDS) summary[date][key] = String(row[key] ?? "");
        tableOne[date] = {};
        for (const key of TABLE_ONE_FIELDS) tableOne[date][key] = String(row[key] ?? "");
        tableTwo[date] = {};
        for (const key of TABLE_TWO_FIELDS) tableTwo[date][key] = String(row[key] ?? "");
      }
      setSummaryData(summary);
      setTableOneData(tableOne);
      setTableTwoData(tableTwo);
      setAutoSaveStatus("Saved");
      showNotification("Market rates saved successfully.", "success");
    } catch (err) {
      setAutoSaveStatus("Error");
      showNotification(`Unable to save market rates: ${handleApiError(err)}`, "error");
    }
  };

  const handleDataChange = (
    setter: React.Dispatch<React.SetStateAction<Record<string, Record<string, string>>>>,
    dateStr: string,
    field: string,
    value: string
  ) => {
    setter(prev => ({
      ...prev,
      [dateStr]: {
        ...(prev[dateStr] || {}),
        [field]: value,
      }
    }));
  };

  const renderTableTimeHeader = () => (
    <div className="flex items-center bg-slate-50 border border-slate-200 rounded-lg p-0.5 shadow-2xs">
      <button onClick={() => handleShiftTime("prev")} className="flex items-center gap-0.5 px-2 py-1 text-slate-600 hover:bg-white hover:text-slate-900 rounded font-medium text-xs transition-all border-r border-slate-200">
        <ChevronLeft size={13} /> <span>Prev Week</span>
      </button>
      <button onClick={() => handleShiftTime("next")} className="flex items-center gap-0.5 px-2 py-1 text-slate-600 hover:bg-white hover:text-slate-900 rounded font-medium text-xs transition-all">
        <span>Next Week</span> <ChevronRight size={13} />
      </button>
    </div>
  );

  return (
    <div className="space-y-4 bg-slate-50/50 p-4 rounded-xl border border-slate-200">
      <div className="flex items-center justify-between mb-2">
        <h2 className="text-lg font-bold text-slate-800">Weekly Market Rates</h2>
        <div className="flex items-center gap-3">
          <div className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg border font-medium ${
            autoSaveStatus === "Error"
              ? "text-red-700 bg-red-50 border-red-200"
              : "text-slate-600 bg-white border-slate-200"
          }`}>
            {autoSaveStatus === "Saving..." ? (
              <RefreshCw size={13} className="text-amber-500 animate-spin" />
            ) : autoSaveStatus === "Error" ? (
              <AlertCircle size={13} className="text-red-600" />
            ) : (
              <CheckCircle2 size={13} className="text-emerald-600" />
            )}
            <span>{autoSaveStatus === "Saving..." ? "Syncing..." : autoSaveStatus === "Error" ? "Failed to sync" : "Synced"}</span>
          </div>
          <button
            type="button"
            onClick={() => void handleSave()}
            disabled={autoSaveStatus === "Saving..."}
            className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-1.5 text-xs font-semibold transition-all disabled:opacity-60 disabled:cursor-not-allowed"
          >
            <Save size={13} /> Save
          </button>
          <div className="flex items-center gap-2 bg-white border border-slate-200 px-3 py-1.5 rounded-lg text-xs font-semibold text-slate-700">
            <span>{fromDate}</span> <span className="text-slate-400">to</span> <span>{toDate}</span>
          </div>
        </div>
      </div>

      {/* 1. Additional Metrics Entry */}
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden p-4">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Tag size={16} className="text-slate-500" />
            <h3 className="font-semibold text-slate-800 text-sm">Additional Metrics Entry (Vij, Gun, R.P)</h3>
          </div>
          {renderTableTimeHeader()}
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-center border border-slate-200 text-xs">
            <thead className="bg-slate-100">
              <tr className="text-slate-700 font-bold border-b border-slate-200">
                <th className="px-4 py-2 border-r border-slate-200 text-left">Date</th>
                <th className="px-4 py-2 border-r border-slate-200">Vij</th>
                <th className="px-4 py-2 border-r border-slate-200">Gun</th>
                <th className="px-4 py-2">R.P</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-slate-700">
              {matrixDays.map((dayObj) => {
                const rowData = summaryData[dayObj.dateStr] || {};
                return (
                  <tr key={dayObj.dateStr} className="hover:bg-slate-50">
                    <td className="px-4 py-2 border-r border-slate-100 text-left font-bold text-slate-900 bg-slate-50/50">{dayObj.dateStr}</td>
                    <td className="px-4 py-2 border-r border-slate-100">
                      <input type="text" inputMode="numeric" placeholder="0" value={rowData["vij"] || ""} onChange={(e) => handleDataChange(setSummaryData, dayObj.dateStr, "vij", e.target.value)} className="w-20 text-center px-2 py-1 border border-slate-200 rounded text-xs" />
                    </td>
                    <td className="px-4 py-2 border-r border-slate-100">
                      <input type="text" inputMode="numeric" placeholder="0" value={rowData["gun"] || ""} onChange={(e) => handleDataChange(setSummaryData, dayObj.dateStr, "gun", e.target.value)} className="w-20 text-center px-2 py-1 border border-slate-200 rounded text-xs" />
                    </td>
                    <td className="px-4 py-2">
                      <input type="text" inputMode="numeric" placeholder="0" value={rowData["rp"] || ""} onChange={(e) => handleDataChange(setSummaryData, dayObj.dateStr, "rp", e.target.value)} className="w-20 text-center px-2 py-1 border border-slate-200 rounded text-xs text-blue-600 font-medium" />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
        {/* 2. Company Rates Matrix Entry */}
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Tag size={16} className="text-slate-500" />
              <h3 className="font-semibold text-slate-800 text-sm">Company Rates Matrix Entry</h3>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-center border-collapse text-xs">
              <thead className="bg-slate-100">
                <tr className="text-slate-700 font-bold border-b border-slate-200">
                  <th className="px-2 py-2 text-left border-r border-slate-200">Date</th>
                  <th className="px-1 py-2 border-r border-slate-200">Sneha</th>
                  <th className="px-1 py-2 border-r border-slate-200">VenCob Rate</th>
                  <th className="px-1 py-2 border-r border-slate-200">VenCob Vii</th>
                  <th className="px-1 py-2 border-r border-slate-200">VenCob Gun</th>
                  <th className="px-1 py-2">Assoc Vii</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 text-slate-700">
                {matrixDays.map((dayObj) => {
                  const rowData = tableOneData[dayObj.dateStr] || {};
                  return (
                    <tr key={dayObj.dateStr} className="hover:bg-slate-50">
                      <td className="px-2 py-2 border-r border-slate-100 text-left font-bold text-slate-900 bg-slate-50/50">{dayObj.dateStr}</td>
                      {["sneha", "vencobRate", "vencobVii", "vencobGun", "associationVii"].map((colKey) => (
                        <td key={colKey} className="px-1 py-1 border-r border-slate-100">
                          <input type="text" inputMode="numeric" placeholder="0" value={rowData[colKey] || ""} onChange={(e) => handleDataChange(setTableOneData, dayObj.dateStr, colKey, e.target.value)} className="w-12 text-center px-1 py-1 border border-slate-200 rounded text-xs" />
                        </td>
                      ))}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {/* 3. Size & Category Breakdown Entry */}
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Tag size={16} className="text-slate-500" />
              <h3 className="font-semibold text-slate-800 text-sm">Size & Category Breakdown Entry</h3>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-center border-collapse text-xs">
              <thead className="bg-slate-100">
                <tr className="text-slate-700 font-bold border-b border-slate-200">
                  <th className="px-2 py-2 text-left border-r border-slate-200">Date</th>
                  <th className="px-1 py-2 border-r border-slate-200">17</th>
                  <th className="px-1 py-2 border-r border-slate-200">15</th>
                  <th className="px-1 py-2 border-r border-slate-200">13</th>
                  <th className="px-1 py-2 border-r border-slate-200">12</th>
                  <th className="px-1 py-2">10</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 text-slate-700">
                {matrixDays.map((dayObj) => {
                  const rowData = tableTwoData[dayObj.dateStr] || {};
                  return (
                    <tr key={dayObj.dateStr} className="hover:bg-slate-50">
                      <td className="px-2 py-2 border-r border-slate-100 text-left font-bold text-slate-900 bg-slate-50/50">{dayObj.dateStr}</td>
                      {["c17", "c15", "c13", "c12", "c10"].map((colKey) => (
                        <td key={colKey} className="px-1 py-1 border-r border-slate-100">
                          <input type="text" inputMode="numeric" placeholder="0" value={rowData[colKey] || ""} onChange={(e) => handleDataChange(setTableTwoData, dayObj.dateStr, colKey, e.target.value)} className="w-12 text-center px-1 py-1 border border-slate-200 rounded text-xs" />
                        </td>
                      ))}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

// src/modules/accounts/components/Summary/exportHelpers.ts

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { format } from 'date-fns';
import type { WeeklyMetrics, ExpenseBreakdown } from '../../types/summary.types';

// ---- Helpers ----
const formatCurrencyPlain = (amount: number): string => {
  return `Rs. ${new Intl.NumberFormat('en-IN', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount)}`;
};

const formatNumber = (num: number): string => {
  return new Intl.NumberFormat('en-IN').format(num);
};

const getTextWidth = (doc: jsPDF, text: string, fontSize: number): number => {
  doc.setFontSize(fontSize);
  const unitWidth = doc.getStringUnitWidth(text);
  return unitWidth * fontSize / 1.5;
};

// ---- PDF Export – A4 Portrait, Light Green, Neat & Professional ----
export const exportPDF = async (
  title: string,
  dateRange: string,
  weeklyGroups: { label: string }[],
  weeklyMetrics: WeeklyMetrics[],
  weeklyExpenses: ExpenseBreakdown[],
  totalMetrics: WeeklyMetrics,
  totalExpenses: ExpenseBreakdown,
  extra?: { totalDistanceKm?: number }
): Promise<void> => {
  const doc = new jsPDF('p', 'mm', 'a4');
  const margin = 12;
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  // Indian financial year (1 Apr → 31 Mar), not the calendar year: in Jan–Mar
  // the running FY started last calendar year.
  const nowFyStart = new Date().getMonth() >= 3 ? new Date().getFullYear() : new Date().getFullYear() - 1;
  const fy = `Financial Year: ${nowFyStart}-${nowFyStart + 1}`;

  // Colors – soft light green theme
  const greenHeaderBg: [number, number, number] = [222, 247, 231]; // emerald-50 light
  const greenHeaderText: [number, number, number] = [22, 101, 52]; // green-800
  const greenAccent: [number, number, number] = [16, 185, 129]; // emerald-500
  const borderGrey: [number, number, number] = [226, 232, 240]; // slate-200
  const slate700: [number, number, number] = [51, 65, 85];

  // ─── Header banner ───────────────────────────────────────────────
  // Light green top bar
  doc.setFillColor(greenHeaderBg[0], greenHeaderBg[1], greenHeaderBg[2]);
  doc.roundedRect(margin, 10, pageWidth - margin * 2, 18, 2, 2, 'F');
  // Accent left border
  doc.setFillColor(greenAccent[0], greenAccent[1], greenAccent[2]);
  doc.roundedRect(margin, 10, 3, 18, 1, 1, 'F');

  doc.setFontSize(13);
  doc.setTextColor(greenHeaderText[0], greenHeaderText[1], greenHeaderText[2]);
  doc.setFont('helvetica', 'bold');
  doc.text(title, margin + 6, 18);

  doc.setFontSize(7.5);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text(`Period: ${dateRange}    •    ${fy}`, margin + 6, 24);

  // Generated small on right
  doc.setFontSize(6.5);
  doc.setTextColor(148, 163, 184);
  const genText = `Generated: ${format(new Date(), 'dd MMM yyyy, hh:mm a')}`;
  doc.text(genText, pageWidth - margin - 2 - 40, 18);

  // ─── KPI cards below header (light, simple) ─────────────────────
  const totalExpenseVal = Object.values(totalExpenses).reduce((a, b) => a + b, 0);
  const totalWeight = (totalMetrics as any).weight || 0;
  const totalDistance = extra?.totalDistanceKm ?? 0;
  const costPerKg = totalWeight > 0 ? totalExpenseVal / totalWeight : 0;
  const costPerKm = totalDistance > 0 ? totalExpenseVal / totalDistance : 0;

  const kpiY = 32;
  const kpiGap = 4;
  const kpiW = (pageWidth - margin * 2 - kpiGap) / 2;
  const kpiH = 18;

  const drawKpi = (x: number, label: string, value: string, sub: string) => {
    // card
    doc.setDrawColor(borderGrey[0], borderGrey[1], borderGrey[2]);
    doc.setFillColor(255, 255, 255);
    doc.setLineWidth(0.2);
    doc.roundedRect(x, kpiY, kpiW, kpiH, 2, 2, 'FD');
    // subtle emerald top accent
    doc.setFillColor(greenAccent[0], greenAccent[1], greenAccent[2]);
    doc.roundedRect(x, kpiY, kpiW, 1.2, 1, 1, 'F');
    // icon circle (light green)
    const iconX = x + 4;
    const iconY = kpiY + 5.5;
    doc.setFillColor(220, 252, 231);
    doc.setDrawColor(187, 247, 208);
    doc.circle(iconX + 3, iconY, 3, 'FD');
    doc.setFontSize(6);
    doc.setTextColor(greenHeaderText[0], greenHeaderText[1], greenHeaderText[2]);
    doc.setFont('helvetica', 'bold');
    doc.text(label === 'COST / KG' ? 'Kg' : 'Km', iconX + 1.6, iconY + 1, { align: 'center' } as any);
    // label
    doc.setFontSize(6.5);
    doc.setTextColor(71, 85, 105);
    doc.setFont('helvetica', 'bold');
    doc.text(label, x + 11, kpiY + 6);
    doc.setFontSize(6);
    doc.setTextColor(148, 163, 184);
    doc.setFont('helvetica', 'normal');
    doc.text(sub, x + 11, kpiY + 9.5);
    // value
    doc.setFontSize(11);
    doc.setTextColor(15, 23, 42);
    doc.setFont('helvetica', 'bold');
    doc.text(value, x + 11, kpiY + 15);
    // unit badge
    const badge = label === 'COST / KG' ? '₹/KG' : '₹/KM';
    doc.setFontSize(5.5);
    doc.setFillColor(241, 245, 249);
    doc.setDrawColor(226, 232, 240);
    const badgeW = 12;
    const badgeX = x + kpiW - badgeW - 3;
    doc.roundedRect(badgeX, kpiY + 3.5, badgeW, 4.5, 1, 1, 'FD');
    doc.setTextColor(71, 85, 105);
    doc.setFont('helvetica', 'bold');
    doc.text(badge, badgeX + badgeW / 2, kpiY + 6.5, { align: 'center' } as any);
  };

  drawKpi(margin, 'COST / KG', formatCurrencyPlain(costPerKg), `${totalWeight.toFixed(2)} kg  •  ${formatNumber((totalMetrics as any).birds || 0)} birds`);
  drawKpi(margin + kpiW + kpiGap, 'COST / KM', formatCurrencyPlain(costPerKm), `${totalDistance.toFixed(1)} km  •  ${(totalMetrics as any).trips || 0} trips`);

  // ─── Determine column widths for A4 portrait ─────────────────────
  const numDataCols = weeklyGroups.length;
  const headerFontSize = 6.5;
  const bodyFontSize = 6.5;

  let maxLabelWidth = 0;
  weeklyGroups.forEach(g => {
    const w = getTextWidth(doc, g.label, headerFontSize);
    if (w > maxLabelWidth) maxLabelWidth = w;
  });
  const dataColWidth = Math.min(Math.max(maxLabelWidth + 6, 22), 36);
  const firstColWidth = 38;
  const totalColWidth = 22;
  const available = pageWidth - margin * 2 - firstColWidth - totalColWidth;
  let finalDataColWidth = dataColWidth;
  if (numDataCols > 0) {
    const needed = numDataCols * dataColWidth;
    if (needed > available) {
      finalDataColWidth = Math.max(16, available / numDataCols);
    }
  }

  const colWidths = [firstColWidth];
  for (let i = 0; i < numDataCols; i++) colWidths.push(finalDataColWidth);
  colWidths.push(totalColWidth);

  const columnStyles = colWidths.reduce((acc, w, idx) => {
    acc[idx] = { cellWidth: w };
    return acc;
  }, {} as any);

  // ─── Summary Table ──────────────────────────────────────────────
  const summaryHeaders = ['Particulars', ...weeklyGroups.map(g => g.label), 'Total'];

  const summaryRows: any[][] = [
    { key: 'trips', label: 'No. of Trips' },
    { key: 'birds', label: 'No. of Birds' },
    { key: 'weight', label: 'Birds in KG' },
    { key: 'mortality', label: 'Mortality (Birds)' },
    { key: 'weightLoss', label: 'Weight Loss (KG)' },
    { key: 'sales', label: 'Sales Amount (Rs.)' },
    { key: 'collection', label: 'Collection Amount (Rs.)' },
    { key: 'pending', label: 'Pending Collection (Rs.)' },
  ].map(item => {
    const row: any[] = [item.label];
    weeklyMetrics.forEach(m => {
      const val = (m[item.key as keyof WeeklyMetrics] as number) || 0;
      if (item.key === 'sales' || item.key === 'collection' || item.key === 'pending') {
        row.push(formatCurrencyPlain(val));
      } else if (item.key === 'weight' || item.key === 'weightLoss') {
        row.push(val.toFixed(2));
      } else {
        row.push(formatNumber(val));
      }
    });
    const totalVal = (totalMetrics[item.key as keyof WeeklyMetrics] as number) || 0;
    if (item.key === 'sales' || item.key === 'collection' || item.key === 'pending') {
      row.push(formatCurrencyPlain(totalVal));
    } else if (item.key === 'weight' || item.key === 'weightLoss') {
      row.push(totalVal.toFixed(2));
    } else {
      row.push(formatNumber(totalVal));
    }
    return row;
  });

  autoTable(doc, {
    head: [summaryHeaders],
    body: summaryRows,
    startY: kpiY + kpiH + 6,
    margin: { left: margin, right: margin },
    theme: 'grid',
    styles: {
      fontSize: bodyFontSize,
      cellPadding: { top: 1.6, bottom: 1.6, left: 2, right: 2 },
      textColor: slate700 as any,
      lineColor: borderGrey as any,
      lineWidth: 0.12,
      valign: 'middle',
    },
    headStyles: {
      fillColor: greenHeaderBg as any,
      textColor: greenHeaderText as any,
      fontStyle: 'bold',
      halign: 'center',
      valign: 'middle',
      fontSize: headerFontSize,
      cellPadding: { top: 2, bottom: 2, left: 2, right: 2 },
    },
    columnStyles: columnStyles,
    alternateRowStyles: { fillColor: [248, 250, 252] as any },
    didParseCell: (data) => {
      if (data.section === 'head' && data.column.index === 0) {
        data.cell.styles.halign = 'left';
      }
      if (data.section === 'body' && data.column.index === 0) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [248, 250, 252] as any;
        data.cell.styles.textColor = [51, 65, 85] as any;
      }
      if (data.section === 'body' && data.column.index > 0) {
        data.cell.styles.halign = 'right';
      }
      // Total column emphasis
      if (data.column.index === colWidths.length - 1) {
        data.cell.styles.fillColor = [240, 253, 244] as any;
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.textColor = [22, 101, 52] as any;
      }
    },
    didDrawPage: (data) => {
      // footer line
      doc.setFontSize(6);
      doc.setTextColor(148, 163, 184);
      doc.setFont('helvetica', 'normal');
      const str = `Page ${data.pageNumber}  •  DMR Poultries – Business Summary`;
      doc.text(str, pageWidth / 2, pageHeight - 6, { align: 'center' } as any);
    },
  });

  const finalY = (doc as any).lastAutoTable.finalY + 6;

  // ─── Expenses Table ─────────────────────────────────────────────
  // Section title
  doc.setFontSize(8);
  doc.setTextColor(greenHeaderText[0], greenHeaderText[1], greenHeaderText[2]);
  doc.setFont('helvetica', 'bold');
  doc.text('EXPENSES BREAKDOWN', margin, finalY);
  doc.setDrawColor(greenAccent[0], greenAccent[1], greenAccent[2]);
  doc.setLineWidth(0.4);
  doc.line(margin, finalY + 1.2, margin + 36, finalY + 1.2);

  const expenseHeaders = ['Expense', ...weeklyGroups.map(g => g.label), 'Total'];

  const expenseRows: any[][] = [
    { key: 'farm', label: 'Farm Payment (Rs.)' },
    { key: 'fuel', label: 'Fuel Payment (Rs.)' },
    { key: 'trip', label: 'Trip Expenses (Rs.)' },
    { key: 'salary', label: 'Salaries (Rs.)' },
    { key: 'maintenance', label: 'Vehicle Maintenance (Rs.)' },
    { key: 'office', label: 'Office & Other Expenses (Rs.)' },
  ].map(item => {
    const row: any[] = [item.label];
    weeklyExpenses.forEach(w => {
      const val = (w[item.key as keyof ExpenseBreakdown] as number) || 0;
      row.push(formatCurrencyPlain(val));
    });
    const totalVal = (totalExpenses[item.key as keyof ExpenseBreakdown] as number) || 0;
    row.push(formatCurrencyPlain(totalVal));
    return row;
  });

  const totalExpRow: any[] = ['Total Expenses (Rs.)'];
  weeklyExpenses.forEach(w => {
    const sum = Object.values(w).reduce((a, b) => a + b, 0);
    totalExpRow.push(formatCurrencyPlain(sum));
  });
  totalExpRow.push(formatCurrencyPlain(Object.values(totalExpenses).reduce((a, b) => a + b, 0)));

  expenseRows.push(totalExpRow);

  autoTable(doc, {
    head: [expenseHeaders],
    body: expenseRows,
    startY: finalY + 4,
    margin: { left: margin, right: margin },
    theme: 'grid',
    styles: {
      fontSize: bodyFontSize,
      cellPadding: { top: 1.6, bottom: 1.6, left: 2, right: 2 },
      textColor: slate700 as any,
      lineColor: borderGrey as any,
      lineWidth: 0.12,
      valign: 'middle',
    },
    headStyles: {
      fillColor: greenHeaderBg as any,
      textColor: greenHeaderText as any,
      fontStyle: 'bold',
      halign: 'center',
      valign: 'middle',
      fontSize: headerFontSize,
      cellPadding: { top: 2, bottom: 2, left: 2, right: 2 },
    },
    columnStyles: columnStyles,
    alternateRowStyles: { fillColor: [248, 250, 252] as any },
    didParseCell: (data) => {
      if (data.section === 'body' && data.column.index === 0) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [248, 250, 252] as any;
      }
      if (data.section === 'body' && data.column.index > 0) {
        data.cell.styles.halign = 'right';
      }
      if (data.column.index === colWidths.length - 1) {
        data.cell.styles.fillColor = [240, 253, 244] as any;
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.textColor = [22, 101, 52] as any;
      }
      if (data.section === 'body' && data.row.index === expenseRows.length - 1) {
        data.cell.styles.fillColor = [240, 253, 244];
        data.cell.styles.fontStyle = 'bold';
      }
    },
  });

  // ─── Footer note below tables ───────────────────────────────────
  const finalY2 = (doc as any).lastAutoTable.finalY + 7;
  // Light note box
  doc.setFillColor(248, 250, 252);
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(margin, finalY2, pageWidth - margin * 2, 8, 1.5, 1.5, 'FD');
  doc.setFontSize(6.5);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'italic');
  doc.text('All amounts are calculated based on the selected date range.  •  Cost/KG = Total Expense ÷ Total Weight  •  Cost/KM = Total Expense ÷ Total Distance', margin + 3, finalY2 + 5);

  doc.save(`${title.replace(/\s/g, '_')}_${format(new Date(), 'yyyy-MM-dd')}.pdf`);
};

// ---- Excel Export – Unchanged + includes Weight Loss ----
export const exportExcel = (
  title: string,
  dateRange: string,
  weeklyGroups: { label: string }[],
  weeklyMetrics: WeeklyMetrics[],
  weeklyExpenses: ExpenseBreakdown[],
  totalMetrics: WeeklyMetrics,
  totalExpenses: ExpenseBreakdown
): void => {
  const wb = XLSX.utils.book_new();
  const wsData: any[][] = [];

  // Header
  wsData.push([title]);
  const xlFyStart = new Date().getMonth() >= 3 ? new Date().getFullYear() : new Date().getFullYear() - 1;
  wsData.push([`Period: ${dateRange}  |  Financial Year: ${xlFyStart}-${xlFyStart + 1}`]);
  wsData.push([]);

  // Summary Table
  wsData.push(['BUSINESS SUMMARY']);
  const summaryHeaders = ['Particulars', ...weeklyGroups.map(g => g.label), 'Total'];
  wsData.push(summaryHeaders);

  const summaryRows = [
    { key: 'trips', label: 'No. of Trips' },
    { key: 'birds', label: 'No. of Birds' },
    { key: 'weight', label: 'Birds in KG' },
    { key: 'mortality', label: 'Mortality (Birds)' },
    { key: 'weightLoss', label: 'Weight Loss (KG)' },
    { key: 'sales', label: 'Sales Amount (₹)' },
    { key: 'collection', label: 'Collection Amount (₹)' },
    { key: 'pending', label: 'Pending Collection (₹)' },
  ].map(item => {
    const row: any[] = [item.label];
    weeklyMetrics.forEach(m => {
      const val = (m[item.key as keyof WeeklyMetrics] as number) || 0;
      if (item.key === 'sales' || item.key === 'collection' || item.key === 'pending') {
        row.push(Number(val.toFixed(2)));
      } else if (item.key === 'weight' || item.key === 'weightLoss') {
        row.push(Number(val.toFixed(2)));
      } else {
        row.push(val);
      }
    });
    const totalVal = (totalMetrics[item.key as keyof WeeklyMetrics] as number) || 0;
    if (item.key === 'sales' || item.key === 'collection' || item.key === 'pending') {
      row.push(Number(totalVal.toFixed(2)));
    } else if (item.key === 'weight' || item.key === 'weightLoss') {
      row.push(Number(totalVal.toFixed(2)));
    } else {
      row.push(totalVal);
    }
    return row;
  });
  summaryRows.forEach(row => wsData.push(row));

  wsData.push([]);

  // Expenses Table
  wsData.push(['EXPENSES']);
  const expenseHeaders = ['Expense', ...weeklyGroups.map(g => g.label), 'Total'];
  wsData.push(expenseHeaders);

  const expenseRows = [
    { key: 'farm', label: 'Farm Payment (₹)' },
    { key: 'fuel', label: 'Fuel Payment (₹)' },
    { key: 'trip', label: 'Trip Expenses (₹)' },
    { key: 'salary', label: 'Salaries (₹)' },
    { key: 'maintenance', label: 'Vehicle Maintenance (₹)' },
    { key: 'office', label: 'Office & Other Expenses (₹)' },
  ].map(item => {
    const row: any[] = [item.label];
    weeklyExpenses.forEach(w => {
      const val = (w[item.key as keyof ExpenseBreakdown] as number) || 0;
      row.push(Number(val.toFixed(2)));
    });
    const totalVal = (totalExpenses[item.key as keyof ExpenseBreakdown] as number) || 0;
    row.push(Number(totalVal.toFixed(2)));
    return row;
  });

  // Total Expenses row
  const totalExpRow: any[] = ['Total Expenses (₹)'];
  weeklyExpenses.forEach(w => {
    const sum = Object.values(w).reduce((a, b) => a + b, 0);
    totalExpRow.push(Number(sum.toFixed(2)));
  });
  totalExpRow.push(Number(Object.values(totalExpenses).reduce((a, b) => a + b, 0).toFixed(2)));
  expenseRows.push(totalExpRow);

  expenseRows.forEach(row => wsData.push(row));

  // KPI below
  wsData.push([]);
  const totalExpenseVal = Object.values(totalExpenses).reduce((a, b) => a + b, 0);
  const costPerKg = (totalMetrics as any).weight ? totalExpenseVal / (totalMetrics as any).weight : 0;
  wsData.push(['KPI']);
  wsData.push(['Cost / KG (Rs.)', Number(costPerKg.toFixed(2))]);
  // distance KPI needs distance – leave blank if not available via this export path; callee can extend

  wsData.push([]);
  wsData.push([`Generated on: ${new Date().toLocaleString()}`]);
  wsData.push(['All amounts are calculated based on the selected date range.']);

  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Set column widths
  ws['!cols'] = [{ wch: 30 }, ...weeklyGroups.map(() => ({ wch: 18 })), { wch: 15 }];

  XLSX.utils.book_append_sheet(wb, ws, 'Business Summary');
  XLSX.writeFile(wb, `${title.replace(/\s/g, '_')}_${format(new Date(), 'yyyy-MM-dd')}.xlsx`);
};

// src/modules/accounts/components/payment-book/PaymentViewModal.tsx
//
// The read-only twin of the entry sheet: same section rules, same field
// shells, same type/mode marks — so opening a record and editing it feel like
// one screen rather than two products.

import type { ReactNode } from 'react';
import { BadgeCheck, CalendarDays, FileText, IndianRupee, Paperclip, Pencil, ScrollText, UserRound } from 'lucide-react';
import type { Payment } from '../../types/payment.types';
import { Modal } from '../../../../ui/Modal';
import { Button } from '../../../../ui/Button';
import { StatusBadge } from '../../../../ui/StatusBadge';
import { MasterSectionHeading } from '../../../masters/components/MasterForm';
import { useI18n } from '../../../../i18n';
import { localizePaymentType, paymentCurrency, paymentNoDisplay } from '../../utils/paymentRegister';
import { inrInWords } from '../../utils/inrInWords';
import { PaymentModeMark, PaymentTypeMark } from './PaymentGlyphMarks';

interface PaymentViewModalProps {
  isOpen: boolean;
  payment: Payment | null;
  onClose: () => void;
  /**
   * Jump straight from the sheet into the edit dialog. Omitted when the caller
   * has no edit flow, in which case nothing edit-related is rendered.
   */
  onEdit?: () => void;
  /** False keeps the edit affordances visible but disabled, with `editHint`. */
  canEdit?: boolean;
  /** Why editing is unavailable — shown as text beside the disabled control. */
  editHint?: string;
}

// Stored statuses read through the shared status dictionary.
const statusLabelKey = (status: Payment['status']) =>
  status === 'Approved' ? 'status.approved' : status === 'Cancelled' ? 'status.cancelled' : 'status.pending';

/** Linked trip lines used to live in localStorage farm payments; Payment
 *  Register rows from the API do not carry that join, so the view shows none. */
const getTripDetails = (_payment: Payment): { tripNo: string; amount: number }[] => [];

const timestamp = (value: string) => {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '—' : date.toLocaleString('en-IN');
};

/**
 * Read-only counterpart of the entry sheet's field: label above, value in a
 * shell. Payment Type and Mode pass no `icon`: their value already carries a
 * mark, and a field showing two icons for one thing reads as a bug.
 */
function DetailField({ label, icon, children }: { label: string; icon?: ReactNode; children: ReactNode }) {
  return (
    <div className="min-w-0">
      <p className="mb-1 text-xs font-semibold text-slate-600">{label}</p>
      <div className="flex min-h-9 items-center gap-2 rounded-xl border border-slate-200 bg-slate-50/70 px-2.5 py-1.5 text-sm font-medium text-slate-800">
        {icon ? <span aria-hidden="true" className="shrink-0 text-slate-400">{icon}</span> : null}
        <span className="min-w-0 flex-1">{children}</span>
      </div>
    </div>
  );
}

const EMPTY = <span className="font-normal text-slate-400">—</span>;

export function PaymentViewModal({ isOpen, payment, onClose, onEdit, canEdit = false, editHint }: PaymentViewModalProps) {
  const { t } = useI18n();
  if (!isOpen || !payment) return null;
  const tripDetails = getTripDetails(payment);
  const inWords = inrInWords(Number(payment.amount) || 0);
  const dateShown = payment.paymentDate.slice(0, 10).split('-').reverse().join('/');
  // Only a pending (Draft) record can still be edited, so the edit symbol is
  // tied to that state rather than shown on every sheet.
  const pending = payment.status === 'Draft';
  const showEdit = pending && Boolean(onEdit);

  return (
    <Modal isOpen onClose={onClose} title={t('accounts.payment.view_title')} description={paymentNoDisplay(payment.paymentNo) || t('accounts.payment.no_payment_no')} size="xl"
      footer={<>
        {/* A disabled button alone reads as a bug, so the reason is stated next
            to it: the row simply is not in an editable state. */}
        {showEdit && !canEdit && <p className="mr-auto text-[11px] leading-4 text-slate-500">{editHint}</p>}
        <Button variant="secondary" onClick={onClose}>{t('common.close')}</Button>
        {showEdit && (
          <Button icon={<Pencil size={14} />} disabled={!canEdit} onClick={onEdit}>{t('accounts.payment.edit_payment')}</Button>
        )}
      </>}>
      <div className="space-y-4">
        {/* FIGURE — accent bar, the amount, and the state it is in. Editing lives
            in the footer, next to Close, so there is exactly one edit control. */}
        <div className="relative overflow-hidden rounded-xl border border-emerald-100 bg-gradient-to-br from-emerald-50/70 via-white to-white px-4 py-3.5">
          <span aria-hidden="true" className="absolute inset-y-0 left-0 w-[3px] bg-emerald-400/80" />
          <div className="flex flex-wrap items-start justify-between gap-3 pl-2">
            <div className="min-w-0">
              <p className="text-[11px] font-semibold uppercase tracking-wider text-emerald-800/60">{t('accounts.payment.amount_paid')}</p>
              <p className="mt-0.5 text-[26px] font-semibold leading-tight tabular-nums text-slate-900">{paymentCurrency.format(payment.amount)}</p>
              {inWords && <p className="mt-1 text-[11px] italic leading-snug text-emerald-900/70">{inWords}</p>}
            </div>
            <StatusBadge status={payment.status} label={t(statusLabelKey(payment.status))} tone={pending ? 'warning' : undefined} size="md" className="shrink-0" />
          </div>
        </div>

        {/* PAYMENT — type and mode bring their own mark, so no field icon. */}
        <section className="space-y-2.5">
          <MasterSectionHeading>{t('accounts.payment.section_payment')}</MasterSectionHeading>
          <div className="grid grid-cols-1 gap-3 md:grid-cols-4">
            <DetailField label={t('accounts.payment.col_date')} icon={<CalendarDays size={14} />}><span className="tabular-nums">{dateShown}</span></DetailField>
            <DetailField label={t('accounts.payment.type')}><PaymentTypeMark type={payment.paymentType} label={localizePaymentType(payment.paymentType, t)} /></DetailField>
            <DetailField label={t('accounts.payment.mode')}>{payment.paymentMode ? <PaymentModeMark mode={payment.paymentMode} /> : EMPTY}</DetailField>
            <DetailField label={t('accounts.payment.field_category')} icon={<IndianRupee size={14} />}>{payment.category || EMPTY}</DetailField>
          </div>
        </section>

        {/* PAYEE & PAPER TRAIL */}
        <section className="space-y-2.5">
          <MasterSectionHeading>{t('accounts.payment.payee_heading')}</MasterSectionHeading>
          <div className="grid grid-cols-1 gap-3 md:grid-cols-12">
            <div className="md:col-span-5">
              <DetailField label={t('accounts.payment.col_paid_to')} icon={<UserRound size={14} />}>{payment.paidTo || EMPTY}</DetailField>
            </div>
            <div className="md:col-span-4">
              <DetailField label={t('accounts.payment.col_reference')} icon={<ScrollText size={14} />}>
                <span className="uppercase tracking-tight">{payment.referenceNo || '—'}</span>
              </DetailField>
            </div>
            <div className="md:col-span-3">
              <DetailField label={t('accounts.payment.field_recorded_by')} icon={<BadgeCheck size={14} />}>{payment.createdBy || EMPTY}</DetailField>
            </div>
          </div>
        </section>

        {tripDetails.length > 0 && <section className="space-y-2.5">
          <MasterSectionHeading>{t('accounts.payment.trips_settled', { n: tripDetails.length })}</MasterSectionHeading>
          <div className="divide-y divide-slate-100 overflow-hidden rounded-xl border border-slate-200">
            {tripDetails.map((trip, index) => <div key={`${trip.tripNo}-${index}`} className="flex flex-wrap items-center justify-between gap-2 bg-white px-3 py-2 text-sm">
              <span className="font-medium text-slate-700">{trip.tripNo}</span>
              <span className="tabular-nums text-slate-600">{paymentCurrency.format(trip.amount)}</span>
            </div>)}
            <div className="flex flex-wrap items-center justify-between gap-2 bg-slate-50/70 px-3 py-2 text-sm font-semibold text-slate-800">
              <span>{t('accounts.payment.total_trip_amount')}</span>
              <span className="tabular-nums text-slate-600">{paymentCurrency.format(tripDetails.reduce((sum, trip) => sum + trip.amount, 0))}</span>
            </div>
          </div>
        </section>}

        {/* NOTE + FILES */}
        <section className="space-y-2.5">
          <MasterSectionHeading>{t('accounts.payment.note_files_heading')}</MasterSectionHeading>
          <div className="grid grid-cols-1 gap-3 md:grid-cols-12">
            <div className="md:col-span-8">
              <DetailField label={t('accounts.payment.field_remarks')} icon={<FileText size={14} />}>
                {payment.remarks ? <span className="block whitespace-pre-wrap break-words text-sm font-normal text-slate-700">{payment.remarks}</span> : <span className="text-sm font-normal text-slate-400">{t('accounts.payment.no_note')}</span>}
              </DetailField>
            </div>
            <div className="md:col-span-4">
              <DetailField label={t('accounts.payment.field_attachments')} icon={<Paperclip size={14} />}>
                {payment.attachments.length === 0
                  ? <span className="text-sm font-normal text-slate-400">{t('accounts.payment.no_files')}</span>
                  : (
                    <ul className="space-y-0.5 text-sm font-normal">
                      {payment.attachments.map(file => <li key={file.id}>
                        <a href={file.fileUrl} target="_blank" rel="noreferrer" className="text-emerald-700 underline decoration-emerald-300 underline-offset-2 hover:text-emerald-800">{file.fileName}</a>
                      </li>)}
                    </ul>
                  )}
              </DetailField>
            </div>
          </div>
        </section>

        <div className="flex flex-wrap justify-between gap-2 border-t border-slate-100 pt-3 text-[11px] text-slate-500">
          <span>{t('accounts.payment.created')} {timestamp(payment.createdAt)}</span>
          <span>{t('accounts.payment.updated')} {timestamp(payment.updatedAt)}</span>
        </div>
      </div>
    </Modal>
  );
}

