          {/* Bill Number & Current KM Row */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('fleet.maintenance_view.bill_number')}</p>
              <p className={`text-sm font-bold ${isApproved ? 'text-green-600' : 'text-orange-500'}`}>
                {bill.billNumber || '-'}
                {isApproved && (
                  <span className="ml-2 inline-flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 text-xs font-semibold rounded-full">
                    <span className="w-1.5 h-1.5 rounded-full bg-green-500" />
                    {translateStatus(t, 'Approved')}
                  </span>
                )}
              </p>
            </div>
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('fleet.maintenance_form.current_km')}</p>
              <p className="text-sm font-bold text-slate-800">{bill.currentKM.toLocaleString()}</p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('common.driver')}</p>
              <p className="text-sm text-slate-700">{bill.driverName || '-'}</p>
            </div>
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('fleet.maintenance_form.next_service_km')}</p>
              <p className="text-sm font-bold text-slate-800">{bill.nextServiceKM ? bill.nextServiceKM.toLocaleString() : '-'}</p>
            </div>
          </div>

          {/* Maintenance Type & Service Type Row */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('operations.maintenance_type')}</p>
              <p className="text-sm text-slate-700">{bill.maintenanceType}</p>
            </div>
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('fleet.maintenance_form.service_type')}</p>
              <p className="text-sm text-slate-700">{bill.serviceType}</p>
            </div>
          </div>

          {/* Garage & Mechanic Row */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('operations.maintenance_garage')}</p>
              <p className="text-sm text-slate-700">{bill.garage || '-'}</p>
            </div>
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('fleet.maintenance_form.mechanic')}</p>
              <p className="text-sm text-slate-700">{bill.mechanic || '-'}</p>
            </div>
          </div>

          {/* Parts Table */}
          {bill.parts && bill.parts.length > 0 && (
            <div className="border-t border-slate-200 pt-4">
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3">{t('fleet.maintenance_view.parts_title')}</p>
              <div className="overflow-x-auto rounded-lg border border-slate-200">
                <table className="min-w-full divide-y divide-slate-200">
                  <thead className="bg-slate-50">
                    <tr>
                      <th className="px-4 py-2 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">{t('fleet.parts.item_name')}</th>
                      <th className="px-4 py-2 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">{t('fleet.parts.qty')}</th>
                      <th className="px-4 py-2 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">{t('common.amount')}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200 bg-white">
                    {bill.parts.map((part, index) => (
                      <tr key={index}>
                        <td className="px-4 py-2 text-sm text-slate-700">{part.name}</td>
                        <td className="px-4 py-2 text-sm text-slate-700 text-center">{part.quantity}</td>
                        <td className="px-4 py-2 text-sm font-medium text-slate-700 text-right">
                          ₹{part.amount.toFixed(2)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot className="bg-slate-50 border-t border-slate-200">
                    <tr>
                      <td colSpan={2} className="px-4 py-2 text-sm font-bold text-slate-700 text-right">{t('common.total')}</td>
                      <td className="px-4 py-2 text-sm font-bold text-blue-600 text-right">
                        ₹{bill.totalCost.toFixed(2)}
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          )}

          {/* Total Cost (if no parts) */}
          {(!bill.parts || bill.parts.length === 0) && (
            <div className="border-t border-slate-200 pt-4 flex justify-between items-center">
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('fleet.parts.total_cost')}</p>
              <p className="text-xl font-bold text-blue-600">₹{bill.totalCost.toFixed(2)}</p>
            </div>
          )}

          {/* Bill / Spare-part Documents */}
          {bill.documents && bill.documents.length > 0 && (
            <div className="border-t border-slate-200 pt-4">
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3">
                {t('fleet.maintenance_view.documents_count', { count: bill.documents.length })}
              </p>
              <MaintenanceDocuments maintenanceId={bill.id || ''} documents={bill.documents} />
            </div>
          )}

          {/* Remarks */}
          {bill.remarks && (
            <div className="border-t border-slate-200 pt-4">
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{t('common.remarks')}</p>
              <p className="text-sm text-slate-600 italic bg-slate-50 p-2 rounded-lg mt-1">{bill.remarks}</p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex justify-end px-6 py-4 border-t border-slate-200 bg-slate-50/50 rounded-b-2xl">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-700 font-semibold rounded-lg transition-colors text-sm"
          >
            {t('common.close')}
          </button>
        </div>
      </div>
    </div>
  );
};

export default BillDetailsModal;

import { memo, useState, useMemo, useEffect, useRef } from 'react';
import {
  Trash2, CheckCircle2,
  Search, Paperclip, Hash, Calendar, Wrench, Store, User, Gauge, Clock, Wallet, History, X, RotateCcw, ListOrdered
} from 'lucide-react';
import { useI18n, translateStatus } from '../../../../i18n';
import MasterDropdown from '../../../masters/components/MasterDropdown';
import { MAINTENANCE_TYPES } from '../../utils/constants';
// Recent-Trip-Activity chrome + global pagination standard.
import { Pagination } from '../../../../ui';
import { BrandRefreshButton } from '../../../../ui';
import { uiActionIconMotionClass } from '../../../../shared/ui/uiTokens';
import { shouldShowPagination, PAGINATION_DEFAULT_PAGE_SIZE } from '../../../../shared/ui/paginationStyles';
import { formatTripListDay } from '../../../operations/vehicle-trips/utils/formatTripListDay';
import { formatVehicleNumber } from "../../../../utils/format";
import { localizeMaintenanceText, localizeMaintenanceName } from '../../utils/maintenanceLocalization';
import { usePendingDelete } from '../../../../hooks/usePendingDelete';
import { PendingDeleteNotification } from '../../../../components/common/PendingDeleteNotification';
import type { MaintenanceEvent } from '../../types';

export type ViewMode = 'pending' | 'approved' | 'deleted';

interface LatestMaintenanceTableProps {
  records: MaintenanceEvent[];
  vehicles: any[];
  viewMode: ViewMode;
  onView: (record: MaintenanceEvent) => void;
  /** Optional: entry-only roles never receive approve/delete affordances. */
  onDelete?: (record: MaintenanceEvent) => void;
  onApprove?: (record: MaintenanceEvent) => void;
  /** Refresh the records from the API — BrandRefreshButton beside the search. */
  onRefresh?: () => void;
  /** True while the API load/refresh is in flight → spinner row, frozen pager. */
  isLoading?: boolean;
  currentPage: number;
  onPageChange: (page: number) => void;
  pageSize?: number;
  onPageSizeChange?: (pageSize: number) => void;
  onToggleView: (mode: ViewMode) => void;
}

const LatestMaintenanceTable = ({
  records,
  vehicles,
  viewMode,
  onView,
  onDelete,
  onApprove,
  onRefresh,
  isLoading = false,
  currentPage,
  onPageChange,
  pageSize = PAGINATION_DEFAULT_PAGE_SIZE,
  onPageSizeChange,
  onToggleView,
}: LatestMaintenanceTableProps) => {
  const { t, language } = useI18n();
  const [searchTerm, setSearchTerm] = useState('');
  // Maintenance Type filter — same neat dropdown as the form's Driver field.
  const [typeFilter, setTypeFilter] = useState<string>('');
  const tableRef = useRef<HTMLDivElement>(null);
  const rowRefs = useRef(new Map<string, HTMLTableRowElement>());

  const { requestDelete, cancel, isPending, pendingItems } = usePendingDelete<string>(async (id) => {
    const record = records.find((item) => item.id === id);
    if (record) await Promise.resolve(onDelete?.(record));
  });

  const validRecords = records.filter((r): r is MaintenanceEvent & { id: string } => !!r.id);

  /** Resolve the registered vehicle number from the Vehicle Master first; fall
   * back to the snapshot stored on the record. NEVER show "Unknown" when a
   * valid vehicle exists. */
  const resolveVehicleNumber = (rec: MaintenanceEvent): string => {
    const vehicle = vehicles.find((v: any) => String(v.id) === String(rec.vehicleId));
    const raw = vehicle?.vehicleNumber ? String(vehicle.vehicleNumber) : rec.vehicleNo ? String(rec.vehicleNo) : '';
    return raw ? formatVehicleNumber(raw) : '—';
  };

  const filteredRecords = useMemo(() => {
    // Type filter first, then the free-text search over the surviving rows.
    const afterType = typeFilter
      ? validRecords.filter((rec) => (rec.maintenanceType || '').split(',').map((x) => x.trim()).includes(typeFilter))
      : validRecords;
    const term = searchTerm.trim().toLowerCase();
    if (!term) return afterType;
    return afterType.filter(rec => {
      const vehicleNumber = resolveVehicleNumber(rec);
      const searchable = [
        rec.billNumber,
        vehicleNumber,
        rec.vehicleNo,
        rec.maintenanceType,
        rec.serviceType,
        rec.garage,
        rec.mechanic,
        rec.driverName,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      return searchable.includes(term);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [validRecords, typeFilter, searchTerm, vehicles]);

  const totalRecords = filteredRecords.length;

  const paginatedRecords = filteredRecords.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );

  const actualTotalPages = Math.max(1, Math.ceil(totalRecords / pageSize));

  useEffect(() => {
    if (totalRecords > 0 && currentPage > actualTotalPages) {
      onPageChange(1);
    }
  }, [actualTotalPages, currentPage, onPageChange, totalRecords]);

  /** Roving keyboard: ArrowUp/Down walks the visible rows, Enter opens the
   *  view — the same interaction as Recent Trip Activity. */
  const moveRowFocus = (fromIndex: number, step: 1 | -1) => {
    const next = paginatedRecords[fromIndex + step];
    if (!next?.id) return;
    const element = rowRefs.current.get(next.id);
    if (element) {
      element.focus();
      element.scrollIntoView({ block: 'nearest' });
    }
  };

  const handleRowKeyDown = (event: React.KeyboardEvent<HTMLTableRowElement>, index: number) => {
    if (event.target !== event.currentTarget) return;
    if (event.key === 'Enter') {
      event.preventDefault();
      const rec = paginatedRecords[index];
      if (rec) onView(rec);
      return;
    }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      moveRowFocus(index, event.key === 'ArrowDown' ? 1 : -1);
    }
  };

  const getFirstMaintenanceType = (types: string): string => {
    if (!types) return '-';
    const parts = types.split(',').map(s => s.trim());
    return parts[0] || '-';
  };

  const getEmptyText = () => {
    if (searchTerm || typeFilter) return t('empty.search_no_results');
    if (viewMode === 'pending') return t('fleet.maintenance_table.no_pending');
    if (viewMode === 'approved') return t('fleet.maintenance_table.no_approved');
    return t('fleet.maintenance_table.no_deleted');
  };

  // Column count for the empty-state row (S.No + the nine data/action cols;
  // the pending action col only exists when a handler was passed).
  const colCount =
    10 + (viewMode === 'deleted' ? 1 : 0) + (viewMode === 'pending' && (onDelete || onApprove) ? 1 : 0);

  return (
    <div ref={tableRef} className="bg-white border border-slate-200/80 rounded-2xl shadow-xl shadow-slate-100 overflow-hidden">
      {/* Header — same treatment as Recent Trip Activity (Trip Entry) */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-3 px-6 py-3 border-b border-slate-100 bg-gradient-to-r from-slate-50 via-white to-slate-50">
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-3">
            <div className="h-9 w-9 rounded-xl bg-blue-50/70 border border-blue-100 flex items-center justify-center text-blue-500 shadow-inner">
              <History className="w-5 h-5" />
            </div>
            <h3 className="text-base font-bold text-slate-800 tracking-tight">
              {t('fleet.maintenance_table.recent_title')}
            </h3>
          </div>

          {/* Count follows the selected tab (Pending / Approved / Deleted) */}
          <span
            className="inline-flex items-center justify-center px-2.5 py-0.5 text-xs font-semibold text-slate-600 bg-slate-100 border border-slate-200/80 rounded-full shadow-sm tabular-nums"
          >
            {totalRecords}
          </span>

          {/* Status toggle — labels only, identical to the trip activity toggle */}
          <div className="flex items-center p-0.5 ml-2 border border-slate-200/80 rounded-lg overflow-hidden bg-slate-50 shadow-sm">
            {([
              ['pending', 'Pending', 'bg-orange-50/80 text-orange-500 shadow-sm'],
              ['approved', 'Approved', 'bg-emerald-50/80 text-emerald-500 shadow-sm'],
              ['deleted', 'Deleted', 'bg-rose-50/80 text-rose-500 shadow-sm'],
            ] as const).map(([mode, label, activeClass]) => (
              <button
                key={mode}
                type="button"
                onClick={() => onToggleView(mode)}
                aria-pressed={viewMode === mode}
                className={`inline-flex items-center px-5 py-1.5 text-xs font-semibold rounded-md transition-all ${
                  viewMode === mode
                    ? activeClass
                    : 'bg-transparent text-slate-500 hover:text-slate-800 hover:bg-slate-200/50'
                }`}
              >
                {translateStatus(t, label)}
              </button>
            ))}
          </div>
        </div>

        {/* Type filter, search, Reset and Refresh — trip activity arrangement */}
        <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto">
          <div className="w-40 sm:w-44">
            <MasterDropdown
              hideLabel
              label={t('operations.maintenance_type')}
              value={typeFilter}
              options={[
                { value: '', label: t('common.all') },
                ...MAINTENANCE_TYPES.map((type) => ({ value: type, label: localizeMaintenanceText(type, language) })),
              ]}
              onChange={(next) => { setTypeFilter(next || ''); onPageChange(1); }}
              placeholder={t('operations.maintenance_type')}
              searchable
              allowClear
              className="w-full"
            />
          </div>

          <div className="relative flex-1 sm:flex-none">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                onPageChange(1);
              }}
              placeholder={t('fleet.maintenance_table.search_placeholder')}
              className="w-full sm:w-64 pl-8 pr-8 py-1.5 text-sm border border-slate-200 rounded-xl bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-400/20 outline-none transition-all"
            />
            {searchTerm && (
              <button
                onClick={() => {
                  setSearchTerm('');
                  onPageChange(1);
                }}
                className="absolute right-2 top-1/2 -translate-y-1/2 w-5 h-5 flex items-center justify-center text-slate-400 hover:text-slate-600 bg-white hover:bg-slate-100 rounded-md transition-colors"
              >
                <X size={13} />
              </button>
            )}
          </div>

          <div className="h-5 w-px bg-slate-200 hidden sm:block" />

          <div className="flex items-center gap-1">
            {/* Reset — clears the search + filters, animated like the trip list reset */}
            <button
              type="button"
              onClick={() => {
                setSearchTerm('');
                setTypeFilter('');
                onPageChange(1);
              }}
              className="group relative h-8 px-2.5 rounded-xl font-medium text-xs flex items-center gap-1 transition-all shadow-sm bg-slate-50 hover:bg-slate-100 text-slate-500 border border-slate-200/70 active:scale-95"
            >
              <span className="inline-flex motion-safe:group-hover:animate-[var(--animate-action-reset)]"><RotateCcw size={13} /></span>
              <span className="hidden md:inline">{t('common.reset')}</span>
            </button>
            {onRefresh && <BrandRefreshButton onClick={() => onRefresh()} />}
          </div>
        </div>
      </div>

      {/* Table */}
      {isLoading && totalRecords === 0 ? (
        <div className="py-16 text-center text-sm font-medium text-slate-400">
          <span className="inline-flex items-center gap-2">
            <span className="h-4 w-4 animate-spin rounded-full border-2 border-slate-300 border-t-emerald-600" aria-hidden="true" />
            {t('fleet.maintenance_entry.loading_records')}
          </span>
        </div>
      ) : totalRecords === 0 ? (
        <div className="py-16 text-center text-slate-400 text-sm">
          <History size={24} className="mx-auto mb-2 opacity-50" />
          {getEmptyText()}
        </div>
      ) : (
        <>
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm text-left border-collapse">
              <thead className="bg-slate-50/75 border-b border-slate-200 text-slate-600">
                <tr>
                  {/* Serial number leads every view — pending, approved, deleted. */}
                  <th className="px-4 py-3 text-left text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center gap-1.5">
                      <ListOrdered size={13} className="text-slate-400 shrink-0" />
                      <span>{t('fleet.maintenance_table.sno')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-left text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center gap-1.5">
                      <Hash size={13} className="text-slate-400 shrink-0" />
                      <span>{t('fleet.maintenance_table.mnt_no')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-left text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center gap-1.5">
                      <Calendar size={13} className="text-blue-500 shrink-0" />
                      <span>{t('common.date')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-left text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center gap-1.5">
                      <Wrench size={13} className="text-purple-500 shrink-0" />
                      <span>{t('fleet.maintenance_table.maintenance_details')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-left text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center gap-1.5">
                      <Store size={13} className="text-amber-500 shrink-0" />
                      <span>{t('operations.maintenance_garage')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-center text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center justify-center gap-1.5">
                      <User size={13} className="text-indigo-500 shrink-0" />
                      <span>{t('fleet.maintenance_form.mechanic')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-center text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center justify-center gap-1.5">
                      <Gauge size={13} className="text-orange-500 shrink-0" />
                      <span>{t('fleet.maintenance_form.current_km')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-center text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center justify-center gap-1.5">
                      <Clock size={13} className="text-cyan-500 shrink-0" />
                      <span>{t('fleet.maintenance_table.next_service')}</span>
                    </div>
                  </th>
                  <th className="px-4 py-3 text-center text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center justify-center gap-1.5">
                      <Wallet size={13} className="text-emerald-600 shrink-0" />
                      <span>{t('fleet.parts.total_cost')}</span>
                    </div>
                  </th>
                  {viewMode === 'deleted' && (
                    <th className="px-4 py-3 text-left text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                      <div className="flex items-center gap-1.5">
                        <History size={13} className="text-rose-500 shrink-0" />
                        <span>{t('fleet.maintenance_table.deleted_at')}</span>
                      </div>
                    </th>
                  )}
                  <th className="px-4 py-3 text-center text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                    <div className="flex items-center justify-center gap-1.5">
                      <Paperclip size={13} className="text-slate-500 shrink-0" />
                      <span>{t('fleet.maintenance_table.docs')}</span>
                    </div>
                  </th>
                  {viewMode === 'pending' && (
                    <th className="px-4 py-3 text-center text-sm font-bold uppercase tracking-wider whitespace-nowrap">
                      <div className="flex items-center justify-center gap-1.5">
                        <CheckCircle2 size={13} className="text-emerald-500 shrink-0" />
                        <span>{t('common.actions')}</span>
                      </div>
                    </th>
                  )}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 bg-white">
                {isLoading ? (
                  <tr>
                    <td colSpan={colCount} className="py-16 text-center text-sm font-medium text-slate-400">
                      <span className="inline-flex items-center gap-2">
                        <span className="h-4 w-4 animate-spin rounded-full border-2 border-slate-300 border-t-emerald-600" aria-hidden="true" />
                        {t('fleet.maintenance_entry.loading_records')}
                      </span>
                    </td>
                  </tr>
                ) : (
                paginatedRecords.map((rec, index) => {
                  const firstType = getFirstMaintenanceType(rec.maintenanceType);
                  const isDeleted = viewMode === 'deleted';
                  const typeCount = rec.maintenanceType
                    ? rec.maintenanceType.split(',').filter(s => s.trim()).length
                    : 0;

                  return (
                    <tr
                      key={rec.id}
                      ref={(element) => {
                        if (element && rec.id) rowRefs.current.set(rec.id, element);
                        else if (rec.id) rowRefs.current.delete(rec.id);
                      }}
                      tabIndex={0}
                      aria-label={`${rec.billNumber || ''} ${resolveVehicleNumber(rec)}`}
                      onKeyDown={(event) => handleRowKeyDown(event, index)}
                      className="cursor-pointer outline-none transition-colors duration-150 hover:bg-slate-50/80 border-l-4 border-l-transparent focus-visible:border-l-blue-400 focus-visible:bg-blue-50/40"
                      onClick={() => onView(rec)}
                    >
                      {/* Serial continues across pages so row 11 on page 2 reads 11. */}
                      <td className="px-4 py-3 whitespace-nowrap">
                        <span className="inline-flex h-6 min-w-6 items-center justify-center rounded-md border border-slate-200 bg-slate-50 px-1.5 text-[11px] font-bold tabular-nums text-slate-500">
                          {(currentPage - 1) * pageSize + index + 1}
                        </span>
                      </td>

                      <td className="px-4 py-3 whitespace-nowrap">
                        <span className={`inline-flex items-center gap-1.5 text-xs font-bold rounded-md px-2 py-0.5 border ${
                          isDeleted
                            ? 'bg-rose-50 text-rose-700 border-rose-100/80'
                            : rec.paymentStatus === 'approved'
                              ? 'bg-emerald-50 text-emerald-700 border-emerald-100/80'
                              : 'bg-orange-50 text-orange-700 border-orange-100/80'
                        }`}>
                          {rec.billNumber || '-'}
                        </span>
                      </td>

                      <td className="px-4 py-3 text-left whitespace-nowrap">
                        <span className="text-xs font-medium text-slate-600 whitespace-nowrap">
                          {formatTripListDay((rec as any).date || rec.createdAt, language)}
                        </span>
                      </td>

                      <td className="px-4 py-3 text-left whitespace-nowrap">
                        <span className="text-xs text-slate-600">
                          {localizeMaintenanceText(firstType, language)}
                          {typeCount > 1 && (
                            <span className="text-xs text-slate-400 ml-1">
                              {t('fleet.maintenance_table.more', { count: typeCount - 1 })}
                            </span>
                          )}
                        </span>
                      </td>

                      <td className="px-4 py-3 text-left whitespace-nowrap">
                        <span className="text-xs text-slate-600">{localizeMaintenanceName(rec.garage || '-', language) || '-'}</span>
                      </td>

                      <td className="px-4 py-3 text-center whitespace-nowrap">
                        <span className="text-xs text-slate-600">{localizeMaintenanceName(rec.mechanic || '-', language) || '-'}</span>
                      </td>

                      <td className="px-4 py-3 text-center text-xs font-semibold text-slate-700 whitespace-nowrap tabular-nums">
                        {rec.currentKM.toLocaleString()}
                      </td>

                      <td className="px-4 py-3 text-center text-xs text-slate-600 whitespace-nowrap tabular-nums">
                        {rec.nextServiceKM?.toLocaleString() || '-'}
                      </td>

                      <td className="px-4 py-3 text-center text-xs font-bold text-blue-700 whitespace-nowrap tabular-nums">
                        ₹{rec.totalCost?.toFixed(2) || '0.00'}
                      </td>

                      {isDeleted && (
                        <td className="px-4 py-3 text-left whitespace-nowrap">
                          <span className="text-xs text-slate-500">
                            {rec.deletedAt ? new Date(rec.deletedAt).toLocaleString() : '-'}
                          </span>
                        </td>
                      )}

                      <td className="px-4 py-3 text-center whitespace-nowrap">
                        {Array.isArray(rec.documents) && rec.documents.length > 0 ? (
                          <button
                            onClick={(e) => { e.stopPropagation(); e.preventDefault(); onView(rec); }}
                            className="group relative inline-flex items-center justify-center gap-1 px-2.5 py-1 text-xs font-semibold text-violet-600 bg-violet-50 border border-violet-200 rounded-lg hover:bg-violet-500 hover:text-white transition-all shadow-sm active:scale-95"
                          >
                            <span className="inline-flex motion-safe:group-hover:animate-[var(--animate-action-view)]"><Paperclip size={12} /></span>
                            {rec.documents.length}
                          </button>
                        ) : (
                          <span className="text-xs text-slate-300">—</span>
                        )}
                      </td>

                      {/* Row actions — Pending only: Approve + Delete (10s undo).
                          Approved rows: no actions at all — clicking the row
                          opens the full view. */}
                      {viewMode === 'pending' && (onDelete || onApprove) && (
                        <td className="px-4 py-3 text-center whitespace-nowrap" onClick={(e) => { e.stopPropagation(); e.preventDefault(); }}>
                          <span className="inline-flex items-center justify-center gap-1">
                            {onApprove && (
                              <button
                                type="button"
                                onClick={(e) => { e.stopPropagation(); e.preventDefault(); onApprove(rec); }}
                                aria-label={t('common.approve')}
                                className="group relative h-8 w-8 rounded-xl flex items-center justify-center transition-all shadow-sm bg-emerald-50/70 hover:bg-emerald-500 text-emerald-600 hover:text-white border border-emerald-200/60 active:scale-95"
                              >
                                <span className="inline-flex motion-safe:group-hover:animate-[var(--animate-action-approve)]"><CheckCircle2 size={14} /></span>
                              </button>
                            )}
                            {onDelete && (
                              <button
                                type="button"
                                onClick={(e) => { e.stopPropagation(); e.preventDefault(); if (rec.id) requestDelete(rec.id, { label: t('fleet.maintenance_table.deleting', { vehicle: resolveVehicleNumber(rec) }) }); }}
                                disabled={!rec.id || isPending(rec.id)}
                                aria-label={t('common.delete')}
                                className="group relative h-8 w-8 rounded-xl flex items-center justify-center transition-all shadow-sm bg-rose-50/70 hover:bg-rose-500 text-rose-500 hover:text-white border border-rose-200/60 active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
                              >
                                <span className={`inline-flex ${!isPending(rec.id) ? uiActionIconMotionClass.delete : ''}`}><Trash2 size={14} /></span>
                              </button>
                            )}
                          </span>
                        </td>
                      )}
                    </tr>
                  );
                })
                )}
              </tbody>
            </table>
          </div>

          {/* Global pagination — identical to the Trip List paginator. */}
          {shouldShowPagination(totalRecords) && (
            <Pagination
              page={currentPage}
              pageSize={pageSize}
              totalItems={totalRecords}
              onPageChange={onPageChange}
              onPageSizeChange={onPageSizeChange}
              disabled={isLoading}
            />
          )}
        </>
      )}
      <PendingDeleteNotification items={pendingItems} onCancel={cancel} />
    </div>
  );
};

export default memo(LatestMaintenanceTable);

import { memo, useEffect, useState } from 'react';
import { Download, FileText, Loader2, Paperclip, Trash2, X, ChevronDown } from 'lucide-react';
import { useI18n } from '../../../../i18n';
import type { MaintenanceDocument } from '../../types';
import { maintenanceApi } from '../../services/maintenanceApi';
import { handleApiError } from '../../../../api/errors';
import { useSafeNotification } from '../../../../hooks/useSafeNotification';
import { confirmDialog } from '../../../../ui/confirm/confirmStore';

interface MaintenanceDocumentsProps {
  maintenanceId: string;
  documents: MaintenanceDocument[];
  allowRemove?: boolean;
  onChanged?: () => void;
}

const formatFileSize = (bytes?: number): string => {
  if (!bytes) return '';
  if (bytes > 1048576) return `${(bytes / 1048576).toFixed(1)} MB`;
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
};

const MaintenanceDocuments = ({ maintenanceId, documents, allowRemove = true, onChanged }: MaintenanceDocumentsProps) => {
  const { t } = useI18n();
  // Inline preview — opens BELOW the cards inside the same view (no popup).
  const [previewDoc, setPreviewDoc] = useState<MaintenanceDocument | null>(null);
  const [visibleDocs, setVisibleDocs] = useState<MaintenanceDocument[]>(documents || []);
  const [removingId, setRemovingId] = useState<number | null>(null);
  const { showNotification } = useSafeNotification();

  useEffect(() => setVisibleDocs(Array.isArray(documents) ? documents : []), [documents]);

  const remove = async (doc: MaintenanceDocument) => {
    // Global confirmation dialog instead of the blocking native
    // `window.confirm`. The handler was already async, so the guard keeps its
    // exact linear shape and nothing below it changes.
    const confirmed = await confirmDialog({
      title: t('common.remove'),
      message: t('fleet.maintenance_docs.confirm_remove', { file: doc.fileName }),
      record: doc.fileName,
      confirmLabel: t('common.remove'),
      cancelLabel: t('common.cancel'),
      tone: 'danger',
    });
    if (!confirmed) return;
    setRemovingId(doc.id);
    try {
      await maintenanceApi.removeDocument(maintenanceId, doc.id);
      setVisibleDocs((items) => items.filter((item) => item.id !== doc.id));
      if (previewDoc?.id === doc.id) setPreviewDoc(null);
      showNotification(t('fleet.maintenance_docs.removed'), 'success');
      onChanged?.();
    } catch (cause) {
      showNotification(handleApiError(cause), 'error');
    } finally {
      setRemovingId(null);
    }
  };

  if (visibleDocs.length === 0) return <p className="text-sm italic text-slate-400">{t('fleet.maintenance_docs.no_documents')}</p>;

  return (
    <>
      <div className="grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4">
        {visibleDocs.map((doc) => {
          const isImage = (doc.mimeType || '').startsWith('image/');
          const url = maintenanceApi.documentUrl(maintenanceId, doc.id);
          return (
            <div key={doc.id} className="group overflow-hidden rounded-xl border border-slate-200 bg-slate-50 transition hover:border-blue-300 hover:shadow-sm">
              <button
                type="button"
                onClick={() => setPreviewDoc((current) => (current?.id === doc.id ? null : doc))}
                className={`flex h-24 w-full items-center justify-center overflow-hidden bg-slate-100 transition-all ${
                  previewDoc?.id === doc.id ? 'ring-2 ring-inset ring-blue-400' : ''
                }`}>
                {isImage ? <img src={url} alt={doc.fileName} className="h-full w-full object-cover transition-transform group-hover:scale-105" /> : <div className="flex flex-col items-center text-slate-400"><FileText size={26} /><span className="mt-1 text-[10px] uppercase">PDF</span></div>}
              </button>
              <div className="p-2">
                <p className="flex items-center gap-1 truncate text-xs font-medium text-slate-700"><Paperclip size={11} className="shrink-0 text-slate-400" /><span className="truncate">{doc.fileName}</span></p>
                <div className="mt-1 flex items-center justify-between">
                  <span className="text-[10px] text-slate-400">{formatFileSize(doc.fileSize)}</span>
                  <div className="flex items-center gap-1">
                    <span className={`inline-flex text-slate-300 transition-transform duration-200 ${previewDoc?.id === doc.id ? 'rotate-180 text-blue-400' : ''}`}><ChevronDown size={12} /></span>
                    <button type="button" onClick={() => maintenanceApi.downloadDocument(maintenanceId, doc).catch((cause) => showNotification(handleApiError(cause), 'error'))} className="rounded p-1 text-slate-400 hover:bg-blue-50 hover:text-blue-600"><Download size={13} /></button>
                    {allowRemove && <button type="button" disabled={removingId === doc.id} onClick={() => void remove(doc)} className="rounded p-1 text-slate-400 hover:bg-rose-50 hover:text-rose-600 disabled:opacity-50">{removingId === doc.id ? <Loader2 size={13} className="animate-spin" /> : <Trash2 size={13} />}</button>}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {/* Inline preview — expands right below the cards, scroll ("drag") to
          see the full document; download + hide live in its own strip. */}
      {previewDoc && (() => {
        const url = maintenanceApi.documentUrl(maintenanceId, previewDoc.id);
        const isImage = (previewDoc.mimeType || '').startsWith('image/');
        const isPdf = (previewDoc.mimeType || '').includes('pdf');
        return (
          <div className="mt-3 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm animate-fade-in-up">
            <div className="flex items-center justify-between gap-3 border-b border-slate-100 bg-slate-50/70 px-3.5 py-2">
              <p className="flex min-w-0 items-center gap-2 text-xs font-bold text-slate-700">
                <FileText size={14} className="shrink-0 text-slate-400" />
                <span className="truncate">{previewDoc.fileName}</span>
                <span className="shrink-0 font-semibold text-slate-400">· {formatFileSize(previewDoc.fileSize)}</span>
              </p>
              <div className="flex shrink-0 items-center gap-1.5">
                <button
                  type="button"
                  onClick={() => maintenanceApi.downloadDocument(maintenanceId, previewDoc).catch((cause) => showNotification(handleApiError(cause), 'error'))}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-blue-600 px-2.5 py-1.5 text-[11px] font-semibold text-white transition hover:bg-blue-700 active:scale-95"
                >
                  <Download size={12} />
                  {t('common.download')}
                </button>
                <button
                  type="button"
                  onClick={() => setPreviewDoc(null)}
                  aria-label={t('common.close')}
                  className="group relative flex h-7 w-7 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm transition-all hover:border-red-100 hover:bg-red-50 hover:text-red-500 active:scale-95"
                >
                  <X size={13} />
                </button>
              </div>
            </div>
            {/* Scroll the body — "drag to see" the whole document. */}
            <div className="max-h-[440px] overflow-auto bg-slate-100/60">
              {isImage ? (
                <img src={url} alt={previewDoc.fileName} className="mx-auto min-h-[120px] w-auto max-w-full object-contain" />
              ) : isPdf ? (
                <iframe src={url} title={previewDoc.fileName} className="h-[436px] w-full border-0" />
              ) : (
                <div className="flex flex-col items-center gap-2 py-10 text-slate-400">
                  <FileText size={26} />
                  <button
                    type="button"
                    onClick={() => maintenanceApi.downloadDocument(maintenanceId, previewDoc).catch((cause) => showNotification(handleApiError(cause), 'error'))}
                    className="text-xs font-semibold text-blue-600 hover:underline"
                  >
                    {t('common.download')}
                  </button>
                </div>
              )}
            </div>
          </div>
        );
      })()}
    </>
  );
};

export default memo(MaintenanceDocuments);

import React, { memo, useState } from 'react';
import Select from 'react-select';
import { useI18n } from '../../../../i18n';
import { DatePicker } from '../../../../components/common/DatePicker';
import { Gauge, Wrench, Cog, Building2, UserCog, FileText, Paperclip, Upload, Trash2, File as FileIcon, AlertTriangle, Truck } from 'lucide-react';
import PartsTable from './PartsTable';
import type { PartItem } from '../../types';
import { maintenanceApi } from '../../services/maintenanceApi';
// Trip-List field chrome — identical labels, inputs and dropdowns.
import { opsFilterLabelClass, opsInputClass } from '../../../../shared/ui/operationsStyles';
import { localizeMaintenanceText } from '../../utils/maintenanceLocalization';
import MasterDropdown from '../../../masters/components/MasterDropdown';
import type { LatestVehicleMeter } from '../../services/maintenanceApi';

export interface FormDocumentItem {
  key: string;
  existingId?: number;
  fileName: string;
  mimeType: string;
  fileSize: number;
  file?: File;
  objectUrl?: string;
  markedForRemoval?: boolean;
}

interface MaintenanceFormProps {
  form: {
    vehicleId: string;
    date: string;
    billNumber: string;
    currentKM: string;
    maintenanceType: string[];   // now an array for multi‑select
    serviceType: string;
    garage: string;
    mechanic: string;
    driverId: string;
    driverName: string;
    nextServiceKM: string;
    nextServiceByType?: Record<string, string>;
    remarks: string;
    id?: string;
  };
  parts: PartItem[];
  setParts: (parts: PartItem[]) => void;
  vehicleOptions: { value: string; label: string }[];
  driverOptions: { value: string; label: string }[];
  maintenanceOptions: { value: string; label: string }[];
  onVehicleChange: (selected: any) => void;
  onDriverChange: (selected: any) => void;
  onMaintenanceChange: (selected: any) => void;  // receives array of selected values
  setFormField: (field: string, value: any) => void;
  selectKey: number;
  documents: FormDocumentItem[];
  onAddDocuments: (files: File[]) => void;
  onRemoveDocument: (key: string) => void;
  onMarkDocumentRemoval: (key: string) => void;
  validateKM?: (km: number) => { valid: boolean; message?: string };
  latestMeter?: LatestVehicleMeter | null;
}

const MaintenanceForm: React.FC<MaintenanceFormProps> = ({
  form,
  parts,
  setParts,
  vehicleOptions,
  driverOptions,
  maintenanceOptions,
  onVehicleChange,
  onDriverChange,
  onMaintenanceChange,
  setFormField,
  selectKey,
  documents,
  onAddDocuments,
  onRemoveDocument,
  onMarkDocumentRemoval,
  validateKM,
  latestMeter,
}) => {
  const { t, language } = useI18n();
  const [kmError, setKmError] = useState<string | null>(null);

  const latestMeterSource = latestMeter
    ? ({
        TRIP_START: 'Trip start',
        TRIP_END: 'Trip end',
        FUEL: 'Fuel bill',
        MAINTENANCE: 'Maintenance entry',
      } as const)[latestMeter.sourceType]
    : '';

  const inputClass = `${opsInputClass} pl-10`;

  // Maintenance Type multi-select — same chrome as the shared MasterDropdown
  // used by the Trip List filters: 40px control, 12px menu, 36px quiet rows
  // with a brand-tinted selection and subtle slate chips.
  const maintenanceSelectStyles = {
    control: (base: Record<string, unknown>) => ({
      ...base,
      minHeight: '36px',
      borderColor: '#cbd5e1',
      boxShadow: 'none',
      borderRadius: '0.75rem',
      fontSize: '13px',
      '&:hover': { borderColor: '#94a3b8' },
    }),
    menu: (base: Record<string, unknown>) => ({
      ...base,
      borderRadius: '0.75rem',
      overflow: 'hidden',
      zIndex: 40,
      boxShadow: '0 12px 32px -12px rgb(15 23 42 / 0.25)',
      border: '1px solid #e2e8f0',
    }),
    menuList: (base: Record<string, unknown>) => ({ ...base, padding: '4px', maxHeight: '240px' }),
    option: (base: Record<string, unknown>, state: { isSelected: boolean; isFocused: boolean }) => ({
      ...base,
      fontSize: '13px',
      fontWeight: state.isSelected ? 600 : 500,
      padding: '8px 10px',
      borderRadius: '0.5rem',
      cursor: 'pointer',
      backgroundColor: state.isSelected ? '#ecfdf5' : state.isFocused ? '#f8fafc' : 'transparent',
      color: state.isSelected ? '#047857' : '#334155',
      '&:active': { backgroundColor: '#ecfdf5' },
    }),
    multiValue: (base: Record<string, unknown>) => ({
      ...base,
      backgroundColor: '#f1f5f9',
      borderRadius: '0.5rem',
      border: '1px solid #e2e8f0',
    }),
    multiValueLabel: (base: Record<string, unknown>) => ({
      ...base,
      fontSize: '12px',
      fontWeight: 600,
      color: '#334155',
      padding: '2px 6px',
    }),
    multiValueRemove: (base: Record<string, unknown>) => ({
      ...base,
      color: '#94a3b8',
      cursor: 'pointer',
      ':hover': { backgroundColor: '#fee2e2', color: '#b91c1c' },
    }),
    placeholder: (base: Record<string, unknown>) => ({ ...base, color: '#9ca3af' }),
    clearIndicator: (base: Record<string, unknown>) => ({ ...base, color: '#94a3b8', cursor: 'pointer' }),
    dropdownIndicator: (base: Record<string, unknown>) => ({ ...base, color: '#94a3b8', cursor: 'pointer' }),
  };

  const handleCurrentKMChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    
    // Allow empty value
    if (val === '') {
      setFormField('currentKM', '');
      setKmError(null);
      return;
    }
    
    const num = parseFloat(val);
    if (isNaN(num)) {
      setKmError(t('validation.invalid_number'));
      return;
    }
    
    // Always update the form field with the raw value
    setFormField('currentKM', val);
    
    // Validate the value
    if (validateKM) {
      const { valid, message } = validateKM(num);
      if (!valid) {
        setKmError(message || t('fleet.maintenance_form.invalid_km'));
      } else {
        setKmError(null);
      }
    } else {
      setKmError(null);
    }
  };

  const handleDocumentInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length > 0) onAddDocuments(files);
    e.target.value = '';
  };

  const formatFileSize = (bytes: number): string => {
    if (!bytes) return '';
    if (bytes > 1048576) return `${(bytes / 1048576).toFixed(1)} MB`;
    return `${Math.max(1, Math.round(bytes / 1024))} KB`;
  };

  const isImageDoc = (doc: FormDocumentItem): boolean =>
    doc.mimeType?.startsWith('image/') || /\.(png|jpe?g)$/i.test(doc.fileName);

  const documentPreviewUrl = (doc: FormDocumentItem): string | undefined => {
    if (doc.objectUrl) return doc.objectUrl;
    if (doc.existingId != null && form.id) {
      return maintenanceApi.documentUrl(form.id, doc.existingId);
    }
    return undefined;
  };

  return (
    <div className="space-y-5">
      {/* Row 1: Vehicle, Date, Driver */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* 1. Vehicle */}
        <div>
          <label className={opsFilterLabelClass}>
            <Truck size={17} className="text-emerald-500 flex-shrink-0" />
            <span>{t('common.vehicle')}</span>
            <span className="text-rose-500">*</span>
          </label>
          <MasterDropdown
            key={`vehicle-${selectKey}`}
            hideLabel
            label={t('common.vehicle')}
            value={form.vehicleId}
            options={vehicleOptions}
            onChange={(next) => onVehicleChange(next ? { value: next } : null)}
            placeholder={t('operations.select_vehicle')}
            searchable
            allowClear
            className="w-full"
          />
        </div>

        {/* 3. Date */}
        <div>
          <DatePicker
            label={t('common.date')}
            required
            value={form.date}
            onChange={(dateStr) => setFormField('date', dateStr)}
            placeholder={t('placeholder.enter_date')}
          />
        </div>

        {/* 4. Driver */}
        <div>
          <label className={opsFilterLabelClass}>
            <UserCog size={17} className="text-violet-500 flex-shrink-0" />
            <span>{t('common.driver')}</span>
          </label>
          <MasterDropdown
            key={`driver-${selectKey}`}
            hideLabel
            label={t('common.driver')}
            value={form.driverId}
            options={driverOptions}
            onChange={(next) => {
              const match = driverOptions.find((opt) => String(opt.value) === String(next));
              onDriverChange(next ? { value: next, label: match?.label ?? next } : null);
            }}
            placeholder={t('operations.select_driver')}
            searchable
            allowClear
            className="w-full"
          />
        </div>
      </div>

      {/* Row 2: Current KM, Garage, Mechanic */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* 5. Current KM */}
        <div>
          <label className={opsFilterLabelClass}>
            <Gauge size={17} className="text-orange-500 flex-shrink-0" />
            <span>{t('fleet.maintenance_form.current_km')}</span>
            <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Gauge size={16} className="text-slate-400" />
            </div>
            <input
              type="number"
              value={form.currentKM}
              onChange={handleCurrentKMChange}
              placeholder={t('fleet.maintenance_form.number_placeholder', { value: '45000' })}
              className={`${inputClass} ${kmError ? 'border-red-500' : ''} [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none`}
            />
          </div>
          {kmError && <p className="mt-1 text-xs text-red-500">{kmError}</p>}
          {!kmError && latestMeter && (
            <p className="mt-1.5 text-xs font-medium text-slate-500">
              Latest recorded reading: <span className="text-slate-700">{latestMeter.meter.toLocaleString()} km</span>
              {' · '}{latestMeterSource} {latestMeter.ref}
              {latestMeter.tripStatus ? ` (${latestMeter.tripStatus})` : ''}
            </p>
          )}
        </div>

        {/* 7. Garage */}
        <div>
          <label className={opsFilterLabelClass}>
            <Building2 size={17} className="text-amber-500 flex-shrink-0" />
            <span>{t('operations.maintenance_garage')}</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Building2 size={16} className="text-slate-400" />
            </div>
