        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {documents.map((doc) => {
              const previewUrl = documentPreviewUrl(doc);
              const isImage = isImageDoc(doc);
              return (
                <div
                  key={doc.key}
                  className={`relative group border rounded-xl overflow-hidden bg-slate-50 ${
                    doc.markedForRemoval ? 'border-red-300 opacity-60' : 'border-slate-200'
                  }`}
                >
                  <div className="h-24 w-full bg-slate-100 flex items-center justify-center overflow-hidden">
                    {isImage && previewUrl ? (
                      <img
                        src={previewUrl}
                        alt={doc.fileName}
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <div className="flex flex-col items-center text-slate-400">
                        <FileIcon size={26} />
                        <span className="text-[10px] mt-1 uppercase text-slate-400">PDF</span>
                      </div>
                    )}
                  </div>
                  <div className="p-2">
                    <p className="text-xs font-medium text-slate-700 truncate">
                      {doc.fileName}
                    </p>
                    <div className="flex items-center justify-between mt-1">
                      <span className="text-[10px] text-slate-400">
                        {formatFileSize(doc.fileSize)}
                      </span>
                      {doc.markedForRemoval ? (
                        <span className="inline-flex items-center gap-0.5 text-[10px] font-semibold text-red-500">
                          <AlertTriangle size={10} /> {t('fleet.maintenance_form.will_remove')}
                        </span>
                      ) : (
                        <button
                          type="button"
                          onClick={() =>
                            doc.existingId != null && !doc.file
                              ? onMarkDocumentRemoval(doc.key)
                              : onRemoveDocument(doc.key)
                          }
                          className="text-slate-400 hover:text-red-500 transition"
                        >
                          <Trash2 size={14} />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default memo(MaintenanceForm);

import { memo } from 'react';
import { useEffect, useRef } from 'react';
import { Trash2, Plus, ShoppingBag } from 'lucide-react';
import { usePendingDelete } from '../../../../hooks/usePendingDelete';
import { PendingDeleteNotification } from '../../../../components/common/PendingDeleteNotification';
import { useI18n } from '../../../../i18n';
import type { PartItem } from '../../types';

interface PartsTableProps {
  parts: PartItem[];
  setParts: (parts: PartItem[]) => void;
  hideSubline?: boolean; // Added optional property
}

const PartsTable = ({ parts, setParts, hideSubline = false }: PartsTableProps) => {
  const { t } = useI18n();
  const updatePart = (index: number, field: keyof PartItem, value: any) => {
    const newParts = [...parts];
    newParts[index] = { ...newParts[index], [field]: value };
    
    if (field === 'quantity' || field === 'rate') {
      const quantity = field === 'quantity' ? value : newParts[index].quantity;
      const rate = field === 'rate' ? value : newParts[index].rate;
      newParts[index].amount = (Number(quantity) || 0) * (Number(rate) || 0);
    }
    
    setParts(newParts);
  };

  const sanitizeQuantity = (value: string): string => {
    let cleaned = value.replace(/[^0-9]/g, '');
    if (cleaned.length > 1 && cleaned.startsWith('0')) {
      cleaned = cleaned.replace(/^0+/, '');
      if (cleaned === '') cleaned = '0';
    }
    return cleaned;
  };

  const sanitizeRate = (value: string): string => {
    let cleaned = value.replace(/[^0-9.]/g, '');
    const components = cleaned.split('.');
    if (components.length > 2) {
      cleaned = components[0] + '.' + components.slice(1).join('');
    }
    if (cleaned.startsWith('.')) {
      cleaned = '0' + cleaned;
    }
    return cleaned;
  };

  const handleQuantityChange = (index: number, value: string) => {
    const sanitized = sanitizeQuantity(value);
    const numValue = sanitized === '' ? 0 : parseInt(sanitized, 10);
    updatePart(index, 'quantity', numValue);
  };

  const handleRateChange = (index: number, value: string) => {
    const sanitized = sanitizeRate(value);
    const numValue = sanitized === '' || sanitized === '.' ? 0 : parseFloat(sanitized);
    updatePart(index, 'rate', numValue);
  };

  const addRow = () => {
    setParts([
      ...parts,
      { name: '', specification: '', quantity: 1, rate: 0, amount: 0 }
    ]);
  };

  // Row delete asks first: the row greys out and an undo pop counts down
  // 5s (Telugu supported via the shared pendingDelete strings) before the
  // part is actually removed. Cancel restores it untouched.
  const pendingPartRef = useRef(new Map<number, PartItem>());
  // setParts takes the next array (not an updater) — keep a live ref so the
  // expiry callback never drops edits made while the countdown runs.
  const partsRef = useRef(parts);
  useEffect(() => {
    partsRef.current = parts;
  }, [parts]);
  const { requestDelete, cancel, isPending, pendingItems } = usePendingDelete<number>(
    (id) => {
      const part = pendingPartRef.current.get(id);
      pendingPartRef.current.delete(id);
      if (part) setParts(partsRef.current.filter((p) => p !== part));
    },
    5
  );

  const removeRow = (index: number) => {
    if (parts.length > 1 && !isPending(index)) {
      const part = parts[index];
      pendingPartRef.current.set(index, part);
      requestDelete(index, { label: part.name || t('fleet.parts.item_name') });
    }
  };

  const totalCost = parts.reduce((sum, p) => sum + (p.amount || 0), 0);

  return (
    <div className="space-y-4">
      {/* Compact Header */}
      <div className="flex flex-row justify-between items-center bg-gray-50/80 border border-gray-200 rounded-xl px-4 py-3 shadow-sm">
        <div className="flex items-center gap-2">
          <div className="p-1.5 bg-blue-50 border border-blue-100 rounded-lg text-blue-600">
            <ShoppingBag className="w-4 h-4" />
          </div>
          <div>
            <h4 className="text-sm font-semibold text-gray-800 tracking-wide">
              {t('fleet.maintenance_form.parts_title')} <span className="text-red-500">*</span>
            </h4>
            {!hideSubline && (
              <p className="text-[10px] text-gray-400 font-medium -mt-0.5">{t('fleet.maintenance_form.parts_subtitle')}</p>
            )}
          </div>
        </div>
        <button
          type="button"
          onClick={addRow}
          className="group relative inline-flex items-center gap-1.5 h-8 px-3 text-[11px] font-bold uppercase tracking-wider bg-green-600 text-white border border-green-700 rounded-lg hover:bg-green-700 transition-all shadow-sm active:scale-95"
        >
          <span className="inline-flex motion-safe:group-hover:animate-[var(--animate-action-add)]"><Plus className="w-3.5 h-3.5" /></span>
          {t('fleet.maintenance_form.add_row')}
        </button>
      </div>

      {/* Table */}
      <div className="overflow-x-auto border border-gray-200 rounded-xl shadow-sm bg-white">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50/80">
            <tr>
              <th className="w-[28%] px-3 py-2.5 text-left text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                {t('fleet.parts.item_name')} <span className="text-red-500">*</span>
              </th>
              <th className="w-[22%] px-3 py-2.5 text-left text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                {t('fleet.parts.specification')}
              </th>
              <th className="w-[12%] px-3 py-2.5 text-center text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                {t('fleet.parts.qty')}
              </th>
              <th className="w-[16%] px-3 py-2.5 text-right text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                {t('fleet.parts.rate')}
              </th>
              <th className="w-[16%] px-3 py-2.5 text-right text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                {t('fleet.parts.amount')}
              </th>
              <th className="w-[6%] px-3 py-2.5 text-center text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                {t('common.actions')}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 bg-white">
            {parts.map((part, index) => {
              const amount = part.amount || 0;
              return (
                <tr key={index} className="hover:bg-gray-50/60 transition-colors">
                  <td className="px-3 py-2">
                    <input
                      type="text"
                      value={part.name}
                      onChange={(e) => updatePart(index, 'name', e.target.value)}
                      placeholder={t('fleet.parts.item_placeholder')}
                      className="w-full h-9 px-2.5 border border-gray-300 rounded-lg text-sm text-gray-800 placeholder-gray-400 bg-white focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                    />
                  </td>
                  <td className="px-3 py-2">
                    <input
                      type="text"
                      value={part.specification || ''}
                      onChange={(e) => updatePart(index, 'specification', e.target.value)}
                      placeholder={t('fleet.parts.spec_placeholder')}
                      className="w-full h-9 px-2.5 border border-gray-300 rounded-lg text-sm text-gray-800 placeholder-gray-400 bg-white focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                    />
                  </td>
                  <td className="px-3 py-2 text-center">
                    <input
                      type="text"
                      inputMode="numeric"
                      value={part.quantity || ''}
                      onChange={(e) => handleQuantityChange(index, e.target.value)}
                      placeholder="0"
                      className="w-full h-9 px-2 text-center border border-gray-300 rounded-lg text-sm font-medium text-gray-800 bg-white focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                    />
                  </td>
                  <td className="px-3 py-2 text-right">
                    <input
                      type="text"
                      inputMode="decimal"
                      value={part.rate || ''}
                      onChange={(e) => handleRateChange(index, e.target.value)}
                      placeholder="0.00"
                      className="w-full h-9 px-2.5 text-right border border-gray-300 rounded-lg text-sm font-medium text-gray-800 bg-white focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                    />
                  </td>
                  <td className="px-3 py-2 text-right font-medium text-sm text-gray-700">
                    {amount > 0 ? (
                      <span className="bg-gray-50 border border-gray-200 rounded-lg px-2.5 py-1 inline-block min-w-[80px] text-sm font-semibold">
                        ₹{amount.toFixed(2)}
                      </span>
                    ) : (
                      <span className="text-gray-300 font-normal pr-2">—</span>
                    )}
                  </td>
                  <td className="px-3 py-2 text-center">
                    <button
                      type="button"
                      onClick={() => removeRow(index)}
                      disabled={parts.length <= 1 || isPending(index)}
                      className="p-1.5 rounded-lg text-red-400 hover:text-red-600 hover:bg-red-50 transition-all disabled:opacity-30 disabled:hover:bg-transparent disabled:cursor-not-allowed"
                      title={parts.length === 1 ? t('fleet.parts.cannot_delete_only_row') : t('fleet.parts.remove_item')}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-gray-50/80 border-t border-gray-200">
            <tr>
              <td colSpan={4} className="px-4 py-3 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">
                {t('fleet.parts.total_cost')}
              </td>
              <td className="px-4 py-3 text-right">
                <span className="inline-flex items-center px-3 py-1.5 bg-blue-50 border border-blue-200 rounded-lg text-sm font-bold text-blue-700 shadow-sm">
                  ₹{totalCost.toFixed(2)}
                </span>
              </td>
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>
      <PendingDeleteNotification items={pendingItems} onCancel={cancel} />
    </div>
  );
};

export default memo(PartsTable);

// src/modules/fleet-operations/components/maintenance/ViewModal.tsx
//
// Maintenance record view — the same global-view shell as the Trip List view
// (AppShellModal: overlay below the header, ESC to close, fade + scale panel).
// Covers EVERY detail of the record — identity, vehicle, all maintenance
// types, per-type next-service targets, parts, cost and documents — and works
// identically for Pending and Approved records. Documents are collapsible
// (show / hide) and open in the shared document lightbox. Edit lives INSIDE
// the view (never for approved / deleted / out-of-window records).

import React from 'react';
import {
  Truck, Wrench, Paperclip, ChevronDown, CheckCircle2, Clock,
  XCircle, IndianRupee, Package, X, Pencil, FileDown,
} from 'lucide-react';
import { generateMaintenancePdf } from '../../utils/generateMaintenancePdf';
import AppShellModal from '../../../../ui/AppShellModal';
import { ScopedI18nProvider } from '../../../../i18n';
import { ViewLanguageToggle } from '../../../../ui/ViewLanguageToggle';
import { uiPdfButtonClass } from '../../../../shared/ui/uiTokens';
import { useI18n, translateStatus } from '../../../../i18n';
import { uiActionIconMotionClass } from '../../../../shared/ui/uiTokens';
import { formatTripListDay } from '../../../operations/vehicle-trips/utils/formatTripListDay';
import { formatVehicleNumber } from '../../../../utils/format';
import { localizeMaintenanceText, localizeMaintenanceName } from '../../utils/maintenanceLocalization';
import type { MaintenanceEvent } from '../../types';
import MaintenanceDocuments from './MaintenanceDocuments';
import MasterDropdown from '../../../masters/components/MasterDropdown';
import { MAINTENANCE_TYPES } from '../../utils/constants';

interface ViewModalProps {
  record: MaintenanceEvent;
  vehicles: any[];
  onClose: () => void;
  /** EVERY maintenance record of this vehicle till now (newest first) —
   *  shown below the details like the collection shop view. */
  vehicleHistory?: MaintenanceEvent[];
  /** Set when the record can still be edited — shows the in-view Edit action. */
  canEdit?: boolean;
  /** Edit from inside the view — closes the modal and loads the form. */
  onEdit?: (record: MaintenanceEvent) => void;
}

const ViewModalInner: React.FC<ViewModalProps> = ({ record, vehicles, onClose, canEdit = false, onEdit, vehicleHistory = [] }) => {
  const { t, language, toggleLanguage } = useI18n();
  // Documents section starts OPEN; the chevron hides/shows the gallery.
  const [docsOpen, setDocsOpen] = React.useState(true);
  // Left panel filter — narrow the vehicle's approved list by type.
  const [typeFilter, setTypeFilter] = React.useState('');
  const [pdfBusy, setPdfBusy] = React.useState(false);
  // The record whose details are displayed. Clicking a row in the vehicle's
  // full history swaps it in — the view-collection interaction. When the
  // parent opens a different record, state resets during render (the React
  // recommended "adjust state on prop change" pattern — no effect needed).
  const [active, setActive] = React.useState(record);
  const [lastRecord, setLastRecord] = React.useState(record);
  if (record !== lastRecord) {
    setLastRecord(record);
    setActive(record);
  }

  /** LEFT PANEL list — every APPROVED maintenance entry of this vehicle,
   *  newest first, narrowable by type. Pending/deleted never appear here. */
  const approvedHistory = React.useMemo(
    () =>
      vehicleHistory.filter(
        (r) => r.paymentStatus === 'approved' && !r.deletedAt &&
          (!typeFilter || (r.maintenanceType || '').split(',').map((x) => x.trim()).includes(typeFilter))
      ),
    [vehicleHistory, typeFilter]
  );

  // Roving focus for the left list — ArrowUp/Down moves the active record.
  const listRefs = React.useRef(new Map<string, HTMLButtonElement>());
  const moveActive = (fromId: string, step: 1 | -1) => {
    const index = approvedHistory.findIndex((r) => String(r.id) === fromId);
    const next = approvedHistory[index + step];
    if (!next) return;
    setActive(next);
    const element = listRefs.current.get(String(next.id));
    if (element) {
      element.focus();
      element.scrollIntoView({ block: 'nearest' });
    }
  };

  const vehicle = vehicles.find((v: any) => String(v.id) === String(active.vehicleId));
  const vehicleNumber = formatVehicleNumber(vehicle?.vehicleNumber || active.vehicleNo || '');

  const handlePdf = async () => {
    if (pdfBusy) return;
    setPdfBusy(true);
    try {
      await generateMaintenancePdf(active, vehicleHistory, vehicleNumber, language, t, vehicle);
