// src/modules/operations/collections/pages/PendingCollectionsPage.tsx

import { useState, useEffect, useMemo, useCallback, useRef } from "react";
import { collectionService } from "../services/collectionService";
import { onShopDataChanged } from "../../../../shared/events/shopDataEvents";
import { useShops } from "../../../masters/shops/hooks/useShops";
import type {
  Collection,
  CollectionPendingSummaryRow,
  PendingOverallTotals,
  PendingShopSortDir,
  PendingShopSortKey,
} from "../types/collection";
import { useToast } from "../../../../components/common/useToast";
import { ShopCollectionDetailModal } from "../components/pending/ShopCollectionDetailModal";
import PendingCollectionsFilters from "../components/pending/PendingCollectionsFilters";
import PendingCollectionsTable from "../components/pending/PendingCollectionsTable";
import { Pagination } from "../../../../ui";
import { shouldShowPagination } from "../../../../shared/ui/paginationStyles";
import { todayBusinessDate } from "../../../../utils/businessDate";
import { useI18n } from "../../../../i18n";
import { CAPABILITIES, useCan } from "../../../auth/permissions";
import { exportPendingCollectionsExcel, exportPendingCollectionsPdf } from "../utils/exportPendingCollections";

const DEFAULT_PAGE_SIZE = 15;

interface PendingReportRow {
  shopId: number;
  shopName: string;
  ownerName: string;
  phoneNumber: string;
  weekStart: string;
  weekEnd: string;
  balance: number;
  weeklySales: number;
  weeklyApprovedCollections: number;
  weeklyPendingCollections: number;
  recoveryPercentage: number;
  overdueDays: number | null;
  lastCollectionDate: string | null | undefined;
  hasPendingCollections: boolean;
}

export default function PendingCollectionsPage() {
  // Entry-only roles (supervisor) view pending balances without delete rights.
  const can = useCan();
  const { t } = useI18n();
  const toast = useToast();

  // Load ALL shops from Master → Shops (Active + Inactive)
  const { shops, loading: shopsLoading, reload: reloadShops } = useShops();
  const allShops = shops; // Show ALL shops (Active + Inactive)

  const [allCollections] = useState<Collection[]>([]);

  // Filter state (unapplied)
  const [shopName, setShopName] = useState("");
  /**
   * Column order, held as key + direction — one vocabulary shared with the
   * table headers and the filter bar's Sort By, exactly like Trip List.
   * Default is shop name A → Z. `null` still means that same alphabet order
   * (never the master's insert sequence, which put "Z …" at the top).
   */
  const [sortBy, setSortBy] = useState<PendingShopSortKey | null>("shopName");
  const [sortDir, setSortDir] = useState<PendingShopSortDir>("asc");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [recoveryThreshold, setRecoveryThreshold] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");

  // Debounced search
  const debouncedSearchRef = useRef<NodeJS.Timeout | null>(null);
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("");

  useEffect(() => {
    if (debouncedSearchRef.current) {
      clearTimeout(debouncedSearchRef.current);
    }
    debouncedSearchRef.current = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery);
    }, 300);
    return () => {
      if (debouncedSearchRef.current) {
        clearTimeout(debouncedSearchRef.current);
      }
    };
  }, [searchQuery]);

  // Applied filters
  const [appliedShopName, setAppliedShopName] = useState("");
  const [appliedSortBy, setAppliedSortBy] = useState<PendingShopSortKey | null>("shopName");
  const [appliedSortDir, setAppliedSortDir] = useState<PendingShopSortDir>("asc");
  const [appliedFromDate, setAppliedFromDate] = useState("");
  const [appliedToDate, setAppliedToDate] = useState("");
  const [appliedRecoveryThreshold, setAppliedRecoveryThreshold] = useState(0);
  const [appliedSearchQuery, setAppliedSearchQuery] = useState("");

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(DEFAULT_PAGE_SIZE);

  // Selection state for table
  const [selectedShopName, setSelectedShopName] = useState<string | null>(null);

  // Modal state
  const [selectedShop, setSelectedShop] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Pending summary from backend (for shops that have collections)
  const [pendingSummaryRows, setPendingSummaryRows] = useState<CollectionPendingSummaryRow[]>([]);
  /**
   * The table is the only thing that loads. Everything below tracks a read that
   * changes table rows, so the page keeps its filter bar, its KPI strip and its
   * card header on screen and never flashes a full-page loader.
   */
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const hasRowsRef = useRef(false);

  const summaryAsOfDate = useCallback(() => {
    const today = todayBusinessDate();
    if (!appliedToDate) return today;
    return appliedToDate < today ? appliedToDate : today;
  }, [appliedToDate]);

  const loadSummary = useCallback(async (opts?: { quiet?: boolean }) => {
    if (!opts?.quiet || !hasRowsRef.current) setSummaryLoading(true);
    else setRefreshing(true);
    try {
      const payload = await collectionService.fetchPendingSummary(
        summaryAsOfDate(),
        appliedFromDate && appliedToDate ? { fromDate: appliedFromDate, toDate: appliedToDate } : undefined,
      );
      setPendingSummaryRows(payload.shops);
      hasRowsRef.current = payload.shops.length > 0;
    } catch {
      if (!opts?.quiet) setPendingSummaryRows([]);
    } finally {
      setSummaryLoading(false);
      setRefreshing(false);
    }
  }, [appliedFromDate, appliedToDate, summaryAsOfDate]);

  useEffect(() => {
    void loadSummary();
  }, [loadSummary]);

  useEffect(
    () =>
      onShopDataChanged(() => {
        void loadSummary({ quiet: true });
      }),
    [loadSummary],
  );

  useEffect(() => {
    setAppliedFromDate(fromDate);
    setAppliedToDate(toDate);
  }, [fromDate, toDate]);

  useEffect(() => {
    setAppliedShopName(shopName);
  }, [shopName]);

  useEffect(() => {
    setAppliedSortBy(sortBy);
    setAppliedSortDir(sortDir);
  }, [sortBy, sortDir]);

  useEffect(() => {
    setAppliedRecoveryThreshold(recoveryThreshold);
  }, [recoveryThreshold]);

  useEffect(() => {
    setAppliedSearchQuery(debouncedSearchQuery);
  }, [debouncedSearchQuery]);

  // Build the report only from backend-authoritative pending/outstanding rows.
  // Mapping every master shop here used to resurrect shops whose only sale
  // belonged to a deleted trip, using the master's stale currentBalance.
  const reportData = useMemo((): PendingReportRow[] => {
    const shopsById = new Map(allShops.map((shop) => [shop.id, shop]));
    return pendingSummaryRows.map((backendData) => {
      const shop = shopsById.get(backendData.shopId);
      return {
        shopId: backendData.shopId,
        shopName: backendData.shopName,
        ownerName: shop?.ownerName ?? "",
        phoneNumber: shop?.phoneNumber ?? "",
        weekStart: backendData.weekStart,
        weekEnd: backendData.weekEnd,
        balance: backendData.balance,
        weeklySales: backendData.weeklySales,
        weeklyApprovedCollections: backendData.weeklyApprovedCollections,
        weeklyPendingCollections: backendData.weeklyPendingCollections,
        recoveryPercentage: backendData.recoveryPercentage,
        overdueDays: backendData.overdueDays,
        lastCollectionDate: backendData.lastCollectionDate,
        hasPendingCollections: backendData.hasPendingCollections,
      };
    });
  }, [allShops, pendingSummaryRows]);

  // Apply filters (debounced search)
  const filteredData = useMemo(() => {
    let data = [...reportData];

    if (debouncedSearchQuery.trim()) {
      const query = debouncedSearchQuery.toLowerCase().trim();
      data = data.filter((s) => s.shopName.toLowerCase().includes(query));
    }

    if (appliedShopName) {
      data = data.filter((s) => s.shopName === appliedShopName);
    }

    if (appliedRecoveryThreshold > 0) {
      data = data.filter((shop) => shop.recoveryPercentage >= appliedRecoveryThreshold);
    }

    const column = appliedSortBy ?? "shopName";
    const direction = appliedSortBy ? (appliedSortDir === "asc" ? 1 : -1) : 1;
    const orderValue = (row: PendingReportRow): string | number => {
      switch (column) {
        case "balance":
          return row.balance;
        case "weeklySales":
          return row.weeklySales;
        case "weeklyApprovedCollections":
          return row.weeklyApprovedCollections;
        case "recoveryPercentage":
          return row.recoveryPercentage;
        case "overdueDays":
          return row.overdueDays ?? -1;
        case "lastCollectionDate":
          return row.lastCollectionDate ?? "";
        case "shopName":
        default:
          return row.shopName;
      }
    };
    data.sort((a, b) => {
      const left = orderValue(a);
      const right = orderValue(b);
      if (typeof left === "number" && typeof right === "number") {
        return (left - right) * direction;
      }
      return String(left).localeCompare(String(right), "en", {
        numeric: true,
        sensitivity: "base",
      }) * direction;
    });
    return data;
  }, [
    reportData,
    debouncedSearchQuery,
    appliedShopName,
    appliedSortBy,
    appliedSortDir,
    appliedRecoveryThreshold,
  ]);

  const totalItems = filteredData.length;
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredData.slice(start, start + pageSize);
  }, [filteredData, currentPage, pageSize]);

  // Reset to page 1 when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [appliedSearchQuery, appliedShopName, appliedSortBy, appliedSortDir, appliedRecoveryThreshold]);

  // Totals for KPI
  const totalOutstanding = filteredData.reduce((sum, s) => sum + s.balance, 0);
  const totalWeeklySales = filteredData.reduce((sum, s) => sum + s.weeklySales, 0);
  const totalWeeklyCollections = filteredData.reduce((sum, s) => sum + s.weeklyApprovedCollections, 0);
  /**
   * Recovery for the strip: approved collections ÷ sales, over exactly the
   * rows on screen — the same formula the backend's `totals.recoveryPercentage`
   * and the dashboard's collection-performance card use.
   *
   * It used to be the MEAN of each shop's own percentage, and that is what made
   * the KPI impossible to reconcile: 90 of the 128 shops in the default week
   * collected against older dues while selling nothing this week, every one of
   * them reading 0%, so the average landed on 49.9% beside ₹14,60,000 collected
   * on ₹4,74,014 of sales. Dividing the two figures the strip already shows
   * gives the honest 308.01% for the same rows.
   */
  const overallRecovery = totalWeeklySales > 0 ? (totalWeeklyCollections / totalWeeklySales) * 100 : 0;

  /**
   * The cumulative that closes the table. Summed over `filteredData` — the
   * whole filtered set — never over the rows of the current page, so the same
   * figures show on page 1 and on the last page.
   */
  const overallTotals = useMemo((): PendingOverallTotals | null => {
    if (filteredData.length === 0) return null;
    const collectionDates = filteredData
      .map((row) => row.lastCollectionDate ?? "")
      .filter((value) => Boolean(value))
      .sort();
    return {
      shops: filteredData.length,
      balance: totalOutstanding,
      weeklySales: totalWeeklySales,
      weeklyApprovedCollections: totalWeeklyCollections,
      recoveryPercentage: overallRecovery,
      lastCollectionDate: collectionDates.length > 0 ? collectionDates[collectionDates.length - 1] : null,
      overdueShops: filteredData.filter((row) => (row.overdueDays ?? 0) > 0).length,
    };
  }, [filteredData, totalOutstanding, totalWeeklySales, totalWeeklyCollections, overallRecovery]);

  /** Header click: ascending → descending → back to shop name A → Z. */
  const handleSortChange = useCallback((key: PendingShopSortKey) => {
    if (sortBy !== key) {
      setSortBy(key);
      setSortDir("asc");
      return;
    }
    if (sortDir === "asc") {
      setSortDir("desc");
      return;
    }
    setSortBy("shopName");
    setSortDir("asc");
  }, [sortBy, sortDir]);

  /** The filter bar's single setter for both halves of the order. */
  const setSort = useCallback((key: PendingShopSortKey | null, dir: PendingShopSortDir) => {
    setSortBy(key);
    setSortDir(dir);
  }, []);

  /**
   * Side arrows in the shop view walk the same order the table shows — the
   * filtered, sorted list — and move the table's highlighted row with them.
   */
  const shopPosition = useMemo(
    () => filteredData.findIndex((row) => row.shopName === selectedShop),
    [filteredData, selectedShop],
  );

  const navigateShop = useCallback(
    (direction: -1 | 1) => {
      if (shopPosition < 0) return;
      const next = shopPosition + direction;
      if (next < 0 || next >= filteredData.length) return;
      const nextShop = filteredData[next].shopName;
      setSelectedShop(nextShop);
      setSelectedShopName(nextShop);
    },
    [filteredData, shopPosition],
  );

  const handleView = (shopName: string) => {
    setSelectedShop(shopName);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedShop(null);
  };

  const refreshData = async () => {
    try {
      await Promise.all([reloadShops(), loadSummary({ quiet: true })]);
      toast.success(t("ops.collection.refreshed"));
    } catch {
      toast.error(t("ops.collection.failed_refresh"));
    }
  };

  const resetFilters = () => {
    setFromDate("");
    setToDate("");
    setShopName("");
    setSortBy("shopName");
    setSortDir("asc");
    setRecoveryThreshold(0);
    setSearchQuery("");
    setAppliedFromDate("");
    setAppliedToDate("");
    setAppliedShopName("");
    setAppliedSortBy("shopName");
    setAppliedSortDir("asc");
    setAppliedRecoveryThreshold(0);
    setAppliedSearchQuery("");
    setCurrentPage(1);
    toast.info(t("ops.collection.filters_reset"));
  };

  const firstLoad = (shopsLoading || summaryLoading) && pendingSummaryRows.length === 0;
  const tableLoading = firstLoad;
  const hasKpiFilters = Boolean(appliedShopName || (appliedFromDate && appliedToDate));
  const exportFileName = `pending-collections-${todayBusinessDate()}`;
  const handleExportPdf = useCallback(() => {
    void exportPendingCollectionsPdf(filteredData, exportFileName);
  }, [filteredData, exportFileName]);
  const handleExportExcel = useCallback(() => {
    exportPendingCollectionsExcel(filteredData, exportFileName);
  }, [filteredData, exportFileName]);

  return (
    <div className="w-full space-y-5 animate-in fade-in duration-500">
      {/* Filter Bar */}
      <PendingCollectionsFilters
        fromDate={fromDate}
        toDate={toDate}
        shopName={shopName}
        sortBy={sortBy}
        sortDir={sortDir}
        shopNames={allShops.map((s) => s.shopName).sort()}
        recoveryThreshold={recoveryThreshold}
        searchQuery={searchQuery}
        setFromDate={setFromDate}
        setToDate={setToDate}
        setShopName={setShopName}
        setSort={setSort}
        setRecoveryThreshold={setRecoveryThreshold}
        setSearchQuery={setSearchQuery}
        onReset={resetFilters}
        onRefresh={refreshData}
        onExportPdf={handleExportPdf}
        onExportExcel={handleExportExcel}
        exportEnabled={hasKpiFilters && filteredData.length > 0 && !tableLoading}
        refreshing={firstLoad || refreshing}
      />

      {/* Table Section */}
      <div className="rounded-2xl border border-slate-200/80 overflow-hidden bg-white shadow-sm text-xs md:text-sm">
        <PendingCollectionsTable
          data={paginatedData}
          selectedShopName={selectedShopName}
          onSelectShop={setSelectedShopName}
          onView={handleView}
          totalShops={filteredData.length}
          startIndex={(currentPage - 1) * pageSize}
          isLoading={tableLoading}
          refreshing={refreshing}
          sortBy={sortBy}
          sortDir={sortDir}
          onSortChange={handleSortChange}
          overall={overallTotals}
        />
        {shouldShowPagination(totalItems) && (
          <Pagination
            compact
            page={currentPage}
            pageSize={pageSize}
            totalItems={totalItems}
            onPageChange={setCurrentPage}
            onPageSizeChange={(size) => {
              setPageSize(size);
              setCurrentPage(1);
            }}
            disabled={tableLoading}
          />
        )}
      </div>

      {selectedShop && (
        <ShopCollectionDetailModal
          isOpen={isModalOpen}
          onClose={closeModal}
          shopName={selectedShop}
          allCollections={allCollections}
          shops={allShops}
          onRefresh={refreshData}
          onNavigateShop={navigateShop}
          canGoPrev={shopPosition > 0}
          canGoNext={shopPosition >= 0 && shopPosition < filteredData.length - 1}
          shopIndex={shopPosition >= 0 ? shopPosition + 1 : undefined}
          shopTotal={filteredData.length}
          allowDelete={can(CAPABILITIES.COLLECTION_DELETE)}
          fromDate={appliedFromDate || undefined}
          toDate={appliedToDate || undefined}
        />
      )}
    </div>
  );
}

/**
 * Frontend regression guards for the persistent-authoritative Collection
 * balance (no weekly opening balance, no weekly reset).
 *
 * The Collection module has no component-test infra (no jsdom / RTL), so
 * these assert on the module source (same pattern as
 * collectionService.contract.test.ts) plus one service-level test using a
 * mock axios adapter that the approval response's `currentBalance` is read.
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";
import type { AxiosRequestConfig } from "axios";
import { apiClient } from "../../../../api/client";
import { collectionService } from "./collectionService";

const __dirname = dirname(fileURLToPath(import.meta.url));
const read = (rel: string) =>
  readFileSync(join(__dirname, rel), "utf8");

const enDictSrc = read("../../../../i18n/modules/operations.en.ts");
// Shared keys (operations.*) live in the main dictionary.
const enMainDictSrc = read("../../../../i18n/en.ts");
const entryHookSrc = read("../hooks/useCollectionEntry.ts");
const summarySrc = read("../components/entry/OutstandingSummary.tsx");
const tableSrc = read("../components/entry/RecentCollectionsTable.tsx");
const collectionInformationSrc = read("../components/entry/CollectionInformation.tsx");
const serviceSrc = read("./collectionService.ts");

test("Opening Balance is correctly displayed as a carried-forward figure", () => {
  // The summary card is i18n-driven, so assert the keys it renders — the
  // English literals only ever matched comments and broke on the i18n pass.
  // en values: "Opening Balance" / "Brought forward from previous week".
  // The summary renders "Opening Balance" + "Brought forward …" through the
  // shared i18n keys; the EN dictionary carries the expected wording.
  assert.match(summarySrc, /t\("ops\.collection\.opening_balance"\)/);
  assert.match(summarySrc, /t\("ops\.collection\.brought_forward_week"\)/);
  assert.match(enDictSrc, /'ops\.collection\.opening_balance':\s*'Opening Balance'/);
  assert.match(enDictSrc, /'ops\.collection\.brought_forward_week':\s*'Brought forward/);
  // The hook calculates openingBalance from the weekly summary
  assert.match(entryHookSrc, /openingBalance/);
});

test("The Collection page balance is the backend-authoritative live balance, not a weekly figure", () => {
  // Outstanding Summary's main KPI is `currentOutstanding` (shops.current_balance).
  // en values: "Current Outstanding" / "Outstanding Amount (Approved Only)".
  // Outstanding Summary's main KPI is `currentOutstanding` (shops.current_balance),
  // rendered through i18n keys — EN values: "Current Outstanding" /
  // "Outstanding Amount (Approved Only)".
  assert.match(summarySrc, /t\("ops\.collection\.current_outstanding"\)/);
  assert.match(summarySrc, /t\("ops\.collection\.outstanding_approved_only"\)/);
  assert.match(enDictSrc, /'ops\.collection\.current_outstanding':\s*'Current Outstanding'/);
  assert.match(enDictSrc, /'ops\.collection\.outstanding_approved_only':\s*'Outstanding includes approved sales only'/);
  // The hook reads `weeklySummary.balance` for the live balance and computes openingBalance.
  assert.match(entryHookSrc, /weeklySummary\.balance/);
  assert.match(entryHookSrc, /currentOutstanding/);
});

test("No weekly opening-balance calculation remains in the frontend (balance is persistent)", () => {
  // The service still uses `balance` from backend (shops.current_balance)
  assert.match(serviceSrc, /balance:\s*Number\(data\.balance/);
  // currentOutstanding is a frontend computed term, not in backend service
  assert.doesNotMatch(serviceSrc, /data\.currentOutstanding/);
});

test("Weekly cards (Approved Sales / Approved Collections / Pending Approval) are week-scoped and informational", () => {
  // en values: "Approved Sales" / "Approved Collections" / "Pending Approval".
  assert.match(summarySrc, /t\("ops\.collection\.approved_sales"\)/);
  assert.match(summarySrc, /t\("ops\.collection\.approved_collections"\)/);
  assert.match(summarySrc, /t\("operations\.pending_approval"\)/);
  assert.match(enDictSrc, /'ops\.collection\.approved_sales':\s*'Approved Sales'/);
  assert.match(enDictSrc, /'ops\.collection\.approved_collections':\s*'Approved Collections'/);
  assert.match(enMainDictSrc, /'operations\.pending_approval':\s*'Pending Approval'/);
  // The week range label is displayed on the weekly cards only.
  assert.match(summarySrc, /periodLabel/);
});

test("Summary permanently keeps sales on the previous week and collections on the current week", () => {
  // Backend contract: weekStart/weekEnd are the previous completed sales week;
  // collectionWeekStart/collectionWeekEnd are the selected current collection week.
  assert.match(summarySrc, /weekStart && weekEnd/);
  assert.match(summarySrc, /collectionWeekStart && collectionWeekEnd/);
  assert.match(summarySrc, /subtitle=\{countLabel\(salesCount, inWeekSubtitle\)\}/);
  assert.match(summarySrc, /subtitle=\{countLabel\(approvedCollectionsCount, collectionWeekRange\)\}/);
  assert.match(summarySrc, /subtitle=\{countLabel\(pendingCollectionsCount, collectionWeekRange\)\}/);
});

test("Collection date calendar is not clipped by the entry card", () => {
  assert.match(collectionInformationSrc, /overflow-visible/);
  assert.match(collectionInformationSrc, /focus-within:z-20/);
  assert.doesNotMatch(collectionInformationSrc, /opsFilterCardClass\} overflow-hidden/);
});

test("Current Outstanding KPI is the primary summary figure (highlighted, bottom of summary)", () => {
  // Current Outstanding is the bottom-line figure in the summary card (highlighted in emerald)
  assert.match(summarySrc, /t\("ops\.collection\.current_outstanding"\)/);
  assert.match(summarySrc, /t\("ops\.collection\.outstanding_approved_only"\)/);
  assert.match(summarySrc, /text-emerald-700/);  // Highlighted in emerald
  assert.match(summarySrc, /font-extrabold/);   // Large font
  // It is the last financial row (after the weekly cards)
  const outstandingIndex = summarySrc.lastIndexOf('t("ops.collection.current_outstanding")');
  const salesIndex = summarySrc.indexOf('t("ops.collection.approved_sales")');
  assert.ok(outstandingIndex !== -1 && salesIndex !== -1);
  assert.ok(outstandingIndex > salesIndex, "Current Outstanding must be the final summary row");
});

test("Collection Entry renders the collection table with the required columns", () => {
  // Column headers are i18n-driven, so assert the keys the table actually
  // renders rather than English literals (those only ever matched incidental
  // comments, and silently stopped matching when the layout was reworked).
  // The compact row-number heading is #, followed by the collection details.
  assert.match(tableSrc, />\s*#\s*</);
  assert.match(tableSrc, /t\("table\.collection_no"\)/);
  assert.match(tableSrc, /t\("common\.day"\)/);
  assert.match(tableSrc, /t\("table\.shop"\)/);
  assert.match(tableSrc, /t\("table\.collector"\)/);
  assert.match(tableSrc, /t\("table\.mode"\)/);
  assert.match(tableSrc, /t\("table\.amount"\)/);
  assert.match(tableSrc, /t\("table\.remarks"\)/);
  assert.match(tableSrc, /col\.paymentModeName/);
});

test("Collection Entry shop search is prefix-based and shows the latest shop transaction", () => {
  assert.match(collectionInformationSrc, /searchFromStart/);
  assert.match(collectionInformationSrc, /latestTransaction\.paymentModeName/);
  assert.match(collectionInformationSrc, /latestTransaction\.amount/);
  assert.match(collectionInformationSrc, /compactDate\(latestTransaction\.collectionDate\)/);
});

test("Filtering happens before display (single global filter)", () => {
  const filterIdx = tableSrc.indexOf("filteredBySearch");
  const displayIdx = tableSrc.indexOf("displayedData");
  assert.ok(filterIdx !== -1 && displayIdx !== -1);
  assert.ok(filterIdx < displayIdx, "filter must run before display");
  // RecentCollectionsTable doesn't use pagination (it shows all filtered results)
});

test("Recent Collections clears the selected row when clicking outside the table card", () => {
  assert.match(tableSrc, /document\.addEventListener\("pointerdown", handleClickAway\)/);
  assert.match(tableSrc, /target\.closest\("\[data-recent-collections\]"\)/);
  assert.match(tableSrc, /data-recent-collections/);
  assert.match(tableSrc, /data-recent-collection-row/);
  assert.match(tableSrc, /data-recent-collection-actions/);
  assert.match(tableSrc, /onSelectionChange\?\.\(null\)/);
});

test("Recent Collections keeps the selected row while a table-level action is clicked", () => {
  const guard = tableSrc.indexOf('target.closest("[data-recent-collections]")');
  const edit = tableSrc.indexOf("selectedCollection && onEdit(selectedCollection)");
  assert.ok(guard !== -1, "the click-away guard must include the whole Recent Collections card");
  assert.ok(edit !== -1, "the Edit action must use the selected collection");
});

test("Recent Collections uses selected-row toolbar actions instead of an actions column", () => {
  assert.match(tableSrc, /canEditSelected/);
  assert.match(tableSrc, /canDeleteSelected/);
  assert.match(tableSrc, /queueSelectedDelete/);
  assert.doesNotMatch(tableSrc, /t\("table\.actions"\)/);
});

test("Approve selected works for one pending row, many rows, and select-all", () => {
  assert.match(tableSrc, /idsReadyToApprove/);
  assert.match(tableSrc, /onApproveMany\(ids\)/);
  assert.match(tableSrc, /toggleAllPending/);
  assert.match(tableSrc, /Approve selected/);
  assert.match(tableSrc, /data-recent-collections/);
});

test("approveCollection() reads the backend-returned currentBalance", async () => {
  const calls: string[] = [];
  const original = apiClient.defaults.adapter;
  apiClient.defaults.adapter = async (config: AxiosRequestConfig) => {
    const method = (config.method ?? "get").toLowerCase();
    const url = config.url ?? "";
    calls.push(`${method} ${url}`);
    if (method === "patch") {
      return {
        data: { status: "Approved", currentBalance: 80000 },
        status: 200,
        statusText: "OK",
        headers: {},
        config: config as any,
      };
    }
    return {
      data: [],
      status: 200,
      statusText: "OK",
      headers: {},
      config: config as any,
    };
  };
  try {
    const result = await collectionService.approveCollection("7", "Admin");
    assert.equal(result.success, true);
    assert.equal(result.balance, 80000, "approval must surface the authoritative new balance");
    assert.ok(
      calls.some((c) => c === "patch /operations/collection-entry/7/status"),
      "approval must call the status endpoint"
    );
  } finally {
    apiClient.defaults.adapter = original;
  }
});

/**
 * API contract regression tests for Collection Entry vs. Pending Collection
 * delete endpoints.
 *
 * Context: Pending Collection was found calling the wrong backend route
 * (DELETE /collection-entry/:id, the unrestricted Collection Entry delete)
 * instead of its own gated route (DELETE /collection-entry/pending/:id).
 * That mistake silently defeated the backend's 7-day deletion window for
 * real users. These tests pin the exact URL each service function calls,
 * using a mock axios adapter (no network/server required), so a future
 * change cannot reintroduce the mix-up without failing CI.
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";
import type { AxiosRequestConfig } from "axios";
import { apiClient } from "../../../../api/client";
import { mapRawEntry } from "./collectionMapping";
import { collectionService } from "./collectionService";

const __dirname = dirname(fileURLToPath(import.meta.url));

interface RecordedCall {
  method: string;
  url: string;
  params?: Record<string, unknown>;
}

test("legacy mixed-case collection numbers are exposed with the permanent COL prefix", () => {
  const entry = mapRawEntry({
    id: 1,
    collection_no: "Col-20261019-001",
    collection_date: "2026-10-19",
    amount: 100,
  });

  assert.equal(entry.collectionNo, "COL-20261019-001");
});

function installMockAdapter(): { calls: RecordedCall[]; restore: () => void } {
  const calls: RecordedCall[] = [];
  const original = apiClient.defaults.adapter;

  apiClient.defaults.adapter = async (config: AxiosRequestConfig) => {
    const method = (config.method ?? "get").toLowerCase();
    const url = config.url ?? "";
    calls.push({
      method,
      url,
      params: config.params as Record<string, unknown> | undefined,
    });

    // GET requests are only hit here because deletePendingCollection() and
    // deleteCollection() both call refreshFromBackend() on success, which
    // fans out to /collection-entry, /shop-sales, and /masters/shops. Return
    // empty collections so the cache rebuild has nothing to choke on.
    if (method === "get") {
      return {
        data: [],
        status: 200,
        statusText: "OK",
        headers: {},
        config: config as any,
      };
    }

    // DELETE (and anything else exercised here) succeeds with an empty body.
    return {
      data: {},
      status: 200,
      statusText: "OK",
      headers: {},
      config: config as any,
    };
  };

  return {
    calls,
    restore: () => {
      apiClient.defaults.adapter = original;
    },
  };
}

test("deletePendingCollection() calls DELETE /operations/collection-entry/pending/:id", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    const result = await collectionService.deletePendingCollection("42");
    assert.equal(result.success, true);
    const deleteCalls = calls.filter((c) => c.method === "delete");
    assert.equal(deleteCalls.length, 1);
    assert.equal(deleteCalls[0].url, "/operations/collection-entry/pending/42");
  } finally {
    restore();
  }
});

test("deleteCollection() (Collection Entry) calls DELETE /operations/collection-entry/:id — no /pending segment", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    const success = await collectionService.deleteCollection("42");
    assert.equal(success, true);
    const deleteCalls = calls.filter((c) => c.method === "delete");
    assert.equal(deleteCalls.length, 1);
    assert.equal(deleteCalls[0].url, "/operations/collection-entry/42");
    assert.equal(deleteCalls[0].url.includes("/pending/"), false);
  } finally {
    restore();
  }
});

test("Collection Entry delete and Pending Collection delete are NOT the same endpoint", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    await collectionService.deleteCollection("7");
    await collectionService.deletePendingCollection("7");
    const deleteUrls = calls.filter((c) => c.method === "delete").map((c) => c.url);
    assert.equal(deleteUrls.length, 2);
    assert.notEqual(deleteUrls[0], deleteUrls[1]);
  } finally {
    restore();
  }
});

test("refreshFromBackend() requests deleted rows for global collection-number integrity", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    await collectionService.refreshFromBackend();
    const collectionCall = calls.find(
      (call) => call.method === "get" && call.url === "/operations/collection-entry",
    );
    assert.ok(collectionCall);
    assert.equal(collectionCall.params?.includeDeleted, "true");
  } finally {
    restore();
  }
});

test("fetchRecentCollectionsForShop() excludes deleted rows from the operational shop view", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    await collectionService.fetchRecentCollectionsForShop(5, 10);
    const getCalls = calls.filter((c) => c.method === "get");
    assert.equal(getCalls.length, 1);
    assert.equal(getCalls[0].url, "/operations/collection-entry/recent");
    assert.equal(getCalls[0].params?.shopId, 5);
    assert.equal(getCalls[0].params?.limit, 10);
    assert.equal(getCalls[0].params?.includeDeleted, undefined);
  } finally {
    restore();
  }
});

/**
 * Source-level regression guards.
 *
 * Pending Collection has no component-test infrastructure in this repo
 * (no jsdom/React Testing Library dependency), so these assert directly on
 * the page/table source to lock in the P0/P1 fixes at the wiring level:
 * no reachable Edit action, no client-side day-count eligibility calc, and
 * the delete handler is wired to the pending-specific service call.
 */
const pendingPageSrc = readFileSync(
  join(__dirname, "../pages/PendingCollectionsPage.tsx"),
  "utf8"
);
const pendingTableSrc = readFileSync(
  join(__dirname, "../components/pending/PendingTable.tsx"),
  "utf8"
);
/**
 * Deletion moved out of the Pending Collections list and into the shop view:
 * a row there offers View only, and the record being removed is visible (and
 * confirmable) inside that view. These guards pin that split so the list cannot
 * quietly grow a delete action again.
 */
const shopViewSrc = readFileSync(
  join(__dirname, "../components/pending/ShopCollectionDetailModal.tsx"),
  "utf8"
);

test("PendingCollectionsPage lists shops read-only — no delete from the list", () => {
  assert.doesNotMatch(pendingPageSrc, /deletePendingCollection\(/);
  assert.doesNotMatch(pendingPageSrc, /handleDelete/);
});

test("the shop view owns deletion — pending rows use the pending route, approved rows reverse through soft-delete", () => {
  assert.match(shopViewSrc, /collectionService\.deletePendingCollection\(/);
  assert.match(shopViewSrc, /collectionService\.deleteCollection\(/);
});

test("Pending Collections table has View only — no table-level Delete", () => {
  const pendingCollectionsTableSrc = readFileSync(
    join(__dirname, "../components/pending/PendingCollectionsTable.tsx"),
    "utf8",
  );
  assert.doesNotMatch(pendingCollectionsTableSrc, /Trash2/);
  assert.doesNotMatch(pendingCollectionsTableSrc, /allowDelete/);
  assert.doesNotMatch(pendingCollectionsTableSrc, /t\("common\.delete"\)/);
  assert.match(pendingCollectionsTableSrc, /onView/);
});

test("PendingCollectionsPage has no client-side 10-day (or any hardcoded day-count) eligibility calculation", () => {
  assert.doesNotMatch(pendingPageSrc, /isCollectionEditable/);
  assert.doesNotMatch(pendingPageSrc, /diffDays\s*>\s*10/);
  assert.doesNotMatch(pendingPageSrc, /canEditCollection/);
});

test("the shop view reads the backend-authoritative canDelete before deleting", () => {
  assert.match(shopViewSrc, /canDelete/);
  assert.doesNotMatch(shopViewSrc, /diffDays\s*>\s*10/);
  assert.doesNotMatch(shopViewSrc, /canEditCollection/);
});

test("PendingCollectionsPage no longer opens the modal in edit mode", () => {
  assert.doesNotMatch(pendingPageSrc, /mode=\{editMode\}/);
  assert.doesNotMatch(pendingPageSrc, /handleEdit/);
});

test("PendingTable has no reachable Edit/Pencil action", () => {
  assert.doesNotMatch(pendingTableSrc, /onEdit/);
  assert.doesNotMatch(pendingTableSrc, /Pencil/);
});

/**
 * P1-3 financial-authority regression tests.
 *
 * Context: the Pending Collection main table/view and the Collection Report
 * page independently recomputed weekly sales, approved collections, and
 * recovery % from raw/lifetime data instead of reading the backend's
 * GET .../pending-summary and GET .../report responses. These tests pin
 * the actual endpoint URLs called and forbid the specific duplicate-formula
 * patterns (`x / y * 100`) from reappearing in the financial-authority path.
 */

test("fetchPendingSummary() calls GET /operations/collection-entry/pending-summary", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    await collectionService.fetchPendingSummary("2026-08-18");
    const getCalls = calls.filter((c) => c.method === "get");
    assert.equal(getCalls.length, 1);
    assert.equal(getCalls[0].url, "/operations/collection-entry/pending-summary");
  } finally {
    restore();
  }
});

test("fetchCollectionReport() calls GET /operations/collection-entry/report", async () => {
  const { calls, restore } = installMockAdapter();
  try {
    await collectionService.fetchCollectionReport({ fromDate: "2026-08-10", toDate: "2026-08-16" });
    const getCalls = calls.filter((c) => c.method === "get");
    assert.equal(getCalls.length, 1);
    assert.equal(getCalls[0].url, "/operations/collection-entry/report");
  } finally {
    restore();
  }
});

const collectionReportPageSrc = readFileSync(
  join(__dirname, "../pages/CollectionReportPage.tsx"),
  "utf8"
);

test("PendingCollectionsPage main table sources balance/sales/approved/recovery from pending-summary, not weekly-summaries", () => {
  assert.match(pendingPageSrc, /collectionService\.fetchPendingSummary\(/);
  assert.doesNotMatch(pendingPageSrc, /fetchWeeklySummaries\(/);
});

test("PendingCollectionsPage's primary figures use backend recoveryPercentage (not recomputed from raw collections)", () => {
  // The page uses per-shop recoveryPercentage from pending-summary (backend-authoritative)
  assert.match(pendingPageSrc, /shop\.recoveryPercentage/);
  // It does NOT compute recovery from raw collection rows (collections / sales * 100)
  assert.doesNotMatch(pendingPageSrc, /collections \/ sales\) \* 100/);
  assert.doesNotMatch(pendingPageSrc, /weeklyCollections \/ weeklyStats\.weeklySales/);
  // The totals use backend-aggregated figures
  assert.match(pendingPageSrc, /totalWeeklySales/);
  assert.match(pendingPageSrc, /totalWeeklyCollections/);
  assert.match(pendingPageSrc, /totalOutstanding/);
});

test("PendingTable renders recovery/balance from the pending-summary row, not a local ratio calculation", () => {
  assert.match(pendingTableSrc, /shop\.recoveryPercentage/);
  assert.match(pendingTableSrc, /shop\.balance/);
  assert.match(pendingTableSrc, /shop\.weeklySales/);
  assert.match(pendingTableSrc, /shop\.weeklyApprovedCollections/);
  assert.doesNotMatch(pendingTableSrc, /periodCollections/);
  assert.doesNotMatch(pendingTableSrc, /periodSales/);
  assert.doesNotMatch(pendingTableSrc, /\/ sales\) \* 100/);
});

test("Pending table is sourced from pending-summary shops, not lifetime buildPending totals", () => {
  assert.match(pendingPageSrc, /payload\.shops/);
  assert.doesNotMatch(pendingPageSrc, /getPendingCollections\(\)/);
  assert.doesNotMatch(pendingPageSrc, /shop\.totalSales/);
  assert.doesNotMatch(pendingPageSrc, /shop\.totalCollections/);
});

test("CollectionReportPage sources totals from fetchCollectionReport(), not a client-side reduce over raw collections", () => {
  assert.match(collectionReportPageSrc, /collectionService\.fetchCollectionReport\(/);
  // The old violation: summing raw collection rows for the "official" total.
  assert.doesNotMatch(collectionReportPageSrc, /filteredData\.reduce\(\(sum, c\) => sum \+ c\.amount/);
});

test("CollectionReportPage payment-mode/collector percentages are not independently recomputed from raw rows", () => {
  // The old violation: (data.amount / total) * 100 computed from a client-built map of raw rows.
  assert.doesNotMatch(collectionReportPageSrc, /data\.amount\s*\/\s*total\)\s*\*\s*100/);
});

