import React, { useEffect, useRef, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import {
  ArrowDown,
  ArrowUp,
  Calendar,
  CheckCircle,
  FileImage,
  Fuel,
  Gauge,
  Hash,
  IndianRupee,
  MapPin,
  Pencil,
  Trash2,
  Truck,
  UserRound,
  Droplets,
  ExternalLink,
  Loader2,
  Route,
} from "lucide-react";
import type { FuelExpense, FuelSortKey } from "../types/fuelExpense";
import { fuelTripLabel, fuelTripLoads, hasFuelLoadBreakdown } from "../utils/fuelSummary";
import type { FuelQuickTab } from "../utils/filterFuelExpenses";
import { formatVehicleNumber } from "../../../../utils/format";
import { formatTripListDay } from "../../vehicle-trips/utils/formatTripListDay";
import { localizeTripViewText } from "../../vehicle-trips/utils/tripViewLocalization";
import { BillPreviewLink } from "../../vehicle-trips/components/Step_5/BillPreviewLink";
import { tableSelectedRowClass } from "../../../../shared/ui/tableRowSelection";
import { useTableRowSelection } from "../../../../shared/ui/useTableRowSelection";
import { RowSelectMark } from "../../../../shared/ui/RowSelectMark";
import { useI18n } from "../../../../i18n";
import { uiActionIconMotionClass } from "../../../../shared/ui/uiTokens";
import { reverseGeocode } from "../../vehicle-trips/utils/reverseGeocode";
import { googleMapsUrl, resolveFuelGps } from "../utils/fuelGps";

interface Props {
  bills: FuelExpense[];
  isLoading?: boolean;
  refreshing?: boolean;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onView?: (bill: FuelExpense) => void;
  onEdit?: (bill: FuelExpense) => void;
  onDelete?: (bill: FuelExpense) => void;
  onApprove?: (bill: FuelExpense) => void;
  startIndex?: number;
  sortBy?: FuelSortKey | null;
  sortDir?: "asc" | "desc";
  onSortChange?: (key: FuelSortKey) => void;
  activeTab?: FuelQuickTab;
  onTabChange?: (tab: FuelQuickTab) => void;
  tabCounts?: { all: number; pending: number; approved: number; deleted: number };
  includeMasterBunks?: boolean;
  onIncludeMasterBunksChange?: (next: boolean) => void;
  filteredTotals?: {
    records: number;
    litres: number;
    amount: number;
    distance: number | null;
    mileage: number | null;
  } | null;
}

function SortArrows({ active, dir }: { active: boolean; dir?: "asc" | "desc" }) {
  const base = "h-3.5 w-3.5 shrink-0 transition-colors";
  const on = "text-emerald-600";
  const off = "text-slate-400 group-hover/sort:text-slate-600";
  return (
    <span className="inline-flex shrink-0 items-center gap-0.5" aria-hidden="true">
      <ArrowUp size={13} strokeWidth={2.7} className={`${base} ${active && dir === "asc" ? on : off}`} />
      <ArrowDown size={13} strokeWidth={2.7} className={`${base} ${active && dir === "desc" ? on : off}`} />
    </span>
  );
}

function PetrolBunkToggle({
  includeMasterBunks,
  onChange,
}: {
  includeMasterBunks: boolean;
  onChange: (next: boolean) => void;
}) {
  return (
    <div className="flex items-center gap-2.5">
      <span className="inline-flex items-center gap-1 text-[11px] font-semibold uppercase tracking-wide text-slate-500">
        <Fuel size={13} className={includeMasterBunks ? "text-emerald-600" : "text-amber-500"} />
        Petrol
      </span>
      <div
        role="radiogroup"
        aria-label="Petrol bunks"
        className="relative isolate grid h-9 w-[214px] grid-cols-2 rounded-full bg-slate-100/90 p-1 ring-1 ring-slate-200/70"
      >
        <span
          aria-hidden="true"
          className={`pointer-events-none absolute top-1 bottom-1 w-[calc(50%-4px)] rounded-full shadow-sm ring-1 transition-[left,background-color] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] ${
            includeMasterBunks
              ? "left-1 bg-emerald-50 ring-emerald-200"
              : "left-[calc(50%+1px)] bg-amber-50 ring-amber-200"
          }`}
        />
        <button
          type="button"
          role="radio"
          aria-checked={includeMasterBunks}
          onClick={() => onChange(true)}
          className={`relative z-10 rounded-full text-[11px] font-bold tracking-wide transition-colors duration-200 ${
            includeMasterBunks ? "text-emerald-800" : "text-slate-500 hover:text-slate-700"
          }`}
        >
          All bunks
        </button>
        <button
          type="button"
          role="radio"
          aria-checked={!includeMasterBunks}
          onClick={() => onChange(false)}
          className={`relative z-10 rounded-full text-[11px] font-bold tracking-wide transition-colors duration-200 ${
            !includeMasterBunks ? "text-amber-800" : "text-slate-500 hover:text-slate-700"
          }`}
        >
          Others
        </button>
      </div>
    </div>
  );
}

function BunkGpsTooltip({
  bunk,
  address,
  lat,
  lon,
}: {
  bunk: string;
  address?: string;
  lat?: number | null;
  lon?: number | null;
}) {
  const { t } = useI18n();
  const gps = resolveFuelGps(lat, lon, address);
  const hasGps = gps.lat != null && gps.lon != null;
  const [position, setPosition] = useState<{ left: number; top: number } | null>(null);
  const [placeName, setPlaceName] = useState(gps.placeName);
  const [locating, setLocating] = useState(false);
  const hideTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    setPlaceName(gps.placeName);
  }, [gps.placeName]);

  useEffect(() => {
    if (!position || gps.lat == null || gps.lon == null) return;
    let cancelled = false;
    setLocating(!gps.placeName);
    void reverseGeocode(gps.lat, gps.lon).then(({ address: resolved }) => {
      if (cancelled) return;
      if (resolved) setPlaceName(resolved);
      setLocating(false);
    });
    return () => {
      cancelled = true;
    };
  }, [position, gps.lat, gps.lon, gps.placeName]);

  const clearHide = () => {
    if (hideTimer.current) {
      clearTimeout(hideTimer.current);
      hideTimer.current = null;
    }
  };

  const openTooltip = (element: HTMLElement) => {
    if (!hasGps && !gps.placeName) return;
    clearHide();
    const rect = element.getBoundingClientRect();
    const width = 300;
    const estimatedHeight = 176;
    const top = rect.bottom + estimatedHeight + 12 <= window.innerHeight ? rect.bottom + 8 : rect.top - estimatedHeight - 8;
    setPosition({
      left: Math.max(12, Math.min(window.innerWidth - width - 12, rect.left + rect.width / 2 - width / 2)),
      top: Math.max(8, top),
    });
  };

  const scheduleHide = () => {
    clearHide();
    hideTimer.current = setTimeout(() => setPosition(null), 280);
  };

  const mapsUrl = hasGps ? googleMapsUrl(gps.lat!, gps.lon!) : "";

  return (
    <span className="inline-flex max-w-full items-center" onMouseLeave={scheduleHide} onMouseEnter={clearHide}>
      <span
        tabIndex={hasGps || gps.placeName ? 0 : -1}
        aria-label={bunk}
        onMouseEnter={(event) => openTooltip(event.currentTarget)}
        onFocus={(event) => openTooltip(event.currentTarget)}
        onBlur={scheduleHide}
        className="max-w-full cursor-default truncate outline-none"
      >
        {bunk || "—"}
      </span>
      {position &&
        createPortal(
          <span
            role="tooltip"
            style={{ left: position.left, top: position.top, width: 300 }}
            className="fixed z-[9999] rounded-xl border border-slate-200 bg-white p-3 text-left text-[11px] font-medium text-slate-700 shadow-2xl"
            onMouseEnter={clearHide}
            onMouseLeave={scheduleHide}
          >
            <span className="mb-2 block border-b border-slate-100 pb-2 font-bold text-slate-700">Petrol bunk GPS</span>
            <span className="flex items-center justify-between gap-5 rounded-md px-1.5 py-1.5 odd:bg-slate-50">
              <span>Bunk</span>
              <span className="font-bold text-slate-900">{bunk || "—"}</span>
            </span>
            {hasGps ? (
              <>
                <span className="mt-0.5 flex items-start gap-2 rounded-md bg-slate-50 px-1.5 py-1.5 leading-5 text-slate-700">
                  {locating ? <Loader2 size={12} className="mt-0.5 shrink-0 animate-spin text-emerald-600" /> : <MapPin size={12} className="mt-0.5 shrink-0 text-rose-500" />}
                  <span className="font-semibold text-slate-800">
                    {locating ? t("ops.trip.locating") : placeName || t("ops.trip.location_captured")}
                  </span>
                </span>
                <span className="flex items-center justify-between gap-5 rounded-md px-1.5 py-1.5">
                  <span>GPS</span>
                  <span className="font-bold tabular-nums text-slate-900">
                    {gps.lat!.toFixed(6)}°N, {gps.lon!.toFixed(6)}°E
                  </span>
                </span>
                <a
                  href={mapsUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={(event) => event.stopPropagation()}
                  className="mt-1 inline-flex items-center gap-1 rounded-md px-1.5 py-1 font-semibold text-emerald-700 hover:bg-emerald-50 hover:underline"
                >
                  <ExternalLink size={11} />
                  {t("masters.shops.location.open_maps")}
                </a>
              </>
            ) : (
              <span className="block rounded-md px-1.5 py-1.5 text-slate-500">{t("ops.trip.not_captured")}</span>
            )}
          </span>,
          document.body,
        )}
    </span>
  );
}

/**
 * Linked-trip cell in the Trip List load idiom: a plain trip number for a
 * single-load (or unlinked) bill, and the same dotted-underline +
 * floating-card breakdown once the linked trip has two or more loads. Each
 * load row names its DC/farm context, and the card identifies this bill's
 * own diesel entry within the trip.
 */
function FuelTripLoadCell({ bill }: { bill: FuelExpense }) {
  const [position, setPosition] = useState<{ left: number; top: number } | null>(null);
  const loads = fuelTripLoads(bill);
  const showBreakdown = hasFuelLoadBreakdown(bill);
  const label = fuelTripLabel(bill);
  if (!showBreakdown) {
    return <span className="font-semibold text-slate-700">{label}</span>;
  }
  const openTooltip = (element: HTMLElement) => {
    const rect = element.getBoundingClientRect();
    const estimatedHeight = 60 + loads.length * 32;
    const top =
      rect.bottom + estimatedHeight + 12 <= window.innerHeight ? rect.bottom + 8 : rect.top - estimatedHeight - 8;
    setPosition({
      left: Math.max(12, Math.min(window.innerWidth - 280 - 12, rect.left + rect.width / 2 - 140)),
      top: Math.max(8, top),
    });
  };
  return (
    <span className="inline-flex items-center justify-start" onMouseLeave={() => setPosition(null)}>
      <button
        type="button"
        aria-label={`${label} by load`}
        onMouseEnter={(event) => openTooltip(event.currentTarget)}
        onFocus={(event) => openTooltip(event.currentTarget)}
        onBlur={() => setPosition(null)}
        className="rounded border-b border-dotted border-current px-0.5 font-bold text-emerald-700 focus:outline-none focus:ring-2 focus:ring-blue-300"
      >
        {label} · {loads.length} loads
      </button>
      {position &&
        createPortal(
          <span
            role="tooltip"
            style={{ left: position.left, top: position.top }}
            className="pointer-events-none fixed z-[9999] w-[280px] rounded-xl border border-slate-200 bg-white p-3 text-left text-[11px] font-medium text-slate-700 shadow-2xl"
          >
            <span className="mb-2 block border-b border-slate-100 pb-2 font-bold text-slate-700">
              {label} by load
            </span>
            {loads.map((load) => (
              <span
                key={load.load}
                className="flex items-center justify-between gap-5 rounded-md px-1.5 py-1.5 odd:bg-slate-50"
              >
                <span>Load {load.load}</span>
                <span className="text-right font-bold text-slate-900">
                  {load.farmName?.trim() || "—"}
                  <span className="block font-semibold tabular-nums text-slate-500">
                    DC {Number(load.dcWeight ?? 0).toFixed(2)} kg · {Math.round(Number(load.birds ?? 0)).toLocaleString()} birds
                  </span>
                </span>
              </span>
            ))}
            {bill.tripFuelEntryIndex != null && (
              <span className="mt-1 block rounded-md bg-emerald-50 px-1.5 py-1.5 font-semibold text-emerald-800">
                This bill: diesel entry #{bill.tripFuelEntryIndex}
              </span>
            )}
          </span>,
          document.body,
        )}
    </span>
  );
}

export function FuelBillTable({
  bills,
  isLoading = false,
  refreshing = false,
  selectedId,
  onSelect,
  onView,
  onEdit,
  onDelete,
  onApprove,
  startIndex = 0,
  sortBy = null,
  sortDir = "asc",
  onSortChange,
  activeTab = "ALL",
  onTabChange,
  tabCounts = { all: 0, pending: 0, approved: 0, deleted: 0 },
  includeMasterBunks = true,
  onIncludeMasterBunksChange,
  filteredTotals,
}: Props) {
  const { t, language } = useI18n();
  const selectedBill = bills.find((bill) => bill.id === selectedId) || null;

  // Single shared selection: click toggles, deleted rows are skipped,
  // Enter opens the bill, Escape clears.
  const selection = useTableRowSelection<FuelExpense>({
    rows: bills,
    getId: (bill) => bill.id,
    isRowSelectable: (bill) => !(bill.deleted === true || bill.status === "Deleted"),
    selectedId,
    toggleOnReselect: true,
    allowEscapeClear: true,
    getRowLabel: (bill) => `Fuel bill ${bill.billNo || bill.id}`,
    onSelect: (bill) => onSelect(bill.id),
    onDeselect: () => onSelect(null),
    onPrimaryAction: (bill) => {
      onSelect(bill.id);
      onView?.(bill);
    },
  });

  const sortable = (key: FuelSortKey, content: ReactNode, center = false) => {
    if (!onSortChange) return content;
    const active = sortBy === key;
    return (
      <button
        type="button"
        onClick={() => onSortChange(key)}
        aria-sort={active ? (sortDir === "asc" ? "ascending" : "descending") : "none"}
        className={`group/sort flex w-full items-center gap-1.5 text-[11px] font-bold uppercase tracking-wider transition-colors hover:text-emerald-700 ${
          center ? "justify-center" : ""
        } ${active ? "text-emerald-700" : "text-slate-700"}`}
      >
        {content}
        <SortArrows active={active} dir={sortDir} />
      </button>
    );
  };

  const selectedTabCount =
    activeTab === "ALL"
      ? tabCounts.all
      : activeTab === "PENDING"
        ? tabCounts.pending
        : activeTab === "APPROVED"
          ? tabCounts.approved
          : tabCounts.deleted;

  const tabs = [
    { id: "ALL" as const, label: t("common.all") },
    { id: "PENDING" as const, label: t("common.pending") },
    { id: "APPROVED" as const, label: t("common.approved") },
    { id: "DELETED" as const, label: t("common.deleted") },
  ];

  const isSelectedDeleted = selectedBill?.deleted === true || selectedBill?.status === "Deleted";
  const isTripSelected = selectedBill?.sourceType === "TRIP" || !!selectedBill?.tripNo || !!selectedBill?.tripId;
  const isSelectedApproved = !isSelectedDeleted && (selectedBill?.status === "Approved" || isTripSelected);
  const isSelectedPending = Boolean(
    selectedBill && !isSelectedDeleted && !isTripSelected && !isSelectedApproved && selectedBill.status === "Pending",
  );

  return (
    <div className="w-full">
      <div className="flex flex-col gap-3 border-b border-slate-100 bg-gradient-to-r from-emerald-50/60 via-white to-emerald-50/40 px-6 py-3.5 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl border border-emerald-100 bg-emerald-50/70 text-emerald-500 shadow-inner">
              <Fuel className="h-5 w-5" />
            </div>
            <h3 className="text-base font-bold tracking-tight text-slate-800">{t("ops.fuel.table_title")}</h3>
          </div>
          <span className="inline-flex items-center justify-center rounded-full border border-slate-200/80 bg-slate-100 px-2.5 py-0.5 text-xs font-semibold tabular-nums text-slate-600 shadow-sm">
            {selectedTabCount}
          </span>
          {onTabChange && (
            <div className="ml-1 flex items-center overflow-hidden rounded-lg border border-slate-200/80 bg-slate-50 p-0.5 shadow-sm">
              {tabs.map((tab) => {
                const isActive = activeTab === tab.id;
                const activeClass =
                  tab.id === "ALL"
                    ? "bg-slate-200/80 text-slate-800 shadow-sm font-bold"
                    : tab.id === "PENDING"
                      ? "bg-orange-50/80 text-orange-500 shadow-sm font-bold"
                      : tab.id === "APPROVED"
                        ? "bg-emerald-50/80 text-emerald-600 shadow-sm font-bold"
                        : "bg-rose-50/80 text-rose-500 shadow-sm font-bold";
                return (
                  <button
                    key={tab.id}
                    type="button"
                    onClick={() => onTabChange(tab.id)}
                    aria-pressed={isActive}
                    className={`inline-flex items-center rounded-md px-4 py-1.5 text-xs font-semibold transition-all sm:px-5 ${
                      isActive ? activeClass : "bg-transparent text-slate-500 hover:bg-slate-200/50 hover:text-slate-800"
                    }`}
                  >
                    {tab.label}
                  </button>
                );
              })}
            </div>
          )}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {onIncludeMasterBunksChange ? (
            <PetrolBunkToggle includeMasterBunks={includeMasterBunks} onChange={onIncludeMasterBunksChange} />
          ) : null}
          {selectedBill ? (
            <div className="flex flex-wrap items-center gap-2">
              {isSelectedPending && onApprove && (
                <button type="button" onClick={() => onApprove(selectedBill)} className="group relative inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-xl bg-emerald-600 px-3 text-xs font-semibold text-white transition-all hover:bg-emerald-700 active:scale-95" title={t("common.approve")}>
                  <span className={`inline-flex ${uiActionIconMotionClass.approve}`}><CheckCircle size={13} /></span>
                  <span>{t("common.approve")}</span>
                </button>
              )}
              {isSelectedPending && onDelete && (
                <button type="button" onClick={() => onDelete(selectedBill)} className="group relative inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-xl border border-rose-200 bg-rose-50 px-3 text-xs font-semibold text-rose-600 shadow-sm transition-all hover:bg-rose-100 active:scale-95" title={t("common.delete")}>
                  <span className={`inline-flex ${uiActionIconMotionClass.delete}`}><Trash2 size={13} /></span>
                  <span>{t("common.delete")}</span>
                </button>
              )}
              {isSelectedPending && onEdit && (
                <button type="button" onClick={() => onEdit(selectedBill)} className="group relative inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-xl border border-slate-200 bg-slate-100 px-3 text-xs font-semibold text-slate-700 shadow-sm transition-all hover:bg-slate-200 active:scale-95" title={t("common.edit")}>
                  <span className={`inline-flex ${uiActionIconMotionClass.edit}`}><Pencil size={13} /></span>
                  <span>{t("common.edit")}</span>
                </button>
              )}
            </div>
          ) : null}
        </div>
      </div>

      <div className="relative overflow-x-auto" aria-busy={isLoading || refreshing}>
        {refreshing && (
          <div aria-hidden="true" className="absolute inset-x-0 top-0 z-10 h-0.5 overflow-hidden bg-transparent">
            <div className={`h-full w-full animate-pulse ${includeMasterBunks ? "bg-emerald-300/80" : "bg-amber-300/80"}`} />
          </div>
        )}
        <table className="min-w-full border-collapse text-left text-[13px]">
          <thead className="border-b border-slate-200 bg-slate-50/80">
            <tr className="whitespace-nowrap text-slate-700">
              <th className="px-4 py-4 text-center text-[11px] font-bold uppercase tracking-wider text-slate-500">
                <div className="flex items-center justify-center gap-1.5"><Hash size={14} className="text-slate-400" /> #</div>
              </th>
              <th className="px-4 py-4 text-left">
                {sortable("billNo", <div className="flex items-center gap-1.5"><Fuel size={14} className="shrink-0 text-emerald-500" /><span>Bill No.</span></div>)}
              </th>
              <th className="px-4 py-4 text-left">
                {sortable("date", <div className="flex items-center gap-1.5"><Calendar size={14} className="shrink-0 text-blue-500" /><span>Day</span></div>)}
              </th>
              <th className="px-4 py-4 text-left">
                {sortable("tripNo", <div className="flex items-center gap-1.5"><Route size={14} className="shrink-0 text-teal-600" /><span>Trip / Load</span></div>)}
              </th>
              <th className="px-4 py-4 text-left">
                {sortable("vehicleNo", <div className="flex items-center gap-1.5"><Truck size={14} className="shrink-0 text-indigo-500" /><span>Vehicle</span></div>)}
              </th>
              <th className="px-4 py-4 text-left">
                {sortable("supervisorName", <div className="flex items-center gap-1.5"><UserRound size={14} className="shrink-0 text-violet-500" /><span>Supervisor</span></div>)}
              </th>
              <th className="px-4 py-4 text-center">
                {sortable("meterReading", <div className="flex items-center justify-center gap-1.5"><Gauge size={14} className="shrink-0 text-amber-500" /><span>Meter</span></div>, true)}
              </th>
              <th className="px-4 py-4 text-center">
                {sortable("litres", <div className="flex items-center justify-center gap-1.5"><Droplets size={14} className="shrink-0 text-cyan-600" /><span>Litres</span></div>, true)}
              </th>
              <th className="px-4 py-4 text-center">
                {sortable("rate", <div className="flex items-center justify-center gap-1.5"><IndianRupee size={14} className="shrink-0 text-violet-600" /><span>Price</span></div>, true)}
              </th>
              <th className="px-4 py-4 text-center">
                {sortable("amount", <div className="flex items-center justify-center gap-1.5"><IndianRupee size={14} className="shrink-0 text-emerald-600" /><span>Amount</span></div>, true)}
              </th>
              <th className="px-4 py-4 text-left">
                {sortable("petrolBunk", <div className="flex items-center gap-1.5"><MapPin size={14} className="shrink-0 text-rose-500" /><span>Bunk</span></div>)}
              </th>
              <th className="px-4 py-4 text-center text-[11px] font-bold uppercase tracking-wider text-slate-700">
                <div className="flex items-center justify-center gap-1.5"><FileImage size={14} className="text-indigo-500" /><span>Receipt</span></div>
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {isLoading && !bills.length ? (
              <tr>
                <td colSpan={12} className="py-12 text-center text-sm font-medium text-slate-400">
                  <span className="inline-flex items-center gap-2">
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-slate-300 border-t-emerald-600" aria-hidden="true" />
                    {t("ops.fuel.loading")}
                  </span>
                </td>
              </tr>
            ) : bills.length === 0 ? (
              <tr>
                <td colSpan={12} className="py-12 text-center text-[13px] font-medium text-slate-400">{t("ops.fuel.no_records")}</td>
              </tr>
            ) : (
              bills.map((bill, index) => {
                const isSelected = bill.id === selectedId;
                const isDeleted = bill.deleted === true || bill.status === "Deleted";
                return (
                  <tr
                    key={bill.id}
                    {...selection.getRowProps(bill, index)}
                    onDoubleClick={() => onView?.(bill)}
                    className={`cursor-pointer border-l-4 border-l-transparent outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-emerald-400 ${
                      isDeleted
                        ? "border-l-red-400 bg-red-50/50 hover:bg-red-50/80"
                        : isSelected
                          ? tableSelectedRowClass
                          : "hover:bg-slate-50/80"
                    }`}
                  >
                    <td className="px-4 py-5 text-center text-[13px] font-semibold text-slate-500">
                      <RowSelectMark selected={isSelected && !isDeleted} serialNo={startIndex + index + 1} label={`Fuel bill ${bill.billNo || bill.id} selected`} />
                    </td>
                    <td className="px-4 py-5 text-[13px] font-semibold whitespace-nowrap">
                      <button
                        type="button"
                        onClick={(event) => {
                          event.stopPropagation();
                          onView?.(bill);
                        }}
                        className={`cursor-pointer rounded-md underline-offset-4 transition-colors hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400 ${isDeleted ? "text-slate-500 line-through hover:text-slate-700" : "text-emerald-700 hover:text-emerald-900"}`}
                        aria-label={`View fuel bill ${bill.billNo || bill.id}`}
                      >
                        {bill.billNo || "—"}
                      </button>
                    </td>
                    <td className="whitespace-nowrap px-4 py-5 text-[13px] font-medium text-slate-600">{formatTripListDay(bill.date, language)}</td>
                    <td className="whitespace-nowrap px-4 py-5 text-[13px]"><FuelTripLoadCell bill={bill} /></td>
                    <td className="whitespace-nowrap px-4 py-5 text-[13px] font-semibold text-slate-700">{localizeTripViewText(formatVehicleNumber(bill.vehicleNo), language)}</td>
                    <td className="whitespace-nowrap px-4 py-5 text-[13px]">
                      <div className="font-semibold text-slate-700">{localizeTripViewText(bill.supervisorName || "—", language)}</div>
                      <div className="mt-0.5 text-[11px] font-semibold text-slate-500">{localizeTripViewText(bill.driverName || "—", language)}</div>
                    </td>
                    <td className="whitespace-nowrap px-4 py-5 text-center text-[13px] font-bold tabular-nums text-slate-700">
                      {bill.meterReading > 0 ? bill.meterReading.toLocaleString() : "—"}
                    </td>
                    <td className="whitespace-nowrap px-4 py-5 text-center text-[13px] font-bold tabular-nums text-cyan-700">{Number(bill.litres || 0).toFixed(2)}</td>
                    <td className="whitespace-nowrap px-4 py-5 text-center text-[13px] font-bold tabular-nums text-violet-600">{Number(bill.rate || 0).toFixed(2)}</td>
                    <td className="whitespace-nowrap px-4 py-5 text-center text-[13px] font-bold tabular-nums text-slate-700">{Number(bill.amount || 0).toFixed(2)}</td>
                    <td className="max-w-[220px] px-4 py-5 text-[13px] font-semibold text-slate-700">
                      <BunkGpsTooltip
                        bunk={localizeTripViewText(bill.petrolBunk || "—", language)}
                        address={bill.gpsAddress}
                        lat={bill.gpsLat}
                        lon={bill.gpsLon}
                      />
                    </td>
                    <td className="whitespace-nowrap px-4 py-5 text-center" onClick={(event) => event.stopPropagation()}>
                      {bill.image ? (
                        <BillPreviewLink href={bill.image} fileName={bill.imageName || `${bill.billNo}.png`} />
                      ) : (
                        <span className="text-[13px] text-slate-400">—</span>
                      )}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
          {filteredTotals && filteredTotals.records > 0 && <tfoot className="border-t-2 border-slate-200 bg-slate-50/90"><tr>
            <td className="px-4 py-4 text-center font-bold text-slate-500">Σ</td>
            <td colSpan={5} className="px-4 py-4 text-left"><div className="text-sm font-extrabold text-emerald-700">Overall Total</div><div className="text-[11px] font-medium text-slate-500">{filteredTotals.records} filtered bills · not just this page</div><div className="mt-1 text-[11px] font-bold tabular-nums text-slate-600">Total Distance: {filteredTotals.distance != null ? `${filteredTotals.distance.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} km` : "—"} · Avg Mileage: {filteredTotals.mileage != null ? `${filteredTotals.mileage.toFixed(2)} km/L` : "—"}</div></td>
            <td className="px-4 py-4 text-center text-slate-400">—</td>
            <td className="px-4 py-4 text-center text-sm font-extrabold tabular-nums text-cyan-700">{filteredTotals.litres.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} L</td>
            <td className="px-4 py-4 text-center text-slate-400">—</td>
            <td className="px-4 py-4 text-center text-sm font-extrabold tabular-nums text-emerald-700">₹{filteredTotals.amount.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            <td colSpan={2} />
          </tr></tfoot>}
        </table>
      </div>
    </div>
  );
}

export default React.memo(FuelBillTable);

// src/modules/operations/fuel-expenses/components/FuelViewModal.tsx
//
// Fuel record view — the same global-view shell as the Trip List and Maintenance view
// (AppShellModal: overlay below the header, ESC to close, fade + scale panel).
// Two-panel split layout:
// - LEFT: Generous expanded sidebar (w-96) listing every approved fuel entry of this vehicle
//   (newest first), filterable by source (Trip / Manual), with roving keyboard navigation,
//   GPS indicators with address tooltip, and receipt thumbnail previews.
// - RIGHT: Full detail breakdown — identity, vehicle, driver, odometer, quantity, rate,
//   total cost, bunk, full-width GPS address block with direct Google Maps Location URL,
//   receipt lightbox and operator remarks.
// - FOOTER: Professional DMR branded PDF export (bill + vehicle history), in-view Edit (if pending) and Close.

import React, { useState, useRef, useMemo, useCallback } from "react";
import { 
  X, 
  Truck, 
  User, 
  MapPin,
  MessageSquare,
  Fuel,
  CheckCircle2,
  Clock,
  AlertCircle,
  FileText,
  FileDown,
  IndianRupee,
  Pencil,
  Image as ImageIcon,
  ExternalLink,
  Copy,
  Check,
} from "lucide-react";
import AppShellModal from "../../../../ui/AppShellModal";
import type { FuelExpense } from "../types/fuelExpense";
import type { FuelQuickTab } from "../utils/filterFuelExpenses";
import { formatVehicleNumber } from "../../../../utils/format";
import { formatTripListDay } from "../../vehicle-trips/utils/formatTripListDay";
import { localizeTripViewText } from "../../vehicle-trips/utils/tripViewLocalization";
import { TripNoBadge } from "../../vehicle-trips/components/TripNoBadge";
import { GpsAddressText } from "../../vehicle-trips/components/GpsAddressText";
import { BillPreviewLink } from "../../vehicle-trips/components/Step_5/BillPreviewLink";
import { ScopedI18nProvider, useI18n, translateStatus } from "../../../../i18n";
import { ViewLanguageToggle } from "../../../../ui/ViewLanguageToggle";
import { uiActionIconMotionClass, uiPdfButtonClass } from "../../../../shared/ui/uiTokens";
import { generateFuelPdf } from "../utils/generateFuelPdf";
import { googleMapsUrl, resolveFuelGps } from "../utils/fuelGps";
import MasterDropdown from "../../../masters/components/MasterDropdown";

export interface FuelViewModalProps {
  isOpen: boolean;
  bill: FuelExpense | null;
  vehicles?: any[];
  /** Every fuel record of this vehicle till now (newest first) — shown in the left panel */
  vehicleBills?: FuelExpense[];
  /** Set when the record can still be edited — shows the in-view Edit action. */
  canEdit?: boolean;
  /** Active status tab context (ALL, PENDING, APPROVED, DELETED) */
  activeTab?: FuelQuickTab;
  /** Edit from inside the view — closes the modal and loads the form. */
  onEdit?: (bill: FuelExpense) => void;
  onClose: () => void;
}

function FuelViewModalContent({
  isOpen,
  bill,
  vehicles = [],
  vehicleBills = [],
  canEdit = false,
  activeTab,
  onEdit,
  onClose,
}: FuelViewModalProps) {
  const { t, language, toggleLanguage } = useI18n();
  const [sourceFilter, setSourceFilter] = useState("");
  const [pdfBusy, setPdfBusy] = useState(false);
  const [copiedUrl, setCopiedUrl] = useState(false);

  // The record whose details are displayed. Clicking a row in the vehicle's
  // history swaps it in — identical to Maintenance ViewModal.
  const [active, setActive] = useState<FuelExpense | null>(bill);
  const [lastBill, setLastBill] = useState<FuelExpense | null>(bill);

  if (bill !== lastBill) {
    setLastBill(bill);
    setActive(bill);
  }

  // Find vehicle record for formatting if available
  const currentRecord = active || bill;
  const vehicleObj = currentRecord
    ? vehicles.find(
        (v: any) =>
          String(v.id) === String(currentRecord.vehicleId) ||
          String(v.vehicleNumber || "").toLowerCase() === String(currentRecord.vehicleNo || "").toLowerCase()
      )
    : null;

  const rawVehicleNo = vehicleObj?.vehicleNumber || currentRecord?.vehicleNo || "";
  const vehicleNumber = formatVehicleNumber(rawVehicleNo);

  const isDeleted = currentRecord?.deleted === true || currentRecord?.status === "Deleted";
  const isTrip = currentRecord?.sourceType === "TRIP" || !!currentRecord?.tripNo || !!currentRecord?.tripId;
  const isApproved = !isDeleted && (isTrip || currentRecord?.status === "Approved");
  const isPending = !isDeleted && !isTrip && !isApproved;

  const effectiveTab: FuelQuickTab = activeTab
    ? activeTab
    : isDeleted
    ? "DELETED"
    : isPending
    ? "PENDING"
    : isApproved
    ? "APPROVED"
    : "ALL";

  const sidebarTitle =
    effectiveTab === "APPROVED"
      ? t("ops.fuel.approved_fuel_history") || "Approved Fuel History"
      : effectiveTab === "PENDING"
      ? t("ops.fuel.pending_fuel_bills") || "Pending Fuel Bills"
      : effectiveTab === "DELETED"
      ? t("ops.fuel.deleted_fuel_bills") || "Deleted Fuel Bills"
      : t("ops.fuel.vehicle_fuel_history") || "Vehicle Fuel History";

  /** LEFT PANEL list — filtered vehicle entries matching active tab context:
   *  - APPROVED tab: ONLY Approved bills of this vehicle
   *  - PENDING tab: ONLY Pending bills of this vehicle
   *  - DELETED tab: ONLY Deleted bills of this vehicle
   *  - ALL tab: All active bills of this vehicle
   *  newest first, narrowable by source (Trip / Manual). */
  const vehicleHistory = useMemo(() => {
    if (!vehicleBills.length && currentRecord) return [currentRecord];
    const filtered = vehicleBills
      .filter((r) => {
        const isRecDel = r.deleted === true || r.status === "Deleted";
        const isRecTrp = r.sourceType === "TRIP" || !!r.tripNo;
        const isRecApp = !isRecDel && (isRecTrp || r.status === "Approved");
        const isRecPnd = !isRecDel && !isRecTrp && r.status === "Pending";

        if (effectiveTab === "APPROVED") {
          if (!isRecApp && r.id !== currentRecord?.id) return false;
        } else if (effectiveTab === "PENDING") {
          if (!isRecPnd && r.id !== currentRecord?.id) return false;
        } else if (effectiveTab === "DELETED") {
          if (!isRecDel && r.id !== currentRecord?.id) return false;
        } else {
          // ALL tab: active rows only
          if (isRecDel && r.id !== currentRecord?.id) return false;
        }

        if (sourceFilter === "TRIP" && !isRecTrp) return false;
        if (sourceFilter === "MANUAL" && isRecTrp) return false;
        return true;
      })
      .sort((a, b) => new Date(b.date || b.createdDate || 0).getTime() - new Date(a.date || a.createdDate || 0).getTime());

    if (currentRecord && !filtered.some((f) => f.id === currentRecord.id)) {
      filtered.unshift(currentRecord);
    }
    return filtered;
  }, [vehicleBills, currentRecord, effectiveTab, sourceFilter]);

  // Roving focus for the left list — ArrowUp/Down moves the active record.
  const listRefs = useRef(new Map<string, HTMLButtonElement>());
  const moveActive = (fromId: string, step: 1 | -1) => {
    const index = vehicleHistory.findIndex((r) => String(r.id) === fromId);
    const next = vehicleHistory[index + step];
    if (!next) return;
    setActive(next);
    const element = listRefs.current.get(String(next.id));
    if (element) {
      element.focus();
      element.scrollIntoView({ block: "nearest" });
    }
  };

  const handleDownloadPdf = useCallback(async () => {
    if (!currentRecord || pdfBusy) return;
    setPdfBusy(true);
    try {
      await generateFuelPdf(
        currentRecord,
        vehicleHistory,
        vehicleNumber,
        language,
        t
      );
    } finally {
      setPdfBusy(false);
    }
  }, [currentRecord, vehicleHistory, vehicleNumber, language, t, pdfBusy]);

  if (!isOpen || !currentRecord) return null;

  const vehicleDisplay = localizeTripViewText(vehicleNumber, language);
  const driverDisplay = localizeTripViewText(currentRecord.driverName || "—", language);
  const bunkDisplay = localizeTripViewText(currentRecord.petrolBunk || "—", language);

  const statusLabel = isDeleted
    ? translateStatus(t, "Deleted")
    : isApproved
    ? isTrip
      ? t("ops.fuel.approved_trip_completion")
      : translateStatus(t, "Approved")
    : translateStatus(t, "Pending");

  const statusPillClass = isDeleted
    ? "text-rose-700 bg-rose-50 border-rose-200"
    : isApproved
    ? "text-emerald-700 bg-emerald-50 border-emerald-200"
    : "text-blue-700 bg-blue-50 border-blue-200";

  const statusIcon = isDeleted ? (
    <AlertCircle size={13} className="text-rose-600" />
  ) : isApproved ? (
    <CheckCircle2 size={13} className="text-emerald-600" />
  ) : (
    <Clock size={13} className="text-blue-500" />
  );

  const currentGps = resolveFuelGps(currentRecord.gpsLat, currentRecord.gpsLon, currentRecord.gpsAddress);
  const hasGpsCoords = currentGps.lat != null && currentGps.lon != null;
  const mapsLocationUrl =
    currentGps.lat != null && currentGps.lon != null ? googleMapsUrl(currentGps.lat, currentGps.lon) : "";

  const handleCopyMapsUrl = () => {
    if (!mapsLocationUrl) return;
    navigator.clipboard.writeText(mapsLocationUrl);
    setCopiedUrl(true);
    setTimeout(() => setCopiedUrl(false), 2000);
  };

  const showEdit = Boolean(canEdit && onEdit && !isApproved && !isDeleted);

  return (
    <AppShellModal open={isOpen} onClose={onClose} panelClassName="max-w-6xl" ariaLabelledBy="fuel-view-title">
      <div className="flex max-h-[calc(100vh-96px)] flex-col overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-2xl animate-scale-in">
        
        {/* ── Header — Identity + Vehicle + Status Pill + Language Toggle + Close ── */}
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 bg-gradient-to-r from-slate-50/80 via-white to-slate-50/80 px-6 py-4">
          <div className="flex min-w-0 flex-wrap items-center gap-3">
            <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-xl border border-emerald-100 bg-emerald-50/80 text-emerald-600 shadow-inner">
              <Fuel className="h-5 w-5" />
            </div>
            <div className="min-w-0">
              <h2 id="fuel-view-title" className="truncate text-base font-bold tracking-tight text-slate-800">
                {t("ops.fuel.bill_details", { billNo: currentRecord.billNo })}
              </h2>
              <p className="flex items-center gap-1.5 text-xs font-semibold text-slate-500">
                <Truck size={13} className="flex-shrink-0 text-slate-400" />
                <span>{vehicleDisplay}</span>
                <span className="text-slate-300">·</span>
                <User size={13} className="flex-shrink-0 text-slate-400" />
                <span>{driverDisplay}</span>
              </p>
            </div>
          </div>

          <div className="flex flex-shrink-0 items-center gap-2.5">
            {/* Status Pill */}
            <span className={`inline-flex items-center gap-1 rounded-full border px-3 py-1 text-xs font-bold shadow-sm ${statusPillClass}`}>
              {statusIcon}
              <span>{statusLabel}</span>
            </span>

            {/* Language Switcher */}
            <ViewLanguageToggle
              language={language}
              onToggle={toggleLanguage}
              tone="emerald"
              labelMode="target"
              ariaLabel={t("ops.fuel.popup_language_toggle")}
            />

            {/* Close Button */}
            <button
              type="button"
              onClick={onClose}
              aria-label={t("common.close")}
              className="group relative inline-flex h-9 w-9 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm transition-all hover:-translate-y-0.5 hover:border-red-100 hover:bg-red-50 hover:text-red-500 active:scale-95 cursor-pointer"
            >
              <span className={`inline-flex ${uiActionIconMotionClass.close}`}><X size={16} /></span>
            </button>
          </div>
        </div>

        {/* ── Body — Split Layout: Left Expanded Sidebar (w-96) + Right (Active record details) ── */}
        <div className="flex min-h-0 flex-1 flex-col lg:flex-row">
          
          {/* ── LEFT PANEL — Generous sidebar with filtered fuel entries of this vehicle ── */}
          <aside className="flex w-full flex-shrink-0 flex-col border-b border-slate-100 bg-slate-50/40 lg:w-[380px] lg:border-b-0 lg:border-r">
            <div className="flex items-center justify-between px-4 pt-4">
              <p className="flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-wider text-slate-500">
                <Truck size={13} className="flex-shrink-0 text-slate-400" />
                <span>{sidebarTitle}</span>
              </p>
              <span className="rounded-full bg-white px-2.5 py-0.5 text-[11px] font-bold tabular-nums text-slate-600 ring-1 ring-slate-200 shadow-xs">
                {vehicleHistory.length}
              </span>
            </div>

            {/* Source filter dropdown */}
            <div className="px-3 pt-2.5">
              <MasterDropdown
                hideLabel
                label={t("ops.fuel.source") || "Source"}
                value={sourceFilter}
                options={[
                  { value: "", label: t("common.all") },
                  { value: "TRIP", label: t("ops.fuel.trip_diesel") || "Trip Diesel" },
                  { value: "MANUAL", label: t("ops.fuel.manual_bill") || "Manual Bill" },
                ]}
                onChange={(next) => setSourceFilter(next || "")}
                placeholder={t("ops.fuel.source") || "Source"}
                allowClear
                className="w-full"
              />
            </div>

            {/* Scrollable list of vehicle fuel entries */}
            <div className="max-h-64 min-h-0 flex-1 overflow-y-auto p-3 lg:max-h-none space-y-2">
              {vehicleHistory.length === 0 ? (
                <p className="py-8 text-center text-xs font-medium text-slate-400">
                  {t("ops.fuel.no_records") || "No records found"}
                </p>
              ) : (
                vehicleHistory.map((rec) => {
                  const isSelected = String(rec.id) === String(currentRecord.id);
                  const isRecTrip = rec.sourceType === "TRIP" || !!rec.tripNo;
                  const recGps = resolveFuelGps(rec.gpsLat, rec.gpsLon, rec.gpsAddress);
                  const hasGps = recGps.lat != null && recGps.lon != null;
                  const hasImg = Boolean(rec.image);

                  return (
                    <button
                      key={rec.id}
                      ref={(element) => {
                        if (element && rec.id) listRefs.current.set(String(rec.id), element);
                        else if (rec.id) listRefs.current.delete(String(rec.id));
                      }}
                      type="button"
                      onClick={() => setActive(rec)}
                      onKeyDown={(event) => {
                        if (event.key === "ArrowDown") {
                          event.preventDefault();
                          moveActive(String(rec.id), 1);
                        } else if (event.key === "ArrowUp") {
                          event.preventDefault();
                          moveActive(String(rec.id), -1);
                        }
                      }}
                      className={`group flex w-full flex-col rounded-xl border p-3 text-left transition-all ${
                        isSelected
                          ? "border-emerald-500 bg-emerald-50/80 shadow-sm ring-1 ring-emerald-400 border-l-4 border-l-emerald-600"
                          : "border-slate-200/80 bg-white hover:border-slate-300 hover:bg-slate-50/80"
                      }`}
                    >
                      <div className="flex items-center justify-between gap-2">
                        <span className="text-xs font-bold text-slate-800">
                          {formatTripListDay(rec.date || rec.createdDate, language)}
                        </span>
                        <span
                          className={`inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-bold border ${
                            isRecTrip
                              ? "bg-emerald-50 text-emerald-700 border-emerald-200"
                              : "bg-blue-50 text-blue-700 border-blue-200"
                          }`}
                        >
                          {isRecTrip ? rec.tripNo || t("ops.fuel.trip_diesel") : t("ops.fuel.manual_entry")}
                        </span>
                      </div>

                      {/* Bill No & Bunk Name */}
                      <div className="mt-1 flex items-center justify-between gap-1 text-xs">
                        <span className="font-mono text-[11px] font-bold text-slate-700 truncate max-w-[130px]">
                          {rec.billNo}
                        </span>
                        <span className="text-[11px] text-slate-500 truncate max-w-[160px] text-right">
                          {rec.petrolBunk || "—"}
                        </span>
                      </div>

                      {/* Quantity, Cost & Feature Badges (GPS, Photo) */}
                      <div className="mt-1.5 flex items-center justify-between text-xs pt-1 border-t border-slate-100">
                        <div className="flex items-center gap-1.5">
                          <span className="font-bold tabular-nums text-blue-600">
                            {rec.litres.toFixed(2)} L
                          </span>
                          <span className="text-slate-300">·</span>
                          <span className="font-bold tabular-nums text-emerald-700">
                            ₹{rec.amount.toFixed(2)}
                          </span>
                        </div>

                        <div className="flex items-center gap-1">
                          {hasGps && (
                            <span 
                              className="inline-flex items-center text-emerald-600 bg-emerald-50 rounded p-0.5 border border-emerald-100" 
                              title={`GPS: ${recGps.lat!.toFixed(4)}°N, ${recGps.lon!.toFixed(4)}°E`}
                            >
                              <MapPin size={11} />
                            </span>
                          )}
                          {hasImg && (
                            <span 
                              className="inline-flex items-center text-blue-600 bg-blue-50 rounded p-0.5 border border-blue-100" 
                              title={t("ops.fuel.receipt_document")}
                            >
                              <ImageIcon size={11} />
                            </span>
                          )}
                        </div>
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </aside>

          {/* ── RIGHT PANEL — Full Details of the active record ── */}
          <div className="min-w-0 flex-1 overflow-y-auto p-6 space-y-4">
            
            {/* Identity & 2-Column Key Metrics / Attribute Pairs */}
            <section className="animate-fade-in-up">
              <div className="grid grid-cols-1 gap-3 lg:grid-cols-2">
                {(() => {
                  const rows: [string, React.ReactNode][] = [
                    [t("ops.fuel.bill_no"), <span className="font-mono font-bold text-slate-800">{currentRecord.billNo || "—"}</span>],
                    [t("common.date"), formatTripListDay(currentRecord.date || currentRecord.createdDate, language)],
                    [t("common.vehicle"), vehicleDisplay],
                    [t("common.driver"), driverDisplay],
                    [
                      t("ops.fuel.source"),
                      <span className="inline-flex items-center gap-1 font-semibold text-slate-800">
                        {isTrip ? t("ops.fuel.trip_diesel") : t("ops.fuel.manual_bill")}
                      </span>,
                    ],
                    [
                      t("ops.fuel.source_linked_trip"),
                      currentRecord.tripNo ? <TripNoBadge tripNo={currentRecord.tripNo} /> : <span className="text-slate-400">—</span>,
                    ],
                    [
                      t("ops.fuel.odometer_meter"),
                      currentRecord.meterReading > 0 ? (
                        <span className="tabular-nums font-bold text-slate-800">
                          {currentRecord.meterReading.toLocaleString("en-IN")} KM
                        </span>
                      ) : (
                        <span className="text-slate-400">{t("ops.fuel.not_recorded")}</span>
                      ),
                    ],
                    [
                      t("ops.fuel.litres"),
                      <span className="tabular-nums font-bold text-blue-600">{currentRecord.litres.toFixed(2)} L</span>,
                    ],
                    [
                      t("ops.fuel.rate_per_l"),
                      <span className="tabular-nums font-bold text-slate-700">₹ {currentRecord.rate.toFixed(2)}</span>,
                    ],
                    [
                      t("ops.fuel.total_cost"),
                      <span className="tabular-nums font-extrabold text-emerald-600">₹ {currentRecord.amount.toFixed(2)}</span>,
                    ],
                    [
                      t("ops.fuel.petrol_bunk"),
                      <span className="font-medium text-slate-800">{bunkDisplay}</span>,
                    ],
                    [t("common.status"), statusLabel],
                  ];

                  const half = Math.ceil(rows.length / 2);
                  const column = (items: [string, React.ReactNode][], first: boolean) => (
                    <dl className="overflow-hidden rounded-xl border border-slate-200 bg-white">
                      {items.map(([label, value], index) => (
                        <div
                          key={label}
                          className={`flex items-start justify-between gap-4 px-4 py-2.5 ${
                            index > 0 ? "border-t border-slate-100" : ""
                          } ${first ? "lg:border-r lg:border-slate-100" : ""} hover:bg-slate-50/60 transition-colors`}
                        >
                          <dt className="w-28 flex-shrink-0 text-[11px] font-bold uppercase tracking-wider text-slate-400 pt-0.5">
                            {label}
                          </dt>
                          <dd className="min-w-0 flex-1 break-words text-right text-[13px] font-bold text-slate-800">
                            {value}
                          </dd>
                        </div>
                      ))}
                    </dl>
                  );

                  return (
                    <>
                      {column(rows.slice(0, half), true)}
                      {column(rows.slice(half), false)}
                    </>
                  );
                })()}
              </div>
            </section>

            {/* GPS Location & Address Card with Interactive Google Maps Location URL */}
            <section className="animate-fade-in-up" style={{ animationDelay: "40ms" }}>
              <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-xs space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-[12px] uppercase font-bold text-slate-500 flex items-center gap-1.5">
                    <span className="h-6 w-6 rounded-lg bg-emerald-50 text-emerald-600 border border-emerald-100 flex items-center justify-center shrink-0">
                      <MapPin size={13} />
                    </span>
                    <span>{t("ops.trip.field.gps_address") || "GPS Location & Address"}</span>
                  </span>

                  {hasGpsCoords && (
                    <div className="flex items-center gap-2">
                      <a
                        href={mapsLocationUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-1 text-xs font-bold text-emerald-700 bg-emerald-50 hover:bg-emerald-100 px-2.5 py-1 rounded-lg border border-emerald-200 transition-colors shadow-xs"
                      >
                        <ExternalLink size={12} />
                        <span>Google Maps</span>
                      </a>
                      <button
                        type="button"
                        onClick={handleCopyMapsUrl}
                        className="inline-flex items-center gap-1 text-xs font-semibold text-slate-600 bg-slate-50 hover:bg-slate-100 px-2 py-1 rounded-lg border border-slate-200 transition-colors"
                        title="Copy Location URL"
                      >
                        {copiedUrl ? <Check size={12} className="text-emerald-600" /> : <Copy size={12} />}
                        <span>{copiedUrl ? "Copied" : "Copy URL"}</span>
                      </button>
                    </div>
                  )}
                </div>

                {hasGpsCoords ? (
                  <div className="space-y-1.5 pt-1">
                    <p className="text-[13px] font-semibold text-slate-800 break-words leading-relaxed">
                      <GpsAddressText
                        lat={currentGps.lat}
                        lon={currentGps.lon}
                        fallback={t("ops.trip.location_captured")}
                      />
                    </p>
                    <div className="flex flex-wrap items-center gap-3 text-[11px] pt-1 border-t border-slate-100">
                      <div className="font-mono text-emerald-700 font-semibold">
                        GPS: {currentGps.lat!.toFixed(6)}°N, {currentGps.lon!.toFixed(6)}°E
                      </div>
                      <span className="text-slate-300">·</span>
                      <a
                        href={mapsLocationUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-emerald-600 hover:text-emerald-700 hover:underline truncate max-w-xs font-medium"
                      >
                        {mapsLocationUrl}
                      </a>
                    </div>
                  </div>
                ) : (
                  <p className="text-xs font-semibold text-slate-400 italic">
                    {t("ops.trip.not_captured") || "Location not captured"}
                  </p>
                )}
              </div>
            </section>

            {/* Total Fuel Cost Band */}
            <section className="animate-fade-in-up" style={{ animationDelay: "80ms" }}>
              <div className="flex items-center justify-between gap-3 rounded-xl border border-emerald-100 bg-gradient-to-r from-emerald-50/80 via-white to-emerald-50/50 px-4 py-3">
                <span className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-wider text-emerald-700">
                  <IndianRupee size={15} className="flex-shrink-0" />
                  {t("ops.fuel.total_fuel_cost")}
                </span>
                <span className="text-lg font-bold tabular-nums text-emerald-700">
                  ₹ {Number(currentRecord.amount || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>
            </section>

            {/* Receipt Document Card with Preview Lightbox */}
            <section className="animate-fade-in-up" style={{ animationDelay: "120ms" }}>
              <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                  <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl bg-emerald-50 text-emerald-600 border border-emerald-200 shadow-xs">
                    <FileText size={20} />
                  </div>
                  <div>
                    <div className="text-xs font-bold text-slate-800">{t("ops.fuel.receipt_document")}</div>
                    <div className="text-[11px] text-slate-400">{t("ops.fuel.receipt_document_hint")}</div>
                  </div>
                </div>

                <div className="flex items-center gap-3 self-end sm:self-center">
                  {currentRecord.image ? (
                    <div className="flex items-center gap-2.5">
                      <img
                        src={currentRecord.image}
                        alt="Receipt thumbnail"
                        className="h-10 w-10 object-cover rounded-lg border border-slate-200 bg-slate-50"
                      />
                      <BillPreviewLink
                        href={currentRecord.image}
                        fileName={currentRecord.imageName || `${currentRecord.billNo}.png`}
                      />
                    </div>
                  ) : (
                    <span className="text-xs text-slate-400 font-medium italic">
                      {t("ops.fuel.not_uploaded")}
                    </span>
                  )}
                </div>
              </div>
            </section>

            {/* Remarks Callout (if any) */}
            {currentRecord.remarks && (
              <section className="animate-fade-in-up" style={{ animationDelay: "160ms" }}>
                <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-xs">
                  <div className="flex items-start gap-2.5">
                    <MessageSquare size={16} className="text-emerald-600 mt-0.5 flex-shrink-0" />
                    <div className="min-w-0">
                      <div className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                        {t("ops.fuel.remarks_operator_notes")}
                      </div>
                      <p className="text-xs sm:text-sm text-slate-700 font-medium leading-relaxed">
                        {localizeTripViewText(currentRecord.remarks, language)}
                      </p>
                    </div>
                  </div>
                </div>
              </section>
            )}

          </div>
        </div>

        {/* ── Footer — Professional PDF Export, Edit inside the view, Close ── */}
        <div className="flex items-center justify-end gap-3 rounded-b-2xl border-t border-slate-100 bg-gradient-to-r from-slate-50/80 via-white to-slate-50/80 px-6 py-4 shrink-0">
          <button
            type="button"
            onClick={handleDownloadPdf}
            disabled={pdfBusy}
            className={`group relative ${uiPdfButtonClass} disabled:opacity-60 cursor-pointer`}
            aria-label="PDF"
          >
            {pdfBusy ? (
              <span className="inline-flex h-4 w-4 animate-spin rounded-full border-2 border-rose-200 border-t-rose-500" aria-hidden="true" />
            ) : (
              <span className={`inline-flex ${uiActionIconMotionClass.pdf}`}><FileDown size={15} /></span>
            )}
            <span>PDF</span>
          </button>

          {showEdit && (
            <button
              type="button"
              onClick={() => onEdit?.(currentRecord)}
              className="group relative inline-flex items-center gap-2 rounded-2xl bg-blue-600 px-6 py-2.5 text-xs font-semibold text-white shadow-sm transition-all hover:bg-blue-700 active:scale-95 cursor-pointer"
            >
              <span className={`inline-flex ${uiActionIconMotionClass.edit}`}><Pencil size={15} /></span>
              <span>{t("common.edit")}</span>
            </button>
          )}

          <button
            type="button"
            onClick={onClose}
            className="group relative inline-flex items-center gap-2 rounded-2xl bg-slate-100 px-6 py-2.5 text-xs font-semibold text-slate-700 transition-all hover:bg-slate-200 active:scale-95 cursor-pointer"
            aria-label={t("common.close")}
          >
            <span className={`inline-flex ${uiActionIconMotionClass.close}`}><X size={15} /></span>
            <span>{t("common.close")}</span>
          </button>
        </div>

      </div>
    </AppShellModal>
  );
}

export function FuelViewModal(props: FuelViewModalProps) {
  const { language } = useI18n();
  return (
    <ScopedI18nProvider initialLanguage={language}>
      <FuelViewModalContent {...props} />
    </ScopedI18nProvider>
  );
}

export default React.memo(FuelViewModal);

import { useCallback, useEffect, useRef, useState } from "react";
import {
  fuelExpenseService,
  type FuelListMeta,
  type FuelListSummary,
} from "../services/fuelExpenseService";
import type { FuelExpense, FuelExpenseDraft } from "../types/fuelExpense";
import { useI18n } from "../../../../i18n";
import { isCanceledError } from "../../../../api/errors";

type NotificationFn = (msg: string, type?: "success" | "error" | "info") => void;
const FETCH_PAGE_SIZE = 200;

export function useFuelExpenses(showNotification?: NotificationFn) {
  const { t } = useI18n();
  const [expenses, setExpenses] = useState<FuelExpense[]>([]);
  const [deletedMap, setDeletedMap] = useState<Map<string, FuelExpense>>(new Map());
  const [meta, setMeta] = useState<FuelListMeta>({ total: 0, page: 1, limit: FETCH_PAGE_SIZE, totalPages: 1 });
  const [summary, setSummary] = useState<FuelListSummary>({
    totalLitres: 0,
    totalAmount: 0,
    pendingCount: 0,
    approvedCount: 0,
    totalDistance: null,
    avgMileage: null,
    recentTripMileage: null,
  });
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const requestSeqRef = useRef(0);
  const expensesRef = useRef(expenses);
  const deletedMapRef = useRef(deletedMap);
  useEffect(() => { expensesRef.current = expenses; }, [expenses]);
  useEffect(() => { deletedMapRef.current = deletedMap; }, [deletedMap]);

  const refresh = useCallback(async (quiet = false) => {
    const seq = requestSeqRef.current + 1;
    requestSeqRef.current = seq;
    const keepRows = quiet || expensesRef.current.length > 0;
    if (keepRows) setRefreshing(true);
    else setLoading(true);
    setError(null);
    try {
      const fetched: FuelExpense[] = [];
      let page = 1;
      let totalPages = 1;
      let lastMeta: FuelListMeta | null = null;
      let lastSummary: FuelListSummary | null = null;
      do {
        const result = await fuelExpenseService.list({ page, limit: FETCH_PAGE_SIZE, includeDeleted: true });
        if (requestSeqRef.current !== seq) return false;
        fetched.push(...result.data);
        lastMeta = result.meta;
        lastSummary = result.summary;
        totalPages = Math.max(1, result.meta.totalPages);
        page += 1;
      } while (page <= totalPages && page <= 20);

      const activeIds = new Set(fetched.map((row) => row.id));
      const combined = [...fetched];
      for (const [delId, delItem] of deletedMapRef.current.entries()) {
        if (!activeIds.has(delId)) combined.push(delItem);
      }
      setExpenses(combined);
      if (lastMeta) setMeta(lastMeta);
      if (lastSummary) setSummary(lastSummary);
      return true;
    } catch (err) {
      if (isCanceledError(err) || requestSeqRef.current !== seq) return false;
      const message = err instanceof Error ? err.message : "Failed to load fuel expenses.";
      setError(message);
      showNotification?.(message, "error");
      return false;
    } finally {
      if (requestSeqRef.current === seq) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, [showNotification]);

  useEffect(() => {
    void refresh();
    // First load only — later refreshes are explicit (toolbar / save).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const saveExpense = async (expense: FuelExpenseDraft) => {
    setIsSaving(true);
    try {
      await fuelExpenseService.save(expense);
      await refresh(true);
      return true;
    } catch (err) {
      showNotification?.(err instanceof Error ? err.message : "Failed to save fuel bill.", "error");
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  const updateExpense = async (id: string, updates: Partial<FuelExpense>) => {
    setIsSaving(true);
    try {
      await fuelExpenseService.update(id, updates);
      await refresh(true);
      return true;
    } catch (err) {
      showNotification?.(err instanceof Error ? err.message : "Failed to update fuel bill.", "error");
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  const deleteExpense = async (id: string) => {
    setIsSaving(true);
    try {
      const target = expenses.find((e) => e.id === id);
      await fuelExpenseService.remove(id);
      if (target) {
        const deletedRecord: FuelExpense = {
          ...target,
          status: "Deleted",
          deleted: true,
          deletedAt: new Date().toISOString(),
        };
        setDeletedMap((prev) => new Map(prev).set(id, deletedRecord));
        setExpenses((prev) => prev.map((e) => (e.id === id ? deletedRecord : e)));
      }
      // Refetch the canonical register so the table, KPI cards and footer
      // totals/mileage all reflect the backend state (filters/sort/tab/page
      // are owned by the page and therefore retained).
      await refresh(true);
      showNotification?.(t("ops.fuel.deleted_success"), "success");
      return true;
    } catch (err) {
      showNotification?.(err instanceof Error ? err.message : "Failed to delete fuel bill.", "error");
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  const approveExpense = async (id: string) => {
    setIsSaving(true);
    try {
      await fuelExpenseService.approve(id);
      showNotification?.(t("ops.fuel.approved_success"), "success");
      await refresh(true);
      return true;
    } catch (err) {
      showNotification?.(err instanceof Error ? err.message : "Failed to approve fuel bill.", "error");
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  return {
    expenses,
    filteredData: expenses,
    meta,
    summary,
    loading,
    refreshing,
    isSaving,
    error,
    refresh,
    saveExpense,
    updateExpense,
    deleteExpense,
    approveExpense,
  };
}

