import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { ShopSale, ShopSaleFilter } from "../types/shopSale";
import { createShopSale, listShopSales, updateShopSale, updateShopSalesLoad, type CreateShopSaleInput, type ShopSalePatch } from "../services/shopSalesApiService";
import { handleApiError } from "../../../../api";
import {
  calculateSummary,
  filterShopSales,
  listTripNumbersNewestFirst,
  paginateSales,
} from "../utils/shopSaleCalculation";
import { PAGINATION_DEFAULT_PAGE_SIZE } from "../../../../shared/ui/paginationStyles";
import { notifyShopDataChanged } from "../../../../shared/events/shopDataEvents";

const DEFAULT_FILTER: ShopSaleFilter = {
  fromDate: "",
  toDate: "",
  shopName: "",
  tripNo: "",
  search: "",
  sortBy: "latest",
};

/**
 * PostgreSQL (via shopSalesApiService) is the single source of truth for
 * Shop Sales — no localStorage read or write happens anywhere in this
 * hook. The backend's eligibility query (Rate Entry locked) is never
 * re-derived here; this hook only filters/sorts/paginates whatever the
 * backend already decided is eligible.
 */
function useShopSales() {
  const [sales, setSales] = useState<ShopSale[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState<ShopSaleFilter>({ ...DEFAULT_FILTER });
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(PAGINATION_DEFAULT_PAGE_SIZE);
  const mountedRef = useRef(false);
  const requestSequenceRef = useRef(0);

  // Keep a latest-request guard so fast filter changes, manual refreshes and
  // Strict Mode's development effect replay cannot overwrite fresh rows with
  // a late response from an earlier request.
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      requestSequenceRef.current += 1;
    };
  }, []);

  const refreshSales = useCallback(async (options?: { silent?: boolean }) => {
    const requestSequence = requestSequenceRef.current + 1;
    requestSequenceRef.current = requestSequence;
    if (!options?.silent) setIsLoading(true);
    try {
      const data = await listShopSales({
        fromDate: filter.fromDate || undefined,
        toDate: filter.toDate || undefined,
        search: filter.search || undefined,
        sortBy: filter.sortBy || undefined,
      });
      if (!mountedRef.current || requestSequence !== requestSequenceRef.current) return false;
      setSales(data);
      return true;
    } catch (error) {
      if (!mountedRef.current || requestSequence !== requestSequenceRef.current) return false;
      handleApiError(error);
      // Do not fall back to stale/fake data on failure — an empty,
      // clearly-not-current list is preferable to silently showing data
      // that no longer reflects PostgreSQL.
      setSales([]);
      return false;
    } finally {
      if (mountedRef.current && requestSequence === requestSequenceRef.current) {
        setIsLoading(false);
      }
    }
  }, [filter.fromDate, filter.toDate, filter.search, filter.sortBy]);

  // Re-fetch from the backend whenever the server-side filters actually
  // change — this is the "real backend filtering" the from/to date and
  // search fields now drive, replacing the old client-only filtering for
  // those fields specifically. Shop-name filter and sort stay client-side
  // below, same as before.
  useEffect(() => {
    refreshSales();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filter.fromDate, filter.toDate, filter.search]);

  const updateSale = useCallback(
    async (updatedSale: ShopSale) => {
      const original = sales.find((s) => s.id === updatedSale.id);
      if (!original || original.numericId == null) {
        throw new Error("Shop sale not found");
      }

      // Only include fields that actually changed from the last-known
      // backend value. The existing table always builds a full row object
      // on save (including unchanged rate/shopName) — sending those
      // unconditionally would trip the backend's locked-field rejection on
      // every single edit, even a birds-only change. `amount` is never
      // sent at all; the backend always recomputes it from weight × the
      // locked rate.
      const patch: ShopSalePatch = {};
      if (updatedSale.totalBirds !== original.totalBirds) patch.birds = updatedSale.totalBirds;
      if (updatedSale.totalWeight !== original.totalWeight) patch.weight = updatedSale.totalWeight;
      if (updatedSale.numericShopId !== original.numericShopId) {
        patch.shopId = updatedSale.numericShopId ?? null;
        patch.shopName = updatedSale.shopName;
      }
      if (updatedSale.mortality !== original.mortality) patch.mortality = updatedSale.mortality ?? 0;
      if (updatedSale.mortalityWeight !== original.mortalityWeight) patch.mortalityWeight = updatedSale.mortalityWeight ?? 0;
      if (updatedSale.deliveryMode !== original.deliveryMode) patch.deliveryMode = updatedSale.deliveryMode;
      if (updatedSale.rate !== original.rate && updatedSale.rate != null) patch.rate = updatedSale.rate;
      if (updatedSale.remark !== original.remark) patch.remarks = updatedSale.remark;
      if (Object.keys(patch).length === 0) {
        return updatedSale;
      }

      try {
        const saved = await updateShopSale(original.numericId, patch);
        setSales((prev) => prev.map((s) => (s.id === saved.id ? saved : s)));
        // A Shop Sales mutation changes the ledger's financial row and/or
        // delivery quantities. Notify both sides of a reassignment so every
        // open Shop Ledger (including another tab) immediately re-reads the
        // server-authoritative statement.
        notifyShopDataChanged({
          shopId: original.numericShopId ?? null,
          shopName: original.shopName,
          reason: "updated",
          source: "shop-sales",
        });
        if (saved.numericShopId !== original.numericShopId) {
          notifyShopDataChanged({
            shopId: saved.numericShopId ?? null,
            shopName: saved.shopName,
            reason: "updated",
            source: "shop-sales",
          });
        }
        return saved;
      } catch (error) {
        // Don't leave the optimistic/invalid value displayed — reload the
        // authoritative record from PostgreSQL so the row reverts to the
        // real current state (e.g. after a 409 rate-lock rejection, or a
        // 422 capacity rejection, or a concurrent edit by someone else).
        await refreshSales();
        throw error;
      }
    },
    [sales, refreshSales]
  );

  const addSale = useCallback(async (input: CreateShopSaleInput) => {
    const saved = await createShopSale(input);
    setSales((prev) => [...prev, saved]);
    notifyShopDataChanged({
      shopId: saved.numericShopId ?? input.shopId,
      shopName: saved.shopName ?? input.shopName,
      reason: "created",
      source: "shop-sales",
    });
    return saved;
  }, []);

  const saveLoad = useCallback(async (tripId: number, rows: Parameters<typeof updateShopSalesLoad>[1]) => {
    const saved = await updateShopSalesLoad(tripId, rows);
    setSales((previous) => {
      const retained = previous.filter((sale) => sale.numericTripId !== tripId);
      return [...retained, ...saved];
    });
    for (const sale of saved) {
      notifyShopDataChanged({
        shopId: sale.numericShopId ?? null,
        shopName: sale.shopName,
        reason: "updated",
        source: "shop-sales",
      });
    }
    return saved;
  }, []);

  const shopNames = useMemo(() => {
    return [...new Set(sales.map((x) => x.shopName))].sort();
  }, [sales]);

  const tripNumbers = useMemo(() => {
    return listTripNumbersNewestFirst(sales);
  }, [sales]);

  const filteredSales = useMemo(() => {
    return filterShopSales(sales, filter);
  }, [sales, filter]);

  const totalPages = Math.max(1, Math.ceil(filteredSales.length / pageSize));

  // A changed filter or page size can reduce the page count. Clamp the page
  // before slicing so the table never appears blank on a now-invalid page.
  useEffect(() => {
    setCurrentPage((page) => Math.min(Math.max(1, page), totalPages));
  }, [totalPages]);

  const paginatedSales = useMemo(() => {
    return paginateSales(filteredSales, currentPage, pageSize);
  }, [filteredSales, currentPage, pageSize]);

  const summary = useMemo(() => calculateSummary(filteredSales), [filteredSales]);

  const resetFilters = useCallback(() => {
    setFilter({ ...DEFAULT_FILTER });
    setCurrentPage(1);
  }, []);

  return {
    sales,
    filteredSales,
    paginatedSales,
    summary,
    filter,
    setFilter,
    shopNames,
    tripNumbers,
    currentPage,
    setCurrentPage,
    pageSize,
    setPageSize,
    totalPages,
    resetFilters,
    refreshSales,
    isLoading,
    updateSale,
    addSale,
    saveLoad,
  };
}

export default useShopSales;

