import { useEffect, useState } from "react";
import { reverseGeocode } from "../utils/reverseGeocode";

export type AddressStatus = "idle" | "resolving" | "resolved" | "failed";

export interface ReverseGeocodedAddress {
  status: AddressStatus;
  address: string | null;
}

/** Resolves a single (lat, lon) pair to an address once. Re-resolves whenever
 * the coordinates change. */
export function useReverseGeocodedAddress(
  lat?: number | string | null,
  lon?: number | string | null
): ReverseGeocodedAddress {
  const latNum = lat === undefined || lat === null || lat === "" ? null : Number(lat);
  const lonNum = lon === undefined || lon === null || lon === "" ? null : Number(lon);
  const [state, setState] = useState<ReverseGeocodedAddress>({
    status: latNum === null || lonNum === null || !Number.isFinite(latNum) || !Number.isFinite(lonNum) ? "idle" : "resolving",
    address: null,
  });

  useEffect(() => {
    let cancelled = false;
    if (latNum === null || lonNum === null || !Number.isFinite(latNum) || !Number.isFinite(lonNum)) {
      setState({ status: "idle", address: null });
      return;
    }
    setState({ status: "resolving", address: null });
    reverseGeocode(latNum, lonNum).then(({ address, error }) => {
      if (cancelled) return;
      setState({ status: error ? "failed" : "resolved", address });
    });
    return () => {
      cancelled = true;
    };
  }, [latNum, lonNum]);

  return state;
}

import { useState, useRef, useCallback, useEffect, type Dispatch, type SetStateAction } from "react";
import type { Trip, ShopDelivery, BoxDetail, TripStatus } from "../../../../shared/trip/types";
import {
  handleApiError,
  loadTripById,
  saveTripDeliveries,
  saveTripStepProgress,
  submitStep1,
  submitTripStep,
} from "../services/tripHeaderApiService";
import {
  applyDeliveryMetrics,
  calculatePickupTotals,
  createEmptyTrip,
  validateStartStep,
  validateFarmStep,
  validatePickupStep,
  validateDeliveriesStep,
  validateEndStep,
} from "../../../../shared/trip";
import { translate } from "../../../../i18n";
import { translateValidationMessage } from "../utils/translateValidation";

type NotificationFn = (msg: string, type?: "success" | "error" | "info") => void;

/**
 * Keep a user-selected load active after the backend returns a refreshed trip.
 * Step submission may point `activeLegIndex` at the next incomplete load; that
 * is useful for first-time workflow progression, but must not move an operator
 * away from the load they are currently editing.
 */
export function withActiveTripLeg(trip: Trip, legIndex: number): Trip {
  const normalizedIndex = Math.max(1, Math.trunc(Number(legIndex) || 1));
  const leg = trip.legs?.find((candidate) => Number(candidate.legIndex) === normalizedIndex);
  if (!leg) return { ...trip, activeLegIndex: normalizedIndex };

  return {
    ...trip,
    activeLegIndex: normalizedIndex,
    sourceFarmId: Number(leg.sourceFarmId ?? 0),
    sourceFarm: String(leg.sourceFarm ?? ""),
    destMeter: Number(leg.destMeter ?? 0),
    pickupTolls: Number(leg.pickupTolls ?? 0),
    farmAddress: leg.farmAddress ?? "",
    avgBirdWeight: Number(leg.avgBirdWeight ?? 0),
    birdTypeId: Number(leg.farmBirdTypeId ?? trip.birdTypeId ?? 0),
    birdType: String(leg.farmBirdType ?? trip.birdType ?? ""),
    farmGpsLat: leg.farmGpsLat ?? null,
    farmGpsLon: leg.farmGpsLon ?? null,
    farmGpsAccuracy: leg.farmGpsAccuracy ?? null,
    farmGpsTime: leg.farmGpsTime ?? null,
    farmStepSubmitted: Boolean(leg.farmStepSubmitted),
    farmStepSubmittedAt: leg.farmStepSubmittedAt ?? null,
    reachedTime: leg.reachedTime ?? "",
    dcWeight: Number(leg.dcWeight ?? 0),
    totalBirds: Number(leg.totalBirds ?? 0),
    boxes: Number(leg.boxes ?? 0),
    avgWeight: Number(leg.avgWeight ?? 0),
    pickupLoadTime: leg.pickupLoadTime ?? "",
    dcPhotoKey: leg.dcPhotoKey ?? undefined,
    pickupStepSubmitted: Boolean(leg.pickupStepSubmitted),
    pickupStepSubmittedAt: leg.pickupStepSubmittedAt ?? null,
    deliveryStepSubmitted: Boolean(leg.deliveryStepSubmitted),
    boxDetails: leg.boxDetails ?? [],
    deliveries: (leg.deliveries as Trip["deliveries"]) ?? [],
  };
}

export function useTripEntry(
  showNotification?: NotificationFn,
  onTripsChanged?: () => void
) {
  const notifyRef = useRef(showNotification);
  const onTripsChangedRef = useRef(onTripsChanged);

  const emptyTrip = createEmptyTrip;

  const [trip, setTrip] = useState<Trip>(emptyTrip);
  const [savedTrip, setSavedTrip] = useState<Trip>(emptyTrip);
  const tripRef = useRef(trip);
  useEffect(() => {
    notifyRef.current = showNotification;
    onTripsChangedRef.current = onTripsChanged;
    tripRef.current = trip;
  }, [onTripsChanged, showNotification, trip]);

  const [isEditing, setIsEditing] = useState(false);
  const [endStepSubmitted, setEndStepSubmitted] = useState<boolean>(false);
  const [headerLoading, setHeaderLoading] = useState(false);

  const onTripIdAssignedRef = useRef<((id: number) => void) | null>(null);
  const onStep1SuccessRef = useRef<((trip: Trip) => void) | null>(null);
  /** Same-tick double-click guard — React `headerLoading` is one render too late. */
  const startSubmitLockRef = useRef(false);
  /** Per-step operation locks prevent double-click duplicate submits/saves. */
  const operationLocksRef = useRef<Set<string>>(new Set());
  /** Latest-wins guard for rapid Load 1 / Load 2 switching. */
  const selectLegRequestSeqRef = useRef(0);
  const onStep2SuccessRef = useRef<((trip: Trip) => void) | null>(null);
  const onStep3SuccessRef = useRef<((trip: Trip) => void) | null>(null);
  const onStep4SuccessRef = useRef<((trip: Trip) => void) | null>(null);

  const syncEndStep = (tripData: Trip) => {
    setEndStepSubmitted(tripData.endStepSubmitted || false);
  };

  /** URL synchronization is only used after loading an existing permanent trip. */
  const registerTripIdCallback = useCallback((cb: (id: number) => void) => {
    onTripIdAssignedRef.current = cb;
  }, []);

  /** Parent registers post-submit UI reset (Recent Trips already refreshed via onTripsChanged). */
  const registerStep1SuccessCallback = useCallback((cb: (trip: Trip) => void) => {
    onStep1SuccessRef.current = cb;
  }, []);

  const registerStep2SuccessCallback = useCallback((cb: (trip: Trip) => void) => {
    onStep2SuccessRef.current = cb;
  }, []);

  const registerStep3SuccessCallback = useCallback((cb: (trip: Trip) => void) => {
    onStep3SuccessRef.current = cb;
  }, []);

  const registerStep4SuccessCallback = useCallback((cb: (trip: Trip) => void) => {
    onStep4SuccessRef.current = cb;
  }, []);

  const subscribeHeaderSaveStatus = useCallback(() => () => {}, []);
  const getHeaderSaveStatus = useCallback(
    (): "idle" | "saving" | "saved" => "idle",
    []
  );

  const acquireOperationLock = (key: string) => {
    if (operationLocksRef.current.has(key)) return false;
    operationLocksRef.current.add(key);
    return true;
  };
  const releaseOperationLock = (key: string) => {
    operationLocksRef.current.delete(key);
  };

  /** Step 1 edits update React state only — no localStorage, no backend. */
  const applyStartFieldChange = useCallback(
    (updater: Trip | ((prev: Trip) => Trip)) => {
      setTrip((previous) => {
        const next =
          typeof updater === "function" ? updater(previous) : { ...previous, ...updater };
        tripRef.current = next;
        return next;
      });
    },
    []
  );

  const setStartTrip: Dispatch<SetStateAction<Trip>> = useCallback(
    (action) => {
      applyStartFieldChange(action);
    },
    [applyStartFieldChange]
  );

  const updateStartTrip = useCallback(
    (updates: Partial<Trip>) => {
      applyStartFieldChange((prev) => ({ ...prev, ...updates }));
    },
    [applyStartFieldChange]
  );

  const loadTripFromApi = useCallback(async (id: number): Promise<Trip | null> => {
    setHeaderLoading(true);
    try {
      const loaded = await loadTripById(id);
      const resumeLeg = Math.max(
        1,
        Number(
          loaded.activeLegIndex ??
            loaded.legs?.find((leg) => !leg.deliveryStepSubmitted)?.legIndex ??
            1
        )
      );
      const leg = loaded.legs?.find((l) => l.legIndex === resumeLeg);
      const withActive: Trip = leg
        ? {
            ...loaded,
            activeLegIndex: resumeLeg,
            sourceFarmId: Number(leg.sourceFarmId ?? loaded.sourceFarmId ?? 0),
            sourceFarm: String(leg.sourceFarm ?? loaded.sourceFarm ?? ""),
            destMeter: Number(leg.destMeter ?? loaded.destMeter ?? 0),
            pickupTolls: Number(leg.pickupTolls ?? loaded.pickupTolls ?? 0),
            farmAddress: leg.farmAddress ?? loaded.farmAddress ?? "",
            avgBirdWeight: Number(leg.avgBirdWeight ?? loaded.avgBirdWeight ?? 0),
            birdTypeId: Number(leg.farmBirdTypeId ?? loaded.birdTypeId ?? 0),
            birdType: String(leg.farmBirdType ?? loaded.birdType ?? ""),
            farmGpsLat: leg.farmGpsLat ?? loaded.farmGpsLat ?? null,
            farmGpsLon: leg.farmGpsLon ?? loaded.farmGpsLon ?? null,
            farmGpsAccuracy: leg.farmGpsAccuracy ?? loaded.farmGpsAccuracy ?? null,
            farmGpsTime: leg.farmGpsTime ?? loaded.farmGpsTime ?? null,
            farmStepSubmitted: Boolean(leg.farmStepSubmitted),
            farmStepSubmittedAt: leg.farmStepSubmittedAt ?? null,
            reachedTime: leg.reachedTime ?? loaded.reachedTime ?? "",
            dcWeight: Number(leg.dcWeight ?? loaded.dcWeight ?? 0),
            totalBirds: Number(leg.totalBirds ?? loaded.totalBirds ?? 0),
            boxes: Number(leg.boxes ?? loaded.boxes ?? 0),
            avgWeight: Number(leg.avgWeight ?? loaded.avgWeight ?? 0),
            pickupLoadTime: leg.pickupLoadTime ?? loaded.pickupLoadTime ?? "",
            dcPhotoKey: leg.dcPhotoKey ?? loaded.dcPhotoKey,
            pickupStepSubmitted: Boolean(leg.pickupStepSubmitted),
            pickupStepSubmittedAt: leg.pickupStepSubmittedAt ?? null,
            deliveryStepSubmitted: Boolean(leg.deliveryStepSubmitted),
            boxDetails: leg.boxDetails ?? loaded.boxDetails ?? [],
            deliveries: (leg.deliveries as Trip["deliveries"]) ?? loaded.deliveries ?? [],
          }
        : { ...loaded, activeLegIndex: resumeLeg };
      setTrip(withActive);
      setSavedTrip(withActive);
      tripRef.current = withActive;
      syncEndStep(withActive);
      setIsEditing(true);
      onTripIdAssignedRef.current?.(withActive.id);
      return withActive;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return null;
    } finally {
      setHeaderLoading(false);
    }
  }, []);

  const applySavedTrip = (saved: Trip) => {
    setTrip(saved);
    setSavedTrip(saved);
    tripRef.current = saved;
    syncEndStep(saved);
    setIsEditing(true);
    onTripsChangedRef.current?.();
  };

  const submitStartStep = async (data: Partial<Trip> = {}): Promise<boolean> => {
    if (startSubmitLockRef.current) return false;
    const merged = {
      ...tripRef.current,
      ...data,
    };
    const validation = validateStartStep(merged as Trip);
    if (!validation.valid) {
      return false;
    }

    startSubmitLockRef.current = true;
    setHeaderLoading(true);
    try {
      const submitted = await submitStep1({
        ...merged,
      });

      // First submit closes the wizard (parent success callback). Do not park
      // the saved trip in the working copy — that would flash a submitted
      // form before Create New Trip. Recent is refreshed via onTripsChanged.
      // Working fields stay as typed until the success callback resets them.
      onTripsChangedRef.current?.();
      notifyRef.current?.(translate("ops.trip.step1_submitted"), "success");
      onStep1SuccessRef.current?.(submitted);
      return true;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return false;
    } finally {
      startSubmitLockRef.current = false;
      setHeaderLoading(false);
    }
  };

  /** Update an ALREADY-SUBMITTED Step 1 (top-level Edit → "Update Start
   * Details"). Uses the existing-trip submit step endpoint (mode submit) so the
   * step STAYS submitted and the backend re-validates changed resources/meters
   * (self-excluded) — never a save-mode call that would strip start_step_submitted. */
  const updateStartStep = async (data: Partial<Trip> = {}): Promise<boolean> => {
    if (startSubmitLockRef.current) return false;
    const current = { ...tripRef.current, ...data };
    if (!current.id) {
      notifyRef.current?.(translate("ops.trip.trip_id_missing_start"), "error");
      return false;
    }

    const validation = validateStartStep(current as Trip);
    if (!validation.valid) {
      return false;
    }

    startSubmitLockRef.current = true;
    setHeaderLoading(true);
    try {
      const submitted = await submitTripStep(current.id, "start", {
        ...current,
        startStepSubmitted: true,
      });
      applySavedTrip(submitted);
      notifyRef.current?.(translate("ops.trip.step1_submitted"), "success");
      return true;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return false;
    } finally {
      startSubmitLockRef.current = false;
      setHeaderLoading(false);
    }
  };

  const submitFarmStep = async (data: Partial<Trip> = {}): Promise<boolean> => {
    const current = tripRef.current;
    if (!current.id) {
      notifyRef.current?.(translate("ops.trip.trip_id_missing"), "error");
      return false;
    }

    const wasSubmitted = Boolean(current.farmStepSubmitted);
    const tolls = Number(data.pickupTolls ?? current.pickupTolls ?? 0);
    const updatedData = {
      ...current,
      ...data,
      pickupTolls: Number.isFinite(tolls) && tolls < 0 ? 0 : Number.isFinite(tolls) ? tolls : 0,
    };

    const validation = validateFarmStep(updatedData as Trip);
    if (!validation.valid) {
      return false;
    }

    const lockKey = "submit:farm";
    if (!acquireOperationLock(lockKey)) return false;
    setHeaderLoading(true);
    try {
      const submitted = await submitTripStep(current.id, "farm", {
        ...updatedData,
        farmStepSubmitted: true,
      });
      applySavedTrip(submitted);
      notifyRef.current?.(translate("ops.trip.step2_submitted"), "success");
      if (!wasSubmitted) {
        onStep2SuccessRef.current?.(submitted);
      }
      return true;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return false;
    } finally {
      releaseOperationLock(lockKey);
      setHeaderLoading(false);
    }
  };

  const saveStepProgress = async (
    step: "start" | "farm" | "pickup" | "deliveries" | "expenses",
    data: Partial<Trip> = {},
    opts: { silent?: boolean } = {}
  ): Promise<boolean> => {
    const silent = Boolean(opts.silent);
    const current = { ...tripRef.current, ...data } as Trip;
    if (!current.id) {
      if (!silent) notifyRef.current?.(translate("ops.trip.submit_start_first"), "error");
      return false;
    }

    const validation =
      step === "farm"
        ? { valid: true, errors: [] as string[] }
        : step === "start"
        ? validateStartStep(current)
        : { valid: true, errors: [] as string[] };
    if (step !== "farm" && step !== "pickup" && !validation.valid) {
      return false;
    }

    const label = {
      start: "Start",
      farm: "Farm",
      pickup: "Pickup",
      deliveries: "Delivery",
      expenses: "End",
    }[step];
    const lockKey = silent ? `save-silent:${step}` : `save:${step}`;
    if (!acquireOperationLock(lockKey)) return false;
    // Silent background saves must never flash header loading or remount forms.
    if (!silent) setHeaderLoading(true);
    try {
      const saved = await saveTripStepProgress(current.id, step, current);
      if (silent) {
        // Keep the live working copy untouched. Only refresh concurrency
        // metadata — never setTrip / applySavedTrip (that remounts Step 3).
        tripRef.current = {
          ...tripRef.current,
          updatedAt: saved.updatedAt ?? tripRef.current.updatedAt,
          version: saved.version ?? tripRef.current.version,
        };
        setSavedTrip((prev) => ({
          ...prev,
          updatedAt: saved.updatedAt ?? prev.updatedAt,
          version: saved.version ?? prev.version,
        }));
      } else {
        applySavedTrip(saved);
      }
      return true;
    } catch (error) {
      if (!silent && (step === "farm" || step === "pickup" || step === "start" || step === "expenses")) {
        notifyRef.current?.(handleApiError(error), "error");
      } else if (!silent) {
        console.error(`Unable to save ${label.toLowerCase()} details:`, error);
      }
      return false;
    } finally {
      releaseOperationLock(lockKey);
      if (!silent) setHeaderLoading(false);
    }
  };

  const saveStartProgress = (data: Partial<Trip> = {}, opts?: { silent?: boolean }) =>
    saveStepProgress("start", data, opts);
  const saveFarmProgress = (data: Partial<Trip> = {}, opts?: { silent?: boolean }) =>
    saveStepProgress("farm", data, opts);
  const savePickupProgress = (data: Partial<Trip> = {}, opts?: { silent?: boolean }) =>
    saveStepProgress("pickup", data, opts);
  const saveDeliveriesProgress = async (
    rows: ShopDelivery[],
    opts: { silent?: boolean; changedRow?: ShopDelivery } = {}
  ): Promise<ShopDelivery[] | null> => {
    const silent = Boolean(opts.silent);
    const current = tripRef.current;
    if (!current.id) {
      if (!silent) notifyRef.current?.(translate("ops.trip.trip_id_missing"), "error");
      return null;
    }
    // The per-shop endpoint is an upsert, not a full replacement. During an
    // Add/Edit save send only that delivery: an unrelated historical row may
    // temporarily be out of sync after Step 3 boxes are corrected and must
    // not block persistence of the shop the user is currently editing.
    const rowsToSave = opts.changedRow ? [opts.changedRow] : rows;
    const withKeys = rowsToSave.map((row) => ({
      ...row,
      clientKey:
        row.clientKey ||
        (typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : `ck-${row.id}`),
    }));
    const lockKey = silent ? "save-silent:deliveries" : "save:deliveries";
    if (!acquireOperationLock(lockKey)) return null;
    // Silent background saves must never flash header loading or remount forms.
    if (!silent) setHeaderLoading(true);
    try {
      const saved = await saveTripDeliveries(current.id, { ...current, deliveries: withKeys });
      if (silent) {
        tripRef.current = {
          ...tripRef.current,
          updatedAt: saved.updatedAt ?? tripRef.current.updatedAt,
          version: saved.version ?? tripRef.current.version,
        };
        setSavedTrip((prev) => ({
          ...prev,
          updatedAt: saved.updatedAt ?? prev.updatedAt,
          version: saved.version ?? prev.version,
        }));
      } else {
        applySavedTrip(saved);
      }
      // Return the database-authoritative rows. Besides reflecting server-side
      // normalization, these contain the persisted id/clientKey identities
      // needed for the next shop edit to update rather than recreate a row.
      return saved.deliveries ?? withKeys;
    } catch (error) {
      if (!silent) notifyRef.current?.(handleApiError(error), "error");
      return null;
    } finally {
      releaseOperationLock(lockKey);
      if (!silent) setHeaderLoading(false);
    }
  };
  const saveEndProgress = (data: Partial<Trip> = {}, opts?: { silent?: boolean }) =>
    saveStepProgress("expenses", data, opts);

  /** Pickup edits stay in React state until Submit — no localStorage, no backend. */
  const updateBoxDetails = (
    rows: BoxDetail[],
    _persistToStorage: boolean = false,
    _silent: boolean = false
  ) => {
    void _persistToStorage;
    void _silent;
    const current = tripRef.current;
    const totals = calculatePickupTotals(rows);
    const updatedTrip: Trip = {
      ...current,
      boxDetails: rows,
      ...totals,
    };

    setTrip(updatedTrip);
    tripRef.current = updatedTrip;
    syncEndStep(updatedTrip);
  };

  const submitPickupStep = async (data: Partial<Trip> = {}): Promise<boolean> => {
    const current = tripRef.current;
    if (!current.id) {
      notifyRef.current?.(translate("ops.trip.trip_id_missing"), "error");
      return false;
    }

    const wasSubmitted = Boolean(current.pickupStepSubmitted);
    const updatedData = { ...current, ...data };
    const validation = validatePickupStep(updatedData as Trip);
    if (!validation.valid) {
      notifyRef.current?.(translateValidationMessage(translate, validation.errors[0]), "error");
      return false;
    }

    const lockKey = "submit:pickup";
    if (!acquireOperationLock(lockKey)) return false;
    setHeaderLoading(true);
    try {
      const submitted = await submitTripStep(current.id, "pickup", updatedData);
      applySavedTrip(submitted);
      notifyRef.current?.(translate("ops.trip.step3_submitted"), "success");
      if (!wasSubmitted) {
        onStep3SuccessRef.current?.(submitted);
      }
      return true;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return false;
    } finally {
      releaseOperationLock(lockKey);
      setHeaderLoading(false);
    }
  };

  /**
   * Submit Step 4. Returns `true` on success, or an error message string so the
   * Step 4 notice can show the same detail as the shell toast. Pending `[ORDER]`
   * plan stubs (Shops N) are ignored by validateDeliveriesStep.
   */
  const submitDeliveriesStep = async (): Promise<boolean | string> => {
    const current = tripRef.current;
    if (!current.id) {
      const msg = translate("ops.trip.trip_id_missing");
      notifyRef.current?.(msg, "error");
      return msg;
    }
    const wasSubmitted = Boolean(current.deliveryStepSubmitted);
    const validation = validateDeliveriesStep(current, current.deliveries ?? []);
    if (!validation.valid) {
      const msg =
        translateValidationMessage(translate, validation.errors[0] || "") ||
        translate("ops.trip.failed_submit_delivery");
      notifyRef.current?.(msg, "error");
      return msg;
    }

    const lockKey = "submit:deliveries";
    if (!acquireOperationLock(lockKey)) return false;
    setHeaderLoading(true);
    try {
      const submitted = await submitTripStep(current.id, "deliveries", current);
      // Updating Load 1 must remain on Load 1 even when the backend identifies
      // Load 2 as the next workflow target. Overlay the authoritative returned
      // Load 1 data while preserving the operator's current selection.
      const selectedLegIndex = Number(current.activeLegIndex ?? 1);
      const submittedOnSelectedLeg = withActiveTripLeg(submitted, selectedLegIndex);
      applySavedTrip(submittedOnSelectedLeg);
      notifyRef.current?.(translate("ops.trip.step4_submitted"), "success");
      if (!wasSubmitted) {
        onStep4SuccessRef.current?.(submittedOnSelectedLeg);
      }
      return true;
    } catch (error) {
      const message = handleApiError(error);
      const apiErr = error as { status?: number; code?: string };
      const msg =
        apiErr?.code === "NETWORK_ERROR" || message.toLowerCase().includes("unable to reach")
          ? translate("ops.trip.unable_to_connect")
          : message || translate("ops.trip.failed_submit_delivery");
      notifyRef.current?.(msg, "error");
      return msg;
    } finally {
      releaseOperationLock(lockKey);
      setHeaderLoading(false);
    }
  };

  const updateTrip = (updates: Partial<Trip>) => {
    setTrip((prev) => {
      const next = { ...prev, ...updates };
      tripRef.current = next;
      return next;
    });
    if (updates.endStepSubmitted !== undefined) {
      setEndStepSubmitted(updates.endStepSubmitted);
    }
  };

  const updateDeliveries = (rows: ShopDelivery[], _persistToStorage: boolean = false) => {
    void _persistToStorage;
    const updatedTrip = applyDeliveryMetrics(tripRef.current, rows);

    // Wizard edits stay in React state until Submit.
    setTrip(updatedTrip);
    tripRef.current = updatedTrip;
    syncEndStep(updatedTrip);
  };

  const submitEndTrip = async (data: Partial<Trip> = {}): Promise<boolean> => {
    const current = { ...tripRef.current, ...data };
    if (!current.id) {
      notifyRef.current?.(translate("ops.trip.trip_id_missing"), "error");
      return false;
    }
    if (!current.deliveryStepSubmitted) {
      // Part H: Step 5 stays openable and Save Progress works before Step 4,
      // but the FINAL submit is gated on Step 4 with a specific message.
      notifyRef.current?.(
        translate("ops.trip.step4_not_submitted"),
        "error"
      );
      return false;
    }

    const endValidation = validateEndStep(current);
    if (!endValidation.valid) {
      return false;
    }

    const closingMeter = Number(
      current.closingMeter || (current as Trip & { endMeter?: number }).endMeter || 0
    );
    const totalKm = closingMeter - (current.openingMeter || 0);

    const lockKey = "submit:expenses";
    if (!acquireOperationLock(lockKey)) return false;
    setHeaderLoading(true);
    try {
      const submitted = await submitTripStep(current.id, "expenses", {
        ...current,
        closingMeter,
        totalKm,
        endTime: current.endTime || new Date().toLocaleString(),
        status: "Pending" as TripStatus,
        endStepSubmitted: true,
        expensesStepSubmitted: true,
      });
      // Step 5 final submit always lands as Pending (never Completed, never stay Draft).
      applySavedTrip({ ...submitted, status: "Pending" as TripStatus });
      setEndStepSubmitted(true);
      notifyRef.current?.(translate("ops.trip.step5_submitted"), "success");
      return true;
    } catch (error) {
      console.error("Unable to submit end details:", error);
      const wrapped = new Error(handleApiError(error));
      (wrapped as Error & { cause?: unknown }).cause = error;
      throw wrapped;
    } finally {
      releaseOperationLock(lockKey);
      setHeaderLoading(false);
    }
  };

  const loadTrip = (tripToLoad: Trip) => {
    const normalized = {
      ...tripToLoad,
      helpers: tripToLoad.helpers || [],
      deliveries: tripToLoad.deliveries || [],
      boxDetails: tripToLoad.boxDetails || [],
    };
    setTrip(normalized);
    setSavedTrip(normalized);
    tripRef.current = normalized;
    setIsEditing(true);
    setEndStepSubmitted(tripToLoad.endStepSubmitted === true);
  };

  const clearTrip = () => {
    const fresh = emptyTrip();
    setTrip(fresh);
    setSavedTrip(fresh);
    tripRef.current = fresh;
    setIsEditing(false);
    setEndStepSubmitted(false);
  };

  /** Overlay a load's Farm/Pickup/Delivery fields onto the working trip. */
  const selectLeg = useCallback((legIndex: number) => {
    const requestSeq = selectLegRequestSeqRef.current + 1;
    selectLegRequestSeqRef.current = requestSeq;
    setTrip((prev) => {
      const next = withActiveTripLeg(prev, legIndex);
      tripRef.current = next;
      return next;
    });
    const tripId = tripRef.current.id;
    if (tripId > 0) {
      void loadTripById(tripId, legIndex)
        .then((loaded) => {
          if (requestSeq !== selectLegRequestSeqRef.current) return;
          const selectedLoad = withActiveTripLeg(loaded, legIndex);
          setTrip(selectedLoad);
          setSavedTrip(selectedLoad);
          tripRef.current = selectedLoad;
        })
        .catch((error) => {
          if (requestSeq === selectLegRequestSeqRef.current) {
            notifyRef.current?.(handleApiError(error), "error");
          }
        });
    }
  }, []);

  const addAnotherLoad = useCallback(async (): Promise<boolean> => {
    const current = tripRef.current;
    if (!current.id) {
      notifyRef.current?.(translate("ops.trip.trip_id_missing"), "error");
      return false;
    }
    const lockKey = "add:leg";
    if (!acquireOperationLock(lockKey)) return false;
    setHeaderLoading(true);
    try {
      const { addTripLeg } = await import("../services/tripHeaderApiService");
      const updated = await addTripLeg(current.id);
      applySavedTrip(updated);
      const nextIndex = Number(updated.activeLegIndex ?? updated.legCount ?? 1);
      // Overlay the new empty load onto the working copy.
      const leg = updated.legs?.find((l) => l.legIndex === nextIndex);
      if (leg) {
        const overlaid: Trip = {
          ...updated,
          activeLegIndex: nextIndex,
          sourceFarmId: 0,
          sourceFarm: "",
          destMeter: 0,
          pickupTolls: 0,
          farmAddress: "",
          avgBirdWeight: 0,
          birdTypeId: 0,
          birdType: "",
          farmStepSubmitted: false,
          pickupStepSubmitted: false,
          deliveryStepSubmitted: false,
          boxDetails: [],
          deliveries: [],
          dcWeight: 0,
          totalBirds: 0,
          boxes: 0,
        };
        setTrip(overlaid);
        setSavedTrip(overlaid);
        tripRef.current = overlaid;
      }
      onTripsChangedRef.current?.();
      notifyRef.current?.(`Load ${nextIndex} started — same vehicle & crew`, "success");
      return true;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return false;
    } finally {
      releaseOperationLock(lockKey);
      setHeaderLoading(false);
    }
  }, []);

  const closeEmptyLoad = useCallback(async (): Promise<boolean> => {
    const current = tripRef.current;
    const legIndex = Number(current.activeLegIndex ?? current.legCount ?? 1);
    if (!current.id || legIndex <= 1) return false;
    const lockKey = "remove:leg";
    if (!acquireOperationLock(lockKey)) return false;
    setHeaderLoading(true);
    try {
      const { removeEmptyTripLeg } = await import("../services/tripHeaderApiService");
      const updated = await removeEmptyTripLeg(current.id, legIndex);
      applySavedTrip(updated);
      notifyRef.current?.(`Load ${legIndex} closed`, "success");
      onTripsChangedRef.current?.();
      return true;
    } catch (error) {
      notifyRef.current?.(handleApiError(error), "error");
      return false;
    } finally {
      releaseOperationLock(lockKey);
      setHeaderLoading(false);
    }
  }, []);

  return {
    trip,
    savedTrip,
    setTrip,
    isEditing,
    setIsEditing,
    endStepSubmitted,
    headerLoading,
    subscribeHeaderSaveStatus,
    getHeaderSaveStatus,
    updateTrip,
    updateDeliveries,
    updateBoxDetails,
    submitStartStep,
    updateStartStep,
    saveStartProgress,
    submitFarmStep,
    saveFarmProgress,
    submitPickupStep,
    savePickupProgress,
    submitDeliveriesStep,
    saveDeliveriesProgress,
    submitEndTrip,
    saveEndProgress,
    loadTrip,
    loadTripFromApi,
    clearTrip,
    setStartTrip,
    updateStartTrip,
    selectLeg,
    addAnotherLoad,
    closeEmptyLoad,
    registerTripIdCallback,
    registerStep1SuccessCallback,
    registerStep2SuccessCallback,
    registerStep3SuccessCallback,
    registerStep4SuccessCallback,
  };
}

