                    const typeLabel =
                      tx.type === "sale"
                        ? {
                            text: t("shop_ledger.tx_type.sale"),
                            color: "text-emerald-600",
                          }
                        : tx.type === "collection"
                          ? {
                              text: paymentMode
                                ? t("shop_ledger.tx_type.collection_mode", {
                                    mode: paymentMode,
                                  })
