                loadWord={cumulativeTipText.loadWord}
                totalLabel={cumulativeTipText.config[loadTip.metric].totalLabel}
                totalDisplay={cumulativeTipText.config[loadTip.metric].formatValue(
                  loadTip.metric === "birds" ? loadTip.row.birds
