          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredData.length === 0 ? (
              <tr><td colSpan={columns.length} className="py-8 text-center text-sm text-slate-500">No records found.</td></tr>
            ) : (
              filteredData.map((row: any, idx: number) => (
