// src/performance/memory.manager.ts

export class MemoryManager {
  private maxMemory = 50 * 1024 * 1024; // 50 MB

  isLowMemory(): boolean {
    const perf = performance as any; // ✅ Type assertion to any
    if (perf.memory) {
      return perf.memory.usedJSHeapSize > this.maxMemory * 0.8;
    }
    return false;
  }

  clearCache(): void {
    const keys = Object.keys(localStorage);
    keys.forEach((k) => {
      if (k.startsWith('dmr_cache_') || k.startsWith('dmr_temp_')) {
        localStorage.removeItem(k);
      }
    });
  }
}

export const memory = new MemoryManager();

// src/performance/performance.monitor.ts

export class PerformanceMonitor {
  private startTime: number = 0;

  start(): void {
    this.startTime = performance.now();
  }

  stop(): number {
    return performance.now() - this.startTime;
  }

  measure(operation: string): void {
    const duration = this.stop();
    if (duration > 200) {
      console.warn(`⚠️ Slow operation: ${operation} took ${duration.toFixed(2)}ms`);
    } else {
      console.log(`✅ ${operation} completed in ${duration.toFixed(2)}ms`);
    }
  }

  static memory(): string {
    const perf = performance as any; // ✅ Type assertion to any
    if (perf.memory) {
      return `${(perf.memory.usedJSHeapSize / 1024 / 1024).toFixed(2)} MB`;
    }
    return 'N/A';
  }
}

export const monitor = new PerformanceMonitor();

